// Content for Break the Cycle (node g65, Parent Layer, Chapter 8) — NEW v2 build to GDD 65 (mechanic-embodying),
// the EMOTIONAL CORE of the Parent Layer and the deepest Unlearn->Relearn beat in the app: we parent the way we
// were parented, until we choose not to. FIRMLY NON-SHAMING — it busts the PRACTICE, never the parent, and treats
// inherited patterns with compassion (most parents using harsh methods were raised that way). 84 researched,
// India-grounded scenarios across how-you-were-raised → discipline-differently → the-repair → calm-yourself →
// heal-your-wounds → tools-and-help, each encoded as one of the shared v2 play actions (strike-rewrite / branch /
// reflect / role-play / sort / match / spot) — no binary "tap the right card". Lead: strike-rewrite (bust the
// myth), branch (your move), reflect. Six modes: how you were raised (gently surface inherited patterns — keep the
// good, leave the harmful; the inheritance isn't destiny and questioning it isn't betrayal), discipline
// differently (positive, firm AND kind discipline that works; busts "a slap never hurt me", "fear equals respect",
// "positive means permissive", "shaming motivates"; physical punishment is harmful and ineffective), the repair
// (reconnecting after you snap or get it wrong — a clean apology that owns it without blaming the child; repair
// beats perfection), calm yourself (self-regulation, the gap between feeling and acting, knowing your triggers,
// stepping away safely to keep everyone safe when anger surges), heal your own wounds (unhealed pain resurfaces in
// parenting — tend it and seek support; NOT therapy), tools & help (a calm-down-before-you-react and repair
// toolkit, and routing). Care-sensitive and child-safety aware: promotes non-violent, evidence-based positive
// discipline and NEVER endorses hitting or shaming; routes a parent's deeper wounds to support (Tele-MANAS 14416)
// and, where patterns risk real harm to a child, to Be the Safe Adult (g69) and help — with warmth and never
// shame. Builds on Mind Matters (g38) and Bounce (g39) and the Unlearn->Relearn core. India: corporal punishment
// and shaming are still widely normalised and most parents using them were raised that way, so the node is
// compassionate and honest that change is hard, offering positive-discipline alternatives that actually work.
// gameId "break-the-cycle".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"bc-001","cat":"how-you-were-raised","type":"strike-rewrite","hook":"\"You parent the way you were parented, and there's nothing you can do about it.\"","myth":{"un":"You parent the way you were parented, and there's nothing you can do about it.","re":"We tend to repeat what we knew, but the inheritance isn't destiny; new patterns are genuinely learnable.","why":"Awareness is the first step to choosing differently."},"relearn":"You tend to parent as you were parented, but it isn't destiny; you can learn and choose new patterns.","persona":"Suresh","source":"not destiny"},
  {"id":"bc-002","cat":"how-you-were-raised","type":"reflect","hook":"Lensy: noticing a pattern you inherited isn't blaming anyone; it's the start of choosing what to keep and what to leave. Sit right?","prompt":"What do you think?","options":["Sits right","Keep some, leave some","Start of change"],"affirm":"Noticing inherited patterns, without blame, lets you keep the good ones and set down the ones that cause harm.","relearn":"Noticing what you inherited lets you choose what to keep and what to leave, without blame.","persona":"any","source":"keep or leave"},
  {"id":"bc-003","type":"sort","hook":"Sort: an inherited pattern worth keeping, or one worth gently leaving behind?","items":[{"id":"a","text":"Warmth, stories and showing up"},{"id":"b","text":"Hitting when angry"},{"id":"c","text":"Strong family bonds"},{"id":"d","text":"Shaming and harsh words"},{"id":"e","text":"Eating and praying together"},{"id":"f","text":"Ruling the house by fear"}],"bins":[{"id":"keep","label":"Worth keeping","valence":"pos"},{"id":"leave","label":"Worth leaving","valence":"neg"}],"key":{"a":"keep","b":"leave","c":"keep","d":"leave","e":"keep","f":"leave"},"relearn":"Warmth, bonds and showing up are worth keeping; hitting and shaming are patterns worth gently leaving behind.","persona":"any","source":"keep vs leave","cat":"how-you-were-raised"},
  {"id":"bc-004","cat":"how-you-were-raised","type":"strike-rewrite","hook":"\"If I question how my parents raised me, I'm betraying or disrespecting them.\"","myth":{"un":"If I question how my parents raised me, I'm betraying or disrespecting them.","re":"You can love and honour your parents and still choose to do some things differently; that's growth, not betrayal.","why":"Doing better isn't a verdict on them."},"relearn":"You can honour your parents and still parent differently; choosing new ways is growth, not betrayal.","persona":"Suresh","source":"not betrayal"},
  {"id":"bc-005","cat":"how-you-were-raised","type":"branch","hook":"You catch yourself about to repeat a harsh thing your own parent did.","options":[{"text":"Pause and ask whether this is the parent you want to be","consequence":"You interrupt the pattern in the moment.","outcome":"interrupt","best":true},{"text":"Run on autopilot because it's familiar","consequence":"Running on autopilot passes the pattern to the next generation."}],"debrief":"When an old harsh pattern rises, pause and ask if it's the parent you want to be, rather than autopilot.","relearn":"Pause and choose when an inherited pattern rises; autopilot just passes it on.","persona":"Suresh","source":"interrupt the pattern"},
  {"id":"bc-006","type":"match","hook":"Match each inherited message to the truer one to raise your child on.","pairs":[{"left":"'Children should be seen, not heard'","right":"Your voice and feelings matter"},{"left":"'Fear keeps kids in line'","right":"Respect grows from trust, not fear"},{"left":"'Affection spoils them'","right":"Warmth makes children stronger"},{"left":"'Crying is weakness'","right":"Feelings are safe to show here"},{"left":"'A slap is just discipline'","right":"Calm limits teach better than pain"}],"relearn":"Each harsh inherited message has a truer one, voice matters, respect from trust, warmth strengthens, to pass on instead.","persona":"any","source":"truer messages","cat":"how-you-were-raised"},
  {"id":"bc-007","cat":"how-you-were-raised","type":"reflect","hook":"Lensy: most parents who were raised harshly aren't bad people; they're carrying what they were handed. Compassion for that?","prompt":"What's your take?","options":["Compassion","They carried it too","I get it"],"affirm":"Most parents who use harsh methods are repeating what they were handed; understanding that, without excusing harm, is where change starts.","relearn":"Most who parent harshly are carrying what they were handed; compassion for that is where change begins.","persona":"Suresh","source":"compassion"},
  {"id":"bc-008","type":"spot","hook":"Spot the two unhealthy ways of handling your own upbringing.","scene":[{"id":"a","text":"Keeping the good, gently leaving the harmful","trick":false},{"id":"b","text":"Repeating it all unquestioned","trick":true},{"id":"c","text":"Choosing your own patterns with care","trick":false},{"id":"d","text":"Insisting nothing about it can change","trick":true},{"id":"e","text":"Honouring your parents while doing things differently","trick":false}],"why":"\"Repeating it all unquestioned\" and \"nothing can change\" pass on the harm; keeping the good and choosing your own way is healthy.","relearn":"Handle your upbringing by keeping the good and choosing your own patterns, not repeating it unquestioned.","persona":"any","source":"healthy handling","cat":"how-you-were-raised"},
  {"id":"bc-009","cat":"how-you-were-raised","type":"branch","hook":"You feel guilt and grief realising how you were raised, and it's heavy.","options":[{"text":"Let yourself feel it, with compassion, and use it to fuel change","consequence":"The pain becomes motivation, not shame.","outcome":"fuel","best":true},{"text":"Bury it and carry on as before","consequence":"Burying it leaves the old patterns running unexamined."}],"debrief":"Let the grief of how you were raised be felt with compassion and turned into motivation, not buried.","relearn":"Feel the grief with compassion and let it fuel change, rather than burying it and repeating the past.","persona":"Suresh","source":"feel then fuel"},
  {"id":"bc-010","cat":"how-you-were-raised","type":"reflect","hook":"Lensy: you get to decide what stops with you, and that decision is a gift to your child. Feel the weight?","prompt":"What do you think?","options":["Feel it","Stops with me","A gift"],"affirm":"Deciding what harmful patterns stop with you is a profound gift to your child and the generations after.","relearn":"You decide what stops with you, and that decision is a gift to your child.","persona":"any","source":"stops with me"},
  {"id":"bc-011","cat":"discipline-differently","type":"strike-rewrite","hook":"\"A slap never hurt me, and hitting is just normal discipline.\"","myth":{"un":"A slap never hurt me, and hitting is just normal discipline.","re":"Evidence is clear that physical punishment harms children and doesn't work; it raises aggression and problems, not good behaviour.","why":"Common doesn't mean harmless or effective."},"relearn":"Physical punishment harms children and doesn't improve behaviour; it's common, but neither safe nor effective.","persona":"Suresh","source":"hitting harms"},
  {"id":"bc-012","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Fear equals respect; a child who fears you will behave.\"","myth":{"un":"Fear equals respect; a child who fears you will behave.","re":"Fear gets short-term compliance but teaches hiding and resentment; real respect grows from trust and clear, kind limits.","why":"Fear and respect are not the same thing."},"relearn":"Fear isn't respect; it teaches hiding and resentment, while real respect grows from trust and kind, firm limits.","persona":"Suresh","source":"fear isn't respect"},
  {"id":"bc-013","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Positive discipline means being permissive and having no rules.\"","myth":{"un":"Positive discipline means being permissive and having no rules.","re":"Positive discipline is firm and kind: clear boundaries and consequences held with warmth, not harshness, work better.","why":"Firm plus kind beats harsh or soft."},"relearn":"Positive discipline is firm and kind, clear limits held with warmth, not permissiveness and not harshness.","persona":"Vikram","source":"firm and kind"},
  {"id":"bc-014","cat":"discipline-differently","type":"sort","hook":"Sort: positive, effective discipline, or fear-based punishment?","items":[{"id":"a","text":"A calm, clear consequence"},{"id":"b","text":"Hitting or slapping"},{"id":"c","text":"Naming the limit and the reason"},{"id":"d","text":"Shaming or humiliating"},{"id":"e","text":"Staying warm while holding the rule"},{"id":"f","text":"Threatening to abandon them"}],"bins":[{"id":"positive","label":"Positive discipline","valence":"pos"},{"id":"fear","label":"Fear-based","valence":"neg"}],"key":{"a":"positive","b":"fear","c":"positive","d":"fear","e":"positive","f":"fear"},"relearn":"Calm consequences, explained limits and warmth are positive discipline; hitting, shaming and abandonment threats are fear-based and harmful.","persona":"any","source":"positive vs fear"},
  {"id":"bc-015","cat":"discipline-differently","type":"branch","hook":"Your child does something that makes your hand itch to smack.","options":[{"text":"Pause, breathe, and choose a firm-but-calm consequence instead","consequence":"You discipline without harming, and it works better.","outcome":"calm-limit","best":true},{"text":"Smack them like you would have been smacked","consequence":"Smacking repeats the cycle and harms the child."}],"debrief":"When the urge to smack rises, use a firm, calm consequence instead; it works better and breaks the cycle.","relearn":"Pause and use a calm consequence rather than smacking; it disciplines without harm and ends the cycle.","persona":"Suresh","source":"calm consequence"},
  {"id":"bc-016","cat":"discipline-differently","type":"match","hook":"Match each misbehaviour to a positive-discipline response.","pairs":[{"left":"A tantrum","right":"Stay calm, name the feeling, hold the limit"},{"left":"Breaking a rule","right":"A clear, related consequence, explained"},{"left":"Hitting a sibling","right":"Stop it firmly, teach the better choice"},{"left":"Lying about something","right":"Make truth safe, set a fair consequence"},{"left":"Refusing to cooperate","right":"Offer a small choice within the limit"}],"relearn":"Tantrums, broken rules, hitting, lying and refusing each have a firm, kind, teaching response — no fear or pain required.","persona":"Vikram","source":"positive responses"},
  {"id":"bc-017","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Shaming a child, calling them stupid or bad, motivates them to improve.\"","myth":{"un":"Shaming a child, calling them stupid or bad, motivates them to improve.","re":"Shaming damages a child's self-worth and bond with you; it discourages, it doesn't motivate.","why":"Shame wounds; it doesn't teach."},"relearn":"Shaming a child damages their self-worth and your bond; it discourages rather than motivates.","persona":"Suresh","source":"shame doesn't teach"},
  {"id":"bc-018","cat":"discipline-differently","type":"reflect","hook":"Lensy: discipline means to teach, not to punish or frighten. Does that reframe land?","prompt":"What do you think?","options":["It lands","Teach not frighten","Reframed"],"affirm":"Discipline at its root means to teach; the goal is a child who learns, not one who fears.","relearn":"Discipline means to teach, not to punish or frighten; that reframe changes everything.","persona":"any","source":"teach not frighten"},
  {"id":"bc-019","cat":"discipline-differently","type":"spot","hook":"Spot the two 'discipline' moves that harm instead of building good behaviour.","scene":[{"id":"a","text":"Clear, calm, consistent limits","trick":false},{"id":"b","text":"Hitting and yelling to instil fear","trick":true},{"id":"c","text":"Warmth alongside firm boundaries","trick":false},{"id":"d","text":"Shaming the child until they comply","trick":true},{"id":"e","text":"Explaining the reason behind the rule","trick":false}],"why":"Hitting-to-instil-fear and shaming wound a child and don't build behaviour; calm limits, warmth and explained reasons do.","relearn":"Hitting to instil fear and shaming don't build behaviour; clear calm limits, warmth and explained reasons do.","persona":"any","source":"builds behaviour"},
  {"id":"bc-020","cat":"discipline-differently","type":"branch","hook":"Family insist you must beat your child or they'll be 'spoiled'.","options":[{"text":"Hold your non-violent line, kindly but firmly","consequence":"You protect your child and your values.","outcome":"hold","best":true},{"text":"Give in to family pressure and hit","consequence":"Holding the non-violent line protects your child; giving in to pressure passes on harm you've chosen to end."}],"debrief":"Hold your non-violent discipline line against family pressure; protecting your child matters more than the old norm.","relearn":"Hold firm on non-violence despite pressure; your child's safety outranks 'spoiling' fears.","persona":"Suresh","source":"hold the line"},
  {"id":"bc-021","cat":"discipline-differently","type":"reflect","hook":"Lensy: the parents kids feel safest with are firm and warm, not frightening. Worth aiming for?","prompt":"What's your take?","options":["Worth it","Firm and warm","Aiming there"],"affirm":"Children feel safest and behave best with parents who are both firm and warm, not frightening.","relearn":"The parents kids feel safest with are firm and warm, not frightening; that's the aim.","persona":"any","source":"firm and warm"},
  {"id":"bc-022","cat":"the-repair","type":"strike-rewrite","hook":"\"If I lost my temper with my child, I've ruined everything and I'm a bad parent.\"","myth":{"un":"If I lost my temper with my child, I've ruined everything and I'm a bad parent.","re":"Every parent slips; what matters most is the repair afterward, reconnecting and making it right, which children remember.","why":"Repair, not perfection, builds secure kids."},"relearn":"Slipping doesn't make you a bad parent; the repair afterward is what counts and what children remember.","persona":"Divya","source":"repair not perfection"},
  {"id":"bc-023","cat":"the-repair","type":"branch","hook":"You snapped and yelled at your child, and you feel awful.","options":[{"text":"Go back, own it, and reconnect once you're both calm","consequence":"Your child learns that ruptures get repaired.","outcome":"repair","best":true},{"text":"Pretend it didn't happen to avoid the discomfort","consequence":"Pretending it away leaves the hurt and models avoidance."}],"debrief":"After you snap, go back, own it and reconnect when calm; repair is what your child remembers and learns.","relearn":"Repair after a snap by owning it and reconnecting; pretending it didn't happen leaves the hurt unhealed.","persona":"Suresh","source":"go back and repair"},
  {"id":"bc-024","cat":"the-repair","type":"role-play","hook":"You want to apologise to your child after losing your temper, without excuses. You say:","setup":"Apologise simply:","yourLine":[{"text":"\"I'm sorry I shouted, that wasn't okay and it wasn't your fault, I love you and I'll do better.\"","best":true},{"text":"\"I only shouted because you made me angry.\""}],"relearn":"A clean apology, owning it without blaming the child, repairs the bond and models accountability.","persona":"Suresh","source":"clean apology"},
  {"id":"bc-025","cat":"the-repair","type":"strike-rewrite","hook":"\"Apologising to a child makes you lose authority.\"","myth":{"un":"Apologising to a child makes you lose authority.","re":"Apologising models honesty and respect and actually strengthens your bond and your authority, not weakens it.","why":"Owning a mistake earns respect."},"relearn":"Apologising to your child models respect and strengthens your bond and authority; it doesn't weaken them.","persona":"Vikram","source":"apology builds authority"},
  {"id":"bc-026","cat":"the-repair","type":"match","persona":"any","source":"parts of repair","relearn":"Owning it, removing blame, reassuring safety, keeping the limit and reconnecting are the parts of a repair that restore a child's security.","hook":"Match each part of a good repair to what it gives the child.","pairs":[{"left":"Owning what you did","right":"Honesty modelled"},{"left":"Saying it's not their fault","right":"Their security restored"},{"left":"Reconnecting warmly","right":"The bond made whole again"},{"left":"Reassuring they're safe","right":"Their calm returns"},{"left":"Keeping the fair limit","right":"Boundaries still hold kindly"}]},
  {"id":"bc-027","cat":"the-repair","type":"reflect","hook":"Lensy: kids don't need perfect parents; they need parents who come back and make it right. Resonate?","prompt":"What do you think?","options":["Resonates","Come back","Not perfect"],"affirm":"Children don't need perfection; they need parents who repair, who come back and make a rupture right.","relearn":"Kids don't need perfect parents, just ones who come back and make it right.","persona":"any","source":"come back"},
  {"id":"bc-028","cat":"the-repair","type":"spot","persona":"any","source":"healthy repair","relearn":"A healthy repair owns it and reconnects warmly; blaming the child or buying them off instead of apologising is not repair.","hook":"Spot the two moves that look like repair but aren't.","scene":[{"id":"a","text":"A genuine apology and reconnection","trick":false},{"id":"b","text":"Blaming the child for your reaction","trick":true},{"id":"c","text":"Reassuring them they're loved","trick":false},{"id":"d","text":"Buying a treat instead of saying sorry","trick":true},{"id":"e","text":"Owning the slip without excuses","trick":false}],"why":"Blaming the child for your reaction and buying them off instead of apologising both skip the ownership a real repair needs."},
  {"id":"bc-029","cat":"the-repair","type":"branch","hook":"You worry that repairing after a slip is 'too late' to matter.","options":[{"text":"Repair anyway; it's almost never too late to reconnect","consequence":"You restore trust whenever you reach for it.","outcome":"never-late","best":true},{"text":"Skip it, deciding the moment has passed","consequence":"Repairing whenever you can restores trust; deciding it's too late leaves the rupture to harden needlessly."}],"debrief":"It's almost never too late to repair; reconnect whenever you can, not only in the perfect moment.","relearn":"Reach for repair even later; reconnection restores trust whenever it's offered.","persona":"Divya","source":"never too late"},
  {"id":"bc-030","cat":"the-repair","type":"reflect","hook":"Lensy: every repair teaches your child that love survives conflict, a priceless lesson. Worth it?","prompt":"What's your take?","options":["Worth it","Love survives conflict","Priceless"],"affirm":"Each repair teaches a child that love and connection survive conflict, one of the most valuable lessons there is.","relearn":"Every repair teaches your child that love survives conflict, a priceless thing to learn.","persona":"any","source":"love survives"},
  {"id":"bc-031","cat":"the-repair","type":"sort","persona":"any","source":"true vs false repair","relearn":"A clean sorry and warm reconnection truly repair; a blaming 'sorry but', ignoring it, a bribe or pressuring don't heal.","hook":"Sort: a true repair, or a false one that doesn't heal?","items":[{"id":"a","text":"\"I'm sorry, that wasn't okay\""},{"id":"b","text":"\"Sorry, but you made me do it\""},{"id":"c","text":"Warm reconnection after"},{"id":"d","text":"Acting like nothing happened"},{"id":"e","text":"\"It wasn't your fault, I love you\""},{"id":"f","text":"\"Forgive me right now, say it\""}],"bins":[{"id":"true","label":"True repair","valence":"pos"},{"id":"false","label":"Doesn't heal","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"}},
  {"id":"bc-032","cat":"calm-yourself","type":"strike-rewrite","hook":"\"If I'm furious, I can't help how I react to my child.\"","myth":{"un":"If I'm furious, I can't help how I react to my child.","re":"Strong feelings are valid, but there's a gap between feeling and acting, and you can learn to use it to choose your response.","why":"You can feel the anger and still choose the action."},"relearn":"Anger is valid, but there's a gap between feeling and acting; you can learn to pause and choose your response.","persona":"Suresh","source":"feeling vs acting"},
  {"id":"bc-033","cat":"calm-yourself","type":"branch","hook":"You feel your anger surging toward your child and worry you'll lash out.","options":[{"text":"If it's safe, step away to calm down before you respond","consequence":"You protect your child and reset yourself.","outcome":"step-away","best":true},{"text":"Stay in it and let the anger take over","consequence":"Staying in a surge of anger risks harm and regret."}],"debrief":"When anger surges toward your child, if it's safe, step away to calm down before responding.","relearn":"Step away to calm down when anger surges; protecting your child in that moment comes first.","persona":"Suresh","source":"step away to calm"},
  {"id":"bc-034","cat":"calm-yourself","type":"match","hook":"Match each calming tool to the moment it helps.","pairs":[{"left":"A few slow breaths","right":"The first rush of anger"},{"left":"Stepping into another room","right":"When you feel close to losing it"},{"left":"Naming your feeling silently","right":"Catching the surge early"},{"left":"Cool water on your face","right":"When heat is flushing your skin"},{"left":"Asking someone to tag in","right":"When you've nothing left to give"}],"relearn":"Slow breaths, a short step away, naming the feeling, cool water and a hand-off each help you ride out a surge without harm.","persona":"any","source":"calming tools"},
  {"id":"bc-035","cat":"calm-yourself","type":"strike-rewrite","hook":"\"Walking away from my child in anger means I'm a failure.\"","myth":{"un":"Walking away from my child in anger means I'm a failure.","re":"Stepping away to keep everyone safe is a responsible, strong move, not a failure; you can return calm.","why":"A safe pause is strength, not surrender."},"relearn":"Stepping away to stay safe and calm isn't failure; it's a responsible, strong move, and you return calmer.","persona":"Suresh","source":"stepping away is strong"},
  {"id":"bc-036","cat":"calm-yourself","type":"sort","hook":"Sort: a healthy way to handle your own anger, or one that risks harm?","items":[{"id":"a","text":"Breathing and a short pause"},{"id":"b","text":"Taking it out on the child"},{"id":"c","text":"Stepping away to cool down"},{"id":"d","text":"Bottling it until you explode"},{"id":"e","text":"Asking another adult to step in"},{"id":"f","text":"Grabbing or shaking in frustration"}],"bins":[{"id":"healthy","label":"Healthy regulation","valence":"pos"},{"id":"risk","label":"Risks harm","valence":"neg"}],"key":{"a":"healthy","b":"risk","c":"healthy","d":"risk","e":"healthy","f":"risk"},"relearn":"Breathing, stepping away and asking another adult in regulate anger safely; taking it out on the child, bottling it or grabbing risk harm.","persona":"any","source":"regulate vs risk"},
  {"id":"bc-037","cat":"calm-yourself","type":"branch","hook":"You notice the same situations keep triggering your temper.","options":[{"text":"Learn your triggers and plan a calm response in advance","consequence":"You meet the trigger ready, not blindsided.","outcome":"prepared","best":true},{"text":"Keep getting ambushed by the same flashpoints","consequence":"Ignoring your triggers leaves you ambushed every time."}],"debrief":"Learn the situations that trigger your temper and plan a calm response in advance.","relearn":"Spot your recurring triggers and plan a calm response, rather than being ambushed again and again.","persona":"Suresh","source":"know your triggers"},
  {"id":"bc-038","cat":"calm-yourself","type":"reflect","hook":"Lensy: the moment you notice you're escalating is the moment you get your power back. Make sense?","prompt":"What do you think?","options":["Makes sense","I get my power back","Notice and choose"],"affirm":"Noticing that you're escalating is the moment you regain the power to choose a different response.","relearn":"The moment you notice you're escalating is the moment you can choose differently.","persona":"any","source":"notice to choose"},
  {"id":"bc-039","cat":"calm-yourself","type":"spot","hook":"Spot the two red flags — the moves that make a heated moment more dangerous.","scene":[{"id":"a","text":"Pausing and breathing before reacting","trick":false},{"id":"b","text":"Reacting instantly from the anger","trick":true},{"id":"c","text":"Stepping away until you're calm","trick":false},{"id":"d","text":"Letting the shouting keep building","trick":true},{"id":"e","text":"Lowering your voice on purpose","trick":false}],"why":"Reacting instantly and letting the shouting build escalate the danger; pause, breath, distance and a soft voice keep it safe.","relearn":"Reacting straight from anger or letting a shout build makes a moment dangerous; pause, breath and distance keep it safe.","persona":"any","source":"keep it safe"},
  {"id":"bc-040","cat":"calm-yourself","type":"role-play","hook":"Your partner is escalating with your child and needs a gentle hand-off. You step in.","setup":"Step in gently:","yourLine":[{"text":"\"Hey, take a breather, I've got this one, we'll talk in a bit.\"","best":true},{"text":"\"What is wrong with you, calm down!\""}],"relearn":"A calm hand-off, take a breather, I've got this, defuses the moment far better than shouting at the parent too.","persona":"Vikram","source":"gentle hand-off"},
  {"id":"bc-041","cat":"calm-yourself","type":"reflect","hook":"Lensy: regulating yourself first is how you teach your child to regulate themselves. Worth practising?","prompt":"What's your take?","options":["Worth it","I model it","Practising"],"affirm":"When you regulate your own emotions, you model and teach your child how to regulate theirs.","relearn":"Regulating yourself first is how you teach your child to regulate themselves.","persona":"any","source":"model regulation"},
  {"id":"bc-042","cat":"heal-your-wounds","type":"strike-rewrite","hook":"\"My own childhood is in the past and has nothing to do with how I parent.\"","myth":{"un":"My own childhood is in the past and has nothing to do with how I parent.","re":"Unhealed wounds often resurface in parenting, in our triggers and reactions; tending them helps the cycle stop with you.","why":"The past leaks into the present until it's tended."},"relearn":"Unhealed childhood wounds often resurface in parenting; tending them helps the harmful cycle stop with you.","persona":"Suresh","source":"past leaks in"},
  {"id":"bc-043","cat":"heal-your-wounds","type":"reflect","hook":"Lensy: healing your own wounds isn't self-indulgence; it's how you protect your child from inheriting them. Resonate?","prompt":"What do you think?","options":["Resonates","Protects them","Worth tending"],"affirm":"Tending your own old wounds protects your child from inheriting them; it's a gift to them, not self-indulgence.","relearn":"Healing your own wounds protects your child from inheriting them; it's for them as much as you.","persona":"Suresh","source":"protect from inheriting"},
  {"id":"bc-044","type":"sort","persona":"any","source":"heal vs running","hook":"Sort: helps you heal and parent better, or keeps the wound running?","items":[{"id":"a","text":"Acknowledging what hurt you"},{"id":"b","text":"Insisting you're completely fine"},{"id":"c","text":"Seeking support for your past"},{"id":"d","text":"Numbing and never looking"},{"id":"e","text":"Letting yourself grieve it"},{"id":"f","text":"Snapping at your kids instead"}],"bins":[{"id":"heal","label":"Helps you heal","valence":"pos"},{"id":"running","label":"Keeps it running","valence":"neg"}],"key":{"a":"heal","b":"running","c":"heal","d":"running","e":"heal","f":"running"},"relearn":"Acknowledging the hurt, seeking support and grieving help you heal; insisting you're fine, numbing and snapping keep it running.","cat":"heal-your-wounds"},
  {"id":"bc-045","cat":"heal-your-wounds","type":"strike-rewrite","hook":"\"Getting help for my own past means I'm weak or broken.\"","myth":{"un":"Getting help for my own past means I'm weak or broken.","re":"Reaching for support to process your past is a strong, loving act, for yourself and for your child.","why":"Tending wounds is strength, not brokenness."},"relearn":"Getting help to process your past isn't weakness; it's a strong, loving act for you and your child.","persona":"Suresh","source":"help is strength"},
  {"id":"bc-046","cat":"heal-your-wounds","type":"branch","hook":"You realise some of your reactions come from pain you've never dealt with.","options":[{"text":"Gently seek support to work through it, a counsellor or helpline","consequence":"You tend the root, not just the symptom.","outcome":"tend-root","best":true},{"text":"Keep pushing it down and hope it stays buried","consequence":"Pushing it down keeps it leaking into your parenting."}],"debrief":"When old pain drives your reactions, gently seek support to work through it rather than pushing it down.","relearn":"Seek support for unhealed pain behind your reactions; burying it keeps it surfacing in your parenting.","persona":"Suresh","source":"tend the root"},
  {"id":"bc-047","type":"match","persona":"Suresh","source":"steps of healing","hook":"Match each step of healing to what it makes possible.","pairs":[{"left":"Naming what happened to you","right":"Understanding your triggers"},{"left":"Grieving and processing it","right":"Less of it leaking onto your child"},{"left":"Getting support (e.g. Tele-MANAS 14416)","right":"A real path through it"},{"left":"Being kind to your younger self","right":"The old self-blame easing"},{"left":"Choosing differently now","right":"The cycle stopping with you"}],"relearn":"Naming, processing, getting support and self-kindness are the steps that turn an old wound into something that stops with you.","cat":"heal-your-wounds"},
  {"id":"bc-048","cat":"heal-your-wounds","type":"reflect","hook":"Lensy: you can give your child the childhood you didn't have, and healing is how. Feel the hope in that?","prompt":"What's your take?","options":["Feel it","The hope","I can"],"affirm":"By tending your own wounds, you can give your child a childhood different from, and better than, your own.","relearn":"You can give your child the childhood you didn't have, and healing yourself is how.","persona":"Suresh","source":"the childhood you didn't have"},
  {"id":"bc-049","cat":"heal-your-wounds","type":"strike-rewrite","hook":"\"This game can heal my childhood trauma on its own.\"","myth":{"un":"This game can heal my childhood trauma on its own.","re":"This offers compassion and signposting, not therapy; deeper wounds deserve real professional support.","why":"Support tools point to care; they don't replace it."},"relearn":"This game supports and signposts but isn't therapy; deeper wounds deserve professional support.","persona":"any","source":"not therapy"},
  {"id":"bc-050","type":"spot","persona":"any","source":"stop with you","hook":"Spot the two moves that keep the cycle running instead of stopping it.","scene":[{"id":"a","text":"Tending your own old wounds","trick":false},{"id":"b","text":"Insisting the past doesn't matter","trick":true},{"id":"c","text":"Reaching for support when it's heavy","trick":false},{"id":"d","text":"Taking the old pain out on your kids","trick":true},{"id":"e","text":"Naming what happened, kindly","trick":false}],"why":"Denying the past and taking pain out on your kids keep the cycle alive; tending wounds, support and naming stop it with you.","relearn":"The cycle stops with you when you tend your wounds, seek support and name the past, not when you deny it or lash out.","cat":"heal-your-wounds"},
  {"id":"bc-051","cat":"heal-your-wounds","type":"reflect","hook":"Lensy: every wound you heal in yourself is one your child never has to carry. Sit right?","prompt":"What's your take?","options":["Sits right","One less to carry","For them"],"affirm":"Each wound you heal in yourself is one your child won't have to carry or pass on further.","relearn":"Every wound you heal in yourself is one your child never has to carry.","persona":"any","source":"one less to carry"},
  {"id":"bc-052","cat":"tools-and-help","type":"branch","hook":"You want something concrete to use in the heat of the moment.","options":[{"text":"Set a simple plan: pause, breathe, step away if needed, repair after","consequence":"You have a path ready before the storm.","outcome":"plan","best":true},{"text":"Rely on willpower alone when angry","consequence":"A simple ready plan gives you a path in the heat of the moment; willpower alone often fails mid-surge."}],"debrief":"Ready a simple plan, pause, breathe, step away if needed, repair after, for heated moments.","relearn":"Have a concrete pause-breathe-step-away-repair plan ready; willpower alone tends to fail mid-surge.","persona":"Suresh","source":"ready plan"},
  {"id":"bc-053","cat":"tools-and-help","type":"match","hook":"Match each tool to what it does.","pairs":[{"left":"The calm-down-before-you-react step","right":"Stops a harmful reaction"},{"left":"The repair routine","right":"Heals a rupture after"},{"left":"Support routes (Tele-MANAS 14416)","right":"Help for your own past"},{"left":"Knowing your own triggers","right":"Catches the old reflex early"},{"left":"A ready pause-plan","right":"A path in the heat of the moment"}],"relearn":"The calm-down step, the repair routine, support routes, knowing triggers and a ready plan are the core tools.","persona":"any","source":"the toolkit"},
  {"id":"bc-054","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Wanting to change but slipping sometimes means change is impossible for me.\"","myth":{"un":"Wanting to change but slipping sometimes means change is impossible for me.","re":"Change is gradual and slips are part of it; each pause, each repair, each calmer day is real progress.","why":"Progress isn't all-or-nothing."},"relearn":"Slipping while changing doesn't mean change is impossible; each pause and repair is real progress.","persona":"Suresh","source":"progress not perfection"},
  {"id":"bc-055","cat":"tools-and-help","type":"sort","hook":"Sort: a green-flag move for breaking the cycle, or one to rethink?","items":[{"id":"a","text":"Pausing before reacting"},{"id":"b","text":"Hitting when overwhelmed"},{"id":"c","text":"Repairing after a slip"},{"id":"d","text":"Shaming to control"},{"id":"e","text":"Reaching for support"},{"id":"f","text":"Threatening to keep them in line"}],"bins":[{"id":"green","label":"Green-flag move","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"green","b":"rethink","c":"green","d":"rethink","e":"green","f":"rethink"},"relearn":"Pausing, repairing and reaching for support are green-flag moves; hitting, shaming and threatening need a rethink.","persona":"any","source":"green or rethink"},
  {"id":"bc-056","cat":"tools-and-help","type":"branch","hook":"You're frightened that your anger could seriously hurt your child, or it already has.","options":[{"text":"Reach out for help now, to keep your child safe and get support","consequence":"You protect your child and find a way through.","outcome":"reach-now","best":true},{"text":"Stay silent in shame and hope it won't happen again","consequence":"Silence and shame leave the risk in place."}],"debrief":"If you fear your anger could harm your child, or it has, reach out for help now (see Be the Safe Adult).","relearn":"When anger risks real harm to your child, reach for help now; don't carry it alone.","persona":"Suresh","source":"reach for help now"},
  {"id":"bc-057","cat":"tools-and-help","type":"reflect","hook":"Lensy: needing help to parent gently isn't shameful; it's the most caring thing you can do for your child. Hear that?","prompt":"What do you think?","options":["I hear it","Most caring","Not shameful"],"affirm":"Reaching for help to parent more gently is a caring, courageous act, never a shameful one.","relearn":"Needing help to parent gently isn't shameful; it's one of the most caring things you can do.","persona":"any","source":"not shameful"},
  {"id":"bc-058","cat":"tools-and-help","type":"match","hook":"Match a parent's need to where it routes.","pairs":[{"left":"Help regulating anger and discipline","right":"Positive-parenting support"},{"left":"Processing your own past","right":"A counsellor or Tele-MANAS 14416"},{"left":"A child at risk of harm","right":"Be the Safe Adult (g69)"},{"left":"A child in immediate danger","right":"Childline 1098"},{"left":"A life-threatening emergency","right":"Emergency 112"}],"relearn":"Anger help, support for your past, and child-safety routing each have a clear place to turn.","persona":"Suresh","source":"where it routes"},
  {"id":"bc-059","cat":"tools-and-help","type":"spot","hook":"Spot the two ideas that aren't a sustainable way to break the cycle.","scene":[{"id":"a","text":"Small, consistent changes and self-compassion","trick":false},{"id":"b","text":"Expecting to be perfect overnight","trick":true},{"id":"c","text":"Pausing, repairing, healing over time","trick":false},{"id":"d","text":"Quitting the moment you slip","trick":true},{"id":"e","text":"Counting each calmer day as progress","trick":false}],"why":"Expecting overnight perfection and quitting at a slip aren't sustainable; small consistent changes, self-compassion and counting calmer days are.","relearn":"Break the cycle through small consistent changes and self-compassion over time, not overnight perfection.","persona":"any","source":"sustainable change"},
  {"id":"bc-060","cat":"tools-and-help","type":"reflect","hook":"Lensy: notice the pattern, discipline with warmth, repair your slips, heal your wounds, and reach for help. The cycle ends with you. Ready?","prompt":"What's your take?","options":["Ready","It ends with me","Let's go"],"affirm":"Noticing patterns, disciplining warmly, repairing, healing and reaching for help are how the harmful cycle ends with you.","relearn":"Notice the pattern, discipline warmly, repair, heal, and reach for help, and the cycle ends with you.","persona":"any","source":"ends with me"},
  {"id":"bc-061","cat":"tools-and-help","type":"role-play","hook":"Your co-parent grew up with harsh discipline and defaults to it. You want to invite change together.","setup":"Invite change together:","yourLine":[{"text":"\"We were both raised with that, but let's choose differently for our kid, and back each other up.\"","best":true},{"text":"\"You're just like your father, you'll never change.\""}],"relearn":"Inviting change together, with compassion for your shared upbringing, motivates a co-parent far more than condemnation.","persona":"Vikram","source":"invite change together"},
  {"id":"bc-062","cat":"how-you-were-raised","type":"role-play","hook":"A relative says you're 'soft' for not raising your kids the strict way you were raised. You answer with calm conviction.","setup":"Answer with conviction:","yourLine":[{"text":"\"I loved a lot about my childhood, and I'm choosing to do some things differently, kindly and firmly.\"","best":true},{"text":"\"You're right, maybe I should be harder on them.\""}],"relearn":"Owning what you keep and what you change, calmly, holds your new path without attacking your own parents.","persona":"Suresh","source":"calm conviction"},
  {"id":"bc-063","type":"sort","hook":"Sort: a compassionate truth about inherited parenting, or a shaming one?","items":[{"id":"a","text":"'Most harsh parents were raised that way'"},{"id":"b","text":"'Anyone who slips is a monster'"},{"id":"c","text":"'You can choose differently now'"},{"id":"d","text":"'You're doomed to repeat it'"},{"id":"e","text":"'Noticing the pattern is real progress'"},{"id":"f","text":"'One bad day means you've failed'"}],"bins":[{"id":"compassion","label":"Compassionate truth","valence":"pos"},{"id":"shame","label":"Shaming","valence":"neg"}],"key":{"a":"compassion","b":"shame","c":"compassion","d":"shame","e":"compassion","f":"shame"},"relearn":"'Most were raised that way' and 'you can choose now' are compassionate; 'monster' and 'doomed' are shaming and false.","persona":"any","source":"compassion vs shame","cat":"how-you-were-raised"},
  {"id":"bc-064","type":"match","hook":"Match each thing to keep or leave to the reason.","pairs":[{"left":"Keep: family closeness","right":"It nourished you"},{"left":"Leave: hitting","right":"It harms and doesn't work"},{"left":"Keep: hard work","right":"A value worth passing on"},{"left":"Leave: shaming","right":"It wounds a child's self-worth"},{"left":"Keep: showing up","right":"It built your sense of safety"}],"relearn":"Sorting your inheritance, keep the closeness and values, leave the harm, lets you pass on the best of it.","persona":"any","source":"keep-leave reasons","cat":"how-you-were-raised"},
  {"id":"bc-065","type":"spot","hook":"Spot the two mindsets that keep the old pattern running.","scene":[{"id":"a","text":"'I can learn new ways'","trick":false},{"id":"b","text":"'This is just who I am, unchangeable'","trick":true},{"id":"c","text":"'I choose what stops with me'","trick":false},{"id":"d","text":"'It's in my blood, nothing to be done'","trick":true},{"id":"e","text":"'I can keep the good and leave the rest'","trick":false}],"why":"'This is just who I am' and 'it's in my blood' keep the old pattern running; 'I can learn' and 'I choose what stops with me' help you change.","relearn":"Parenting differently starts with 'I can learn' and 'I choose what stops with me', not 'this is just who I am'.","persona":"Suresh","source":"growth mindset","cat":"how-you-were-raised"},
  {"id":"bc-066","cat":"discipline-differently","type":"role-play","hook":"Your child is melting down in public and you feel the old urge to grab and shout. You want to handle it calmly.","setup":"Stay calm and firm:","yourLine":[{"text":"\"I can see you're upset, we're going to take a breath together, and we still can't do that.\"","best":true},{"text":"\"Stop it right now or you'll get it when we get home.\""}],"relearn":"Naming the feeling while holding the limit calms a meltdown and disciplines without threats or fear.","persona":"Vikram","source":"calm in public"},
  {"id":"bc-067","cat":"discipline-differently","type":"sort","hook":"Sort: teaches the child a better choice, or just instils fear?","items":[{"id":"a","text":"Explaining why and what to do instead"},{"id":"b","text":"A slap to make them stop"},{"id":"c","text":"A calm, related consequence"},{"id":"d","text":"Yelling threats"},{"id":"e","text":"Offering a small choice within the limit"},{"id":"f","text":"Mocking until they comply"}],"bins":[{"id":"teaches","label":"Teaches a better choice","valence":"pos"},{"id":"fear","label":"Just instils fear","valence":"neg"}],"key":{"a":"teaches","b":"fear","c":"teaches","d":"fear","e":"teaches","f":"fear"},"relearn":"Explaining, calm consequences and a small choice teach a better choice; slaps, yelled threats and mockery only instil fear.","persona":"any","source":"teaches vs fear"},
  {"id":"bc-068","cat":"discipline-differently","type":"role-play","hook":"Your child asks why you don't hit them when their friends get hit at home. You want to answer honestly.","setup":"Answer honestly:","yourLine":[{"text":"\"Because hurting you would be wrong, and I can help you learn without ever needing to.\"","best":true},{"text":"\"Don't give me ideas, behave or else.\""}],"relearn":"Telling a child you'll never hurt them, and don't need to, builds trust and models non-violence directly.","persona":"Suresh","source":"why no hitting"},
  {"id":"bc-069","cat":"the-repair","type":"role-play","hook":"Hours after snapping, your child is still subdued. You want to reopen and repair gently.","setup":"Reopen gently:","yourLine":[{"text":"\"I've been thinking about earlier, I was wrong to shout, can we have a cuddle and start over?\"","best":true},{"text":"\"Are you still sulking about that? Let it go.\""}],"relearn":"Reopening with ownership and warmth repairs the rupture; dismissing the child's hurt deepens it.","persona":"Divya","source":"reopen and repair"},
  {"id":"bc-070","cat":"the-repair","type":"sort","persona":"any","source":"safe vs edge","relearn":"A sincere apology, warmth and reassurance help a child feel safe; ignoring it, blaming them or a cold spell keep them on edge.","hook":"Sort: helps a child feel safe again after a rupture, or keeps them on edge?","items":[{"id":"a","text":"A sincere apology"},{"id":"b","text":"Acting like nothing happened"},{"id":"c","text":"Extra warmth and reassurance"},{"id":"d","text":"Making them apologise for your outburst"},{"id":"e","text":"\"You're safe, I'm sorry I scared you\""},{"id":"f","text":"Going cold and silent for days"}],"bins":[{"id":"safe","label":"Helps them feel safe","valence":"pos"},{"id":"edge","label":"Keeps them on edge","valence":"neg"}],"key":{"a":"safe","b":"edge","c":"safe","d":"edge","e":"safe","f":"edge"}},
  {"id":"bc-071","cat":"the-repair","type":"branch","hook":"You slipped again after doing well for weeks and feel like giving up.","options":[{"text":"Repair, forgive yourself, and keep going, slips don't erase progress","consequence":"You stay on the path despite a stumble.","outcome":"keep-going","best":true},{"text":"Decide you've failed and abandon the effort","consequence":"Deciding you've failed abandons all the progress you've made."}],"debrief":"A slip after progress isn't failure; repair, forgive yourself and keep going.","relearn":"Treat a slip as a stumble, not the end; repair, self-forgive and continue rather than giving up.","persona":"Suresh","source":"slips don't erase"},
  {"id":"bc-072","cat":"the-repair","type":"match","persona":"any","source":"what makes repair land","relearn":"A repair lands when it owns the behaviour, frees the child of blame, restores the bond, keeps the limit and invites their feelings.","hook":"Match each repair phrase to what makes it land.","pairs":[{"left":"\"I was wrong to do that\"","right":"It owns the behaviour"},{"left":"\"It wasn't your fault\"","right":"It frees the child of blame"},{"left":"\"I love you, always\"","right":"It restores the bond"},{"left":"\"The rule still stands, though\"","right":"It keeps the limit firm"},{"left":"\"Tell me how that felt\"","right":"It invites their feelings"}]},
  {"id":"bc-073","cat":"calm-yourself","type":"role-play","hook":"You can feel yourself about to explode at your kids. You want to narrate a safe exit.","setup":"Narrate a safe exit:","yourLine":[{"text":"\"I'm getting too angry, I'm going to take a minute in the other room and come back calmer.\"","best":true},{"text":"\"That's it, I've had it with all of you!\""}],"relearn":"Narrating a calm exit models emotional honesty and keeps everyone safe, unlike erupting at the children.","persona":"Suresh","source":"narrate safe exit"},
  {"id":"bc-074","cat":"calm-yourself","type":"sort","hook":"Sort each one: a real self-regulation skill, or a way of feeding the anger?","items":[{"id":"a","text":"Slow breathing"},{"id":"b","text":"Replaying what enraged you"},{"id":"c","text":"A brief, safe time-out for yourself"},{"id":"d","text":"Clenching and pushing on"},{"id":"e","text":"Naming the feeling to settle it"},{"id":"f","text":"Muttering how unfair it all is"}],"bins":[{"id":"regulate","label":"Self-regulation","valence":"pos"},{"id":"feed","label":"Feeds the anger","valence":"neg"}],"key":{"a":"regulate","b":"feed","c":"regulate","d":"feed","e":"regulate","f":"feed"},"relearn":"Breathing, a brief self time-out and naming the feeling regulate anger; replaying the trigger, clenching on and muttering feed it.","persona":"any","source":"regulate vs feed"},
  {"id":"bc-075","cat":"calm-yourself","type":"branch","hook":"You realise you're most likely to snap when you're exhausted and overwhelmed.","options":[{"text":"Reduce the load and build in rest so you have more patience to give","consequence":"You shrink what causes the snaps.","outcome":"reduce-load","best":true},{"text":"Ignore your own state and rely on willpower","consequence":"Ignoring your state leaves you running on empty and short-fused."}],"debrief":"Notice that exhaustion and overwhelm fuel your snaps; reduce the load and rest to widen your patience.","relearn":"Tend your exhaustion and load to prevent snaps; willpower alone runs out when you're depleted.","persona":"Divya","source":"reduce the load"},
  {"id":"bc-076","cat":"calm-yourself","type":"spot","hook":"Spot the two red flags — responses to your warning signs that make things worse.","scene":[{"id":"a","text":"Pausing the moment your jaw clenches","trick":false},{"id":"b","text":"Telling yourself 'I can't stop now'","trick":true},{"id":"c","text":"Stepping back when your voice rises","trick":false},{"id":"d","text":"Pushing harder because you've started","trick":true},{"id":"e","text":"Breathing when your heart pounds","trick":false}],"why":"'I can't stop' and 'push harder' override the warning signs; pausing, stepping back and breathing heed them.","relearn":"Heed early-warning signs by pausing, stepping back and breathing; 'I can't stop' and 'push harder' override them.","persona":"Suresh","source":"early warning"},
  {"id":"bc-077","cat":"heal-your-wounds","type":"role-play","hook":"A friend admits they're scared they'll repeat their own harsh upbringing. You want to support them.","setup":"Support them warmly:","yourLine":[{"text":"\"The fact that you're worried about it means you're already breaking the pattern, and help is out there.\"","best":true},{"text":"\"Yeah, we all turn into our parents eventually.\""}],"relearn":"Affirming that their very worry means they're changing, plus pointing to help, supports a friend far more than fatalism.","persona":"Priya","source":"support a friend"},
  {"id":"bc-078","type":"sort","persona":"any","source":"stops vs passes","hook":"Sort: helps the cycle stop with you, or keeps passing it on?","items":[{"id":"a","text":"Tending your own wounds"},{"id":"b","text":"Pretending the past didn't shape you"},{"id":"c","text":"Seeking support for old pain"},{"id":"d","text":"Taking your pain out on your kids"},{"id":"e","text":"Repairing after you're triggered"},{"id":"f","text":"Expecting your child to soothe you"}],"bins":[{"id":"stops","label":"Stops with you","valence":"pos"},{"id":"passes","label":"Passes it on","valence":"neg"}],"key":{"a":"stops","b":"passes","c":"stops","d":"passes","e":"stops","f":"passes"},"relearn":"Tending wounds, seeking support and repairing stop the cycle; denying the past, lashing out and leaning on your child pass it on.","cat":"heal-your-wounds"},
  {"id":"bc-079","cat":"heal-your-wounds","type":"role-play","hook":"You want to acknowledge to yourself, kindly, that you were hurt as a child. You say it inwardly.","setup":"Say it kindly to yourself:","yourLine":[{"text":"\"What happened to me wasn't okay, it wasn't my fault, and I can choose something better now.\"","best":true},{"text":"\"It was nothing, I turned out fine, stop being dramatic.\""}],"relearn":"Acknowledging your own hurt with compassion, rather than dismissing it, is what lets you stop passing it on.","persona":"Suresh","source":"acknowledge kindly"},
  {"id":"bc-080","cat":"heal-your-wounds","type":"branch","hook":"Processing your past brings up more than you can handle alone.","options":[{"text":"Reach for a counsellor or helpline to walk through it with support","consequence":"You get real help for a heavy load.","outcome":"supported","best":true},{"text":"Force yourself to deal with it entirely alone","consequence":"Forcing it alone can overwhelm and stall your healing."}],"debrief":"When your past brings up more than you can handle alone, reach for a counsellor or helpline (e.g. Tele-MANAS 14416).","relearn":"Get support to process heavy past pain; you don't have to walk through it entirely alone.","persona":"Suresh","source":"not alone"},
  {"id":"bc-081","cat":"tools-and-help","type":"role-play","hook":"Your co-parent slipped and is spiralling in guilt. You want to steady them toward repair.","setup":"Steady them gently:","yourLine":[{"text":"\"You slipped, it happens to all of us, go repair it with them, that's what matters now.\"","best":true},{"text":"\"Great, now you've scarred them for life.\""}],"relearn":"Steadying a guilt-spiralling co-parent toward repair helps the child far more than piling on blame.","persona":"Vikram","source":"steady co-parent"},
  {"id":"bc-082","cat":"tools-and-help","type":"role-play","hook":"You want to set a shared family rule that no one, adult or child, hits when angry. You propose it.","setup":"Propose it clearly:","yourLine":[{"text":"\"In our home, none of us hits, not even when we're furious, we take a breath instead, all of us.\"","best":true},{"text":"\"Do as I say, not as I do.\""}],"relearn":"A shared no-hitting rule that applies to adults too models the very self-control you want your kids to learn.","persona":"Suresh","source":"shared family rule"},
  {"id":"bc-083","cat":"tools-and-help","type":"sort","hook":"Sort: a realistic plan for changing how you parent, or a setup to fail?","items":[{"id":"a","text":"One small change at a time"},{"id":"b","text":"Becoming a perfect parent overnight"},{"id":"c","text":"Self-compassion when you slip"},{"id":"d","text":"Quitting at the first relapse"},{"id":"e","text":"Counting your calmer days"},{"id":"f","text":"Shaming yourself for every mistake"}],"bins":[{"id":"realistic","label":"Realistic plan","valence":"pos"},{"id":"fail","label":"Setup to fail","valence":"neg"}],"key":{"a":"realistic","b":"fail","c":"realistic","d":"fail","e":"realistic","f":"fail"},"relearn":"One change at a time with self-compassion is realistic; perfectionism, quitting and self-shaming set you up to fail.","persona":"any","source":"realistic plan"},
  {"id":"bc-084","cat":"tools-and-help","type":"match","hook":"Match a hard moment to the tool for it.","pairs":[{"left":"Anger surging","right":"Pause, breathe, step away safely"},{"left":"After a slip","right":"Repair and self-forgive"},{"left":"Fear of real harm to your child","right":"Reach for help now (Be the Safe Adult)"},{"left":"Your own past resurfacing","right":"Tele-MANAS 14416"},{"left":"A hard day ahead","right":"Ready your pause-plan"}],"relearn":"Each hard moment has a tool: calm yourself, repair after, route your past, and reach for help fast.","persona":"Suresh","source":"moment to tool"},
  {"id":"bc-900","cat":"calm-yourself","type":"strike-rewrite","hook":"\"My temper is just my nature — short fuse runs in our family, nothing to be done.\"","myth":{"un":"My temper is just my nature; a short fuse runs in our family, nothing to be done.","re":"A short fuse is a learned habit, not a fixed fate; the pause between feeling and acting can be trained like any skill.","why":"Habits are learnable and so is the pause."},"relearn":"A short temper is a habit you can retrain, not a fixed fate; the pause before acting can be practised.","persona":"Suresh","source":"temper is trainable"},
  {"id":"bc-901","cat":"calm-yourself","type":"strike-rewrite","hook":"\"If I stay quiet instead of shouting, my child wins and I look weak.\"","myth":{"un":"If I stay quiet instead of shouting, my child wins and I look weak.","re":"A calm pause isn't losing; it's you staying in charge of yourself so you can hold the limit without harm.","why":"Self-control is authority, not surrender."},"relearn":"Staying calm instead of shouting isn't losing or weakness; it keeps you in charge so you hold the limit safely.","persona":"Suresh","source":"calm isn't losing"},
  {"id":"bc-902","cat":"calm-yourself","type":"strike-rewrite","hook":"\"The anger comes so fast there's no moment to catch it.\"","myth":{"un":"The anger comes so fast there's no moment to catch it.","re":"The first rush of fury usually peaks and fades within a couple of minutes; riding out that wave gives you the moment back.","why":"The surge passes if you don't feed it."},"relearn":"The first rush of anger peaks and eases within minutes; waiting it out gives you back the moment to choose.","persona":"any","source":"the wave passes"},
  {"id":"bc-903","cat":"calm-yourself","type":"strike-rewrite","hook":"\"Counting to ten is silly advice that never works for real anger.\"","myth":{"un":"Counting to ten is silly advice that never works for real anger.","re":"A slow count buys a few seconds for the first surge to drop, just enough to unclench and choose your next words.","why":"A few seconds is often all the gap you need."},"relearn":"A slow count isn't silly; it buys seconds for the surge to drop so you can unclench and choose your words.","persona":"any","source":"count buys a gap"},
  {"id":"bc-904","cat":"calm-yourself","type":"strike-rewrite","hook":"\"Showing my child I'm angry but staying calm will confuse them.\"","myth":{"un":"Letting my child see I'm angry but staying calm will confuse them.","re":"Naming your anger calmly teaches them feelings are okay and can be handled; it's one of the best lessons you can model.","why":"Calmly named anger is a lesson, not confusion."},"relearn":"Showing anger while staying calm teaches your child that feelings are okay and manageable; it's a gift, not confusion.","persona":"any","source":"named anger teaches"},
  {"id":"bc-905","cat":"calm-yourself","type":"strike-rewrite","hook":"\"Stepping out of the room when I'm angry means I'm abandoning my child.\"","myth":{"un":"Stepping out of the room when I'm angry means I'm abandoning my child.","re":"A short, safe pause where the child is fine is care, not abandonment; you leave to come back calmer, not to disappear.","why":"You step away to protect, then return."},"relearn":"A brief safe step away isn't abandonment; with the child safe, you leave to return calmer, which protects them.","persona":"Suresh","source":"pause isn't abandonment"},
  {"id":"bc-906","cat":"calm-yourself","type":"strike-rewrite","hook":"\"I never get angry at work, so my temper at home is my kids' fault.\"","myth":{"un":"I never get angry at work, so my temper at home is my kids' fault.","re":"Holding it together all day often means the leftover stress spills at home; the trigger is your load, not your child.","why":"Spilled stress isn't the child's doing."},"relearn":"Calm at work but short at home usually means spilled stress, not your child's fault; the load is the trigger to tend.","persona":"Vikram","source":"spilled stress"},
  {"id":"bc-906b","cat":"calm-yourself","type":"branch","hook":"Your child whines for the tenth time while you cook and your patience snaps thin.","options":[{"text":"Say 'I'm getting frustrated, give me a minute,' then breathe","consequence":"You catch the surge early and stay in control.","outcome":"name-it","best":true},{"text":"Snap and tell them to shut up","consequence":"Snapping teaches them anger means lashing out."}],"debrief":"When patience thins, name the feeling out loud and breathe before you act.","relearn":"Name your rising frustration and breathe rather than snapping; catching it early keeps you in control.","persona":"Suresh","source":"name it early"},
  {"id":"bc-907","cat":"calm-yourself","type":"branch","hook":"You're holding your crying baby at 3am and feel a frightening urge to shake or squeeze.","options":[{"text":"Lay the baby safely in the cot and step out to breathe","consequence":"You both stay safe while the urge passes.","outcome":"safe-down","best":true},{"text":"Keep holding while the urge builds","consequence":"Holding on while that urge builds risks harm."}],"debrief":"When a frightening urge surges, lay the baby down safely and step away to breathe.","relearn":"If a scary urge surges, put the baby safely down and step away; a safe pause protects you both.","persona":"Divya","source":"lay baby down safely"},
  {"id":"bc-908","cat":"calm-yourself","type":"branch","hook":"Your child does the exact thing your father punished you for, and rage floods up.","options":[{"text":"Notice this is the old wound, breathe, respond to your child","consequence":"You separate the trigger from the present child.","outcome":"separate","best":true},{"text":"React with the same fury once aimed at you","consequence":"This aims your father's fury at your own child."}],"debrief":"When a child's act triggers an old wound, notice it's the past and respond to the child here.","relearn":"When rage from an old wound floods up, name it as the past and respond to your child, not the ghost.","persona":"Suresh","source":"separate past from present"},
  {"id":"bc-909","cat":"calm-yourself","type":"branch","hook":"You can feel a shout building and your child is right in front of you, scared.","options":[{"text":"Drop and slow your voice on purpose, even mid-sentence","consequence":"Softening your voice cools the moment for you both.","outcome":"soften","best":true},{"text":"Let the volume climb","consequence":"A climbing volume frightens the child and feeds your anger."}],"debrief":"When a shout builds, deliberately drop and slow your voice; it cools you and reassures your child.","relearn":"Deliberately lower and slow your voice when a shout builds; softening cools you and steadies your child.","persona":"any","source":"soften the voice"},
  {"id":"bc-910","cat":"calm-yourself","type":"branch","hook":"You're alone with three tired kids and no one to tag in, and you're at your limit.","options":[{"text":"Make the space safe, step to the doorway, take ten slow breaths","consequence":"You reset without leaving them unsafe.","outcome":"doorway-reset","best":true},{"text":"Push past your limit and hope you don't blow up","consequence":"Pushing past your limit usually ends in the blow-up you feared."}],"debrief":"With no one to tag in, make the space safe and breathe at the doorway; you can still reset.","relearn":"Alone and at your limit, make the space safe and breathe at the doorway; you can reset without a tag-in.","persona":"any","source":"reset when alone"},
  {"id":"bc-911","cat":"calm-yourself","type":"branch","hook":"You've already started raising your voice and part of you wants to keep going.","options":[{"text":"Stop mid-sentence and say 'I need a moment'","consequence":"You cut the escalation off before it peaks.","outcome":"cut-it","best":true},{"text":"Finish the tirade since you've begun","consequence":"Finishing the tirade only deepens the harm and the regret."}],"debrief":"Even mid-shout you can stop; say 'I need a moment' and step back rather than peaking.","relearn":"You can stop even mid-shout; 'I need a moment' cuts the escalation off instead of riding it out.","persona":"Suresh","source":"stop mid-shout"},
  {"id":"bc-912","cat":"calm-yourself","type":"branch","hook":"You notice you're snappiest right after a stressful phone call from your boss.","options":[{"text":"Build a short buffer — splash water, breathe — before the kids","consequence":"You shed the work stress instead of dumping it.","outcome":"buffer","best":true},{"text":"Walk straight from the call into the kids' chaos","consequence":"The call's stress gets dumped onto them."}],"debrief":"When a stressor primes your temper, take a short buffer to reset before facing the kids.","relearn":"Build a short reset buffer after a known stressor so its tension doesn't spill onto your children.","persona":"Vikram","source":"buffer after stress"},
  {"id":"bc-913","cat":"calm-yourself","type":"branch","hook":"Your toddler hits you and your first instinct is to hit back to 'show them'.","options":[{"text":"Hold their hands gently, breathe, say 'we don't hit' calmly","consequence":"You teach the limit without becoming what you forbid.","outcome":"hold-hands","best":true},{"text":"Smack them so they 'learn how it feels'","consequence":"It just models that big people hit small ones."}],"debrief":"When your child hits you, regulate first, hold their hands and name the limit calmly.","relearn":"Breathe and hold the limit calmly when your child hits you; hitting back only models that bigger people hit.","persona":"Suresh","source":"don't hit back"},
  {"id":"bc-914","cat":"calm-yourself","type":"branch","hook":"You feel the heat rising but you're in the car and can't exactly walk away.","options":[{"text":"Pull over safely, or go quiet and breathe until the surge drops","consequence":"You find a safe pause even when you can't leave.","outcome":"pull-over","best":true},{"text":"Argue and gesture while driving angry","consequence":"Arguing while driving angry is unsafe for everyone in the car."}],"debrief":"When you can't walk away, find another safe pause: pull over, or go quiet and breathe until the surge passes.","relearn":"When you can't step away, pull over or go quiet and breathe; a safe pause is possible even in the car.","persona":"any","source":"pause when stuck"},
  {"id":"bc-915","cat":"calm-yourself","type":"match","hook":"Match each rising body signal to the quick calming move that meets it.","pairs":[{"left":"Jaw and fists clenching","right":"Unclench and drop your shoulders"},{"left":"Voice climbing louder","right":"Deliberately lower and slow it"},{"left":"Breath going shallow and fast","right":"One long, slow exhale"},{"left":"Heat rushing to your face","right":"Splash cool water or step outside"},{"left":"Thoughts racing 'I can't take this'","right":"Name it: 'I'm flooded, I need a minute'"}],"relearn":"Each early signal — clenching, a rising voice, shallow breath, heat, racing thoughts — has a quick move to meet it.","persona":"any","source":"signal to move"},
  {"id":"bc-916","cat":"calm-yourself","type":"match","hook":"Match each trigger you can plan for to a calmer response prepared in advance.","pairs":[{"left":"The chaotic homework hour","right":"Lower the bar and take breaks together"},{"left":"Mornings running late","right":"Lay clothes out the night before"},{"left":"Whining for the same thing","right":"Decide your calm answer ahead of time"},{"left":"Sibling fights at dinner","right":"Separate them early, before it peaks"},{"left":"Bedtime stalling","right":"A fixed, gentle routine you both know"}],"relearn":"Naming your flashpoints lets you plan a calmer response in advance, so the trigger doesn't ambush you.","persona":"any","source":"plan for triggers"},
  {"id":"bc-917","cat":"calm-yourself","type":"match","hook":"Match each calming idea to what it's really doing for you.","pairs":[{"left":"A slow exhale","right":"Signals your body it's safe to settle"},{"left":"Stepping to another room","right":"Puts distance between feeling and acting"},{"left":"Naming the feeling","right":"Turns the surge into something you can hold"},{"left":"Cool water on your face","right":"Physically interrupts the heat of anger"},{"left":"Knowing your trigger","right":"Lets you catch the reflex before it fires"}],"relearn":"Breathing, distance, naming, cool water and knowing your trigger each work on the surge in a different way.","persona":"any","source":"why each tool works"},
  {"id":"bc-918","cat":"calm-yourself","type":"sort","hook":"Sort each move: it widens the gap between feeling and acting, or it shrinks it.","items":[{"id":"a","text":"Taking one slow breath first"},{"id":"b","text":"Shouting the instant you feel it"},{"id":"c","text":"Stepping to the next room"},{"id":"d","text":"Acting on the urge straight away"},{"id":"e","text":"Naming 'I'm angry' to yourself"},{"id":"f","text":"Replaying what enraged you"}],"bins":[{"id":"widens","label":"Widens the gap","valence":"pos"},{"id":"shrinks","label":"Shrinks the gap","valence":"neg"}],"key":{"a":"widens","b":"shrinks","c":"widens","d":"shrinks","e":"widens","f":"shrinks"},"relearn":"Breathing, stepping away and naming the feeling widen the gap before you act; reacting instantly and stewing shrink it.","persona":"any","source":"widen vs shrink"},
  {"id":"bc-919","cat":"calm-yourself","type":"sort","hook":"Sort each thought: does it help you pause, or does it pour fuel on the anger?","items":[{"id":"a","text":"'This will pass if I wait'"},{"id":"b","text":"'He's doing this on purpose to provoke me'"},{"id":"c","text":"'I can handle this calmly'"},{"id":"d","text":"'I've had enough, I'll show him'"},{"id":"e","text":"'He's a tired child, not my enemy'"},{"id":"f","text":"'A real parent wouldn't take this'"}],"bins":[{"id":"cools","label":"Helps you pause","valence":"pos"},{"id":"fuels","label":"Fuels the anger","valence":"neg"}],"key":{"a":"cools","b":"fuels","c":"cools","d":"fuels","e":"cools","f":"fuels"},"relearn":"Thoughts like 'this will pass' and 'he's a tired child' help you pause; 'he's provoking me' and 'I'll show him' fuel the anger.","persona":"Suresh","source":"cooling vs fuelling thoughts"},
  {"id":"bc-920","cat":"calm-yourself","type":"sort","hook":"Sort each habit: it keeps your fuse longer, or it burns it shorter.","items":[{"id":"a","text":"Getting enough sleep when you can"},{"id":"b","text":"Skipping meals and running on empty"},{"id":"c","text":"Asking for help before you're drained"},{"id":"d","text":"Bottling stress until it bursts"},{"id":"e","text":"Short breaks during a hard day"},{"id":"f","text":"Drinking to take the edge off"}],"bins":[{"id":"longer","label":"Lengthens your fuse","valence":"pos"},{"id":"shorter","label":"Shortens your fuse","valence":"neg"}],"key":{"a":"longer","b":"shorter","c":"longer","d":"shorter","e":"longer","f":"shorter"},"relearn":"Sleep, asking for help and small breaks lengthen your patience; skipping meals, bottling stress and drinking shorten it.","persona":"any","source":"lengthen vs shorten fuse"},
  {"id":"bc-921","cat":"calm-yourself","type":"sort","hook":"Sort each one: a real early-warning sign of your anger, or just a passing thing?","items":[{"id":"a","text":"Your chest tightening"},{"id":"b","text":"A song stuck in your head"},{"id":"c","text":"Your voice starting to rise"},{"id":"d","text":"Feeling a bit hungry earlier"},{"id":"e","text":"Heat flushing your neck"},{"id":"f","text":"A light drizzle outside"}],"bins":[{"id":"warning","label":"Anger warning sign","valence":"uhoh"},{"id":"unrelated","label":"Unrelated","valence":"neutral"}],"key":{"a":"warning","b":"unrelated","c":"warning","d":"unrelated","e":"warning","f":"unrelated"},"relearn":"A tight chest, a rising voice and a hot neck are your anger's early-warning signs; a stuck song or the weather aren't.","persona":"Suresh","source":"warning vs noise"},
  {"id":"bc-922","cat":"calm-yourself","type":"reflect","hook":"Lensy: feeling furious doesn't make you a bad parent — what you do with the fury is the part you get to choose. Sit right?","prompt":"What's your take?","options":["Sits right","Feeling isn't acting","I get to choose"],"affirm":"Anger itself isn't wrong or bad; it's a feeling. The choice you make in the gap after it is what's yours to own.","relearn":"Feeling furious doesn't make you a bad parent; what you do with the fury is the part you choose.","persona":"any","source":"feeling isn't the failure"},
  {"id":"bc-923","cat":"calm-yourself","type":"reflect","hook":"Lensy: every time you pause instead of erupting, you're showing your child what self-control looks like. Worth practising?","prompt":"What do you think?","options":["Worth it","They're watching","Practising"],"affirm":"Children learn to handle big feelings mostly by watching you handle yours; each pause you take is a quiet lesson.","relearn":"Each time you pause instead of erupting, you show your child what self-control looks like.","persona":"any","source":"they learn by watching"},
  {"id":"bc-924","cat":"calm-yourself","type":"reflect","hook":"Lensy: the calmest parents aren't the ones who never feel anger — they're the ones who've practised the pause. Land?","prompt":"What's your take?","options":["It lands","Practised the pause","Not never-angry"],"affirm":"Calm parents still feel fury; they've just rehearsed the pause so often that reaching for it has become the reflex.","relearn":"Calm parents still feel anger; they've simply practised the pause until it became their reflex.","persona":"Suresh","source":"pause is practised"},
  {"id":"bc-925","cat":"calm-yourself","type":"reflect","hook":"Lensy: noticing your trigger before it fires is a skill that grows every time you use it. Believe that?","prompt":"What do you think?","options":["I believe it","It grows","Catch it earlier"],"affirm":"The more you notice your own triggers, the earlier you catch them next time; this awareness genuinely strengthens with use.","relearn":"Noticing your trigger before it fires is a skill that grows sharper every time you practise it.","persona":"any","source":"awareness grows"},
  {"id":"bc-926","cat":"calm-yourself","type":"spot","hook":"Spot the two red flags — the moves that make a heated moment more dangerous.","scene":[{"id":"a","text":"Putting space between you before you speak","trick":false},{"id":"b","text":"Getting in the child's face to shout","trick":true},{"id":"c","text":"Taking a slow breath to steady yourself","trick":false},{"id":"d","text":"Grabbing them hard to make them listen","trick":true},{"id":"e","text":"Lowering your voice on purpose","trick":false}],"why":"Getting in a child's face and grabbing them hard escalate and frighten; space, breath and a low voice keep it safe.","relearn":"Crowding and grabbing a child in anger raise the danger; space, breath and a softer voice keep it safe.","persona":"any","source":"red flags in the heat"},
  {"id":"bc-927","cat":"calm-yourself","type":"spot","hook":"Spot the two red-flag thoughts — the ones that feed your anger instead of cooling it.","scene":[{"id":"a","text":"'This surge will pass if I wait'","trick":false},{"id":"b","text":"'He's provoking me on purpose'","trick":true},{"id":"c","text":"'I can choose my next move'","trick":false},{"id":"d","text":"'I have every right to lose it'","trick":true},{"id":"e","text":"'He's a tired kid, not my enemy'","trick":false}],"why":"'He's provoking me' and 'I have a right to lose it' justify erupting; the others remind you it passes and you can choose.","relearn":"Thoughts that cast your child as an enemy or justify losing it feed the anger; cooling ones remind you it passes.","persona":"Suresh","source":"red-flag thoughts"},
  {"id":"bc-928","cat":"calm-yourself","type":"spot","hook":"Spot the two red flags — the 'calming' tricks that actually do harm.","scene":[{"id":"a","text":"Stepping out for a few slow breaths","trick":false},{"id":"b","text":"A drink to 'take the edge off'","trick":true},{"id":"c","text":"Splashing cool water on your face","trick":false},{"id":"d","text":"Smashing things near the kids","trick":true},{"id":"e","text":"Naming the feeling to yourself","trick":false}],"why":"Drinking to cope and smashing things frighten and risk harm; breath, cool water and naming the feeling actually calm.","relearn":"Drinking to cope or smashing things aren't calming; they frighten and risk harm. Breath, cool water and naming do.","persona":"any","source":"fake calm vs real calm"},
  {"id":"bc-928b","cat":"calm-yourself","type":"spot","hook":"Spot the two red flags — the lines that pretend to be a pause but are threats.","scene":[{"id":"a","text":"'I need a minute, I'll be right back'","trick":false},{"id":"b","text":"'Wait till I get my hands on you'","trick":true},{"id":"c","text":"'Let's both take a breath'","trick":false},{"id":"d","text":"'You'll regret this when I'm done'","trick":true},{"id":"e","text":"'I'm too angry to talk well now'","trick":false}],"why":"'Wait till I get my hands on you' and 'you'll regret this' are threats dressed as a pause; the rest are honest exits.","relearn":"A real pause is honest ('I need a minute'); a threat dressed as one ('wait till I get you') only frightens.","persona":"Suresh","source":"pause vs threat"},
  {"id":"bc-929","cat":"calm-yourself","type":"role-play","hook":"You feel yourself flooding and want to tell your older child you're stepping out, without scaring them.","setup":"Tell them honestly:","yourLine":[{"text":"\"I'm feeling really angry, so I'm going to take a few minutes to calm down and then we'll talk.\"","best":true},{"text":"\"Get out of my sight before I do something I regret.\""}],"relearn":"Calmly telling a child you need a few minutes to settle keeps them safe and reassured, unlike a frightening threat.","persona":"Suresh","source":"honest step-out"},
  {"id":"bc-930","cat":"calm-yourself","type":"role-play","hook":"Your spouse sees you're about to lose it and you want to ask them to take over for a moment.","setup":"Ask for the hand-off:","yourLine":[{"text":"\"I'm at my limit — can you take over for ten minutes while I cool down?\"","best":true},{"text":"\"Why am I the only one dealing with this? I give up.\""}],"relearn":"Asking your partner to tag in while you cool down is a strong, planned move that keeps the moment safe.","persona":"Vikram","source":"ask to tag in"},
  {"id":"bc-931","cat":"calm-yourself","type":"role-play","hook":"After a near-miss where you almost shouted, you want to coach yourself silently to stay steady.","setup":"Talk yourself down:","yourLine":[{"text":"\"Breathe. This will pass. He's a child and I'm the calm one here.\"","best":true},{"text":"\"I can't take this, I'm going to explode any second.\""}],"relearn":"A steadying inner script — breathe, this passes, I'm the calm one — pulls you back from the edge better than panic talk.","persona":"any","source":"self-coaching script"},
  {"id":"bc-932","cat":"calm-yourself","type":"role-play","hook":"Your mother insists you should just shout louder to make the kids listen. You hold your calm line.","setup":"Hold your line kindly:","yourLine":[{"text":"\"I know that's how we did it, but I'm learning to stay calm — it works better for me and them.\"","best":true},{"text":"\"You're right, I'll just yell harder next time.\""}],"relearn":"Kindly holding your calm approach against 'just shout louder' honours your parent without inheriting the harsh script.","persona":"Suresh","source":"hold against shout louder"},
  {"id":"bc-990","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Sparing the rod spoils the child — that's just wisdom.\"","myth":{"un":"Sparing the rod spoils the child — that's just wisdom.","re":"Children disciplined without hitting turn out at least as well behaved; hitting raises aggression, not character.","why":"The saying is tradition, not evidence."},"relearn":"You don't need a rod; non-violent discipline raises better-behaved children, and hitting only adds aggression.","persona":"Suresh","source":"no rod needed"},
  {"id":"bc-991","cat":"discipline-differently","type":"strike-rewrite","hook":"\"A quick smack is the fastest way to make a child stop.\"","myth":{"un":"A quick smack is the fastest way to make a child stop.","re":"A smack stops the moment but teaches nothing; the child learns to hide it and to use force when angry.","why":"Fast isn't the same as effective."},"relearn":"A smack only buys silence now; it teaches hiding and that force is how the strong get their way.","persona":"Suresh","source":"fast not effective"},
  {"id":"bc-992","cat":"discipline-differently","type":"strike-rewrite","hook":"\"I turned out fine after being hit, so it clearly does no harm.\"","myth":{"un":"I turned out fine after being hit, so it clearly does no harm.","re":"Turning out okay despite being hit isn't proof it helped; many carry quiet costs, and better ways exist now.","why":"Surviving harm isn't the same as benefiting."},"relearn":"'I turned out fine' isn't proof hitting helped; you turned out fine despite it, and gentler ways work better.","persona":"Suresh","source":"despite not because"},
  {"id":"bc-993","cat":"discipline-differently","type":"strike-rewrite","hook":"\"If I'm gentle, my child will walk all over me and never listen.\"","myth":{"un":"If I'm gentle, my child will walk all over me and never listen.","re":"Gentle isn't weak: firm-and-kind parents hold clear limits warmly, and their children listen more, not less.","why":"Warmth and firmness work together."},"relearn":"Gentle doesn't mean a pushover; holding limits warmly earns more cooperation than harshness ever does.","persona":"Vikram","source":"gentle not weak"},
  {"id":"bc-994","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Yelling isn't hitting, so shouting them down is harmless discipline.\"","myth":{"un":"Yelling isn't hitting, so shouting them down is harmless discipline.","re":"Harsh, frequent yelling also frightens and wounds children and works no better than a calm, clear limit.","why":"Verbal harshness harms too."},"relearn":"Constant shouting frightens a child like hitting does; a calm, clear limit teaches far more than volume.","persona":"Suresh","source":"yelling wounds too"},
  {"id":"bc-995","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Threats like 'I'll leave you here' keep a child in line.\"","myth":{"un":"Threats like 'I'll leave you here' keep a child in line.","re":"Abandonment threats scare a child into obeying but quietly damage their sense of safety with you.","why":"Fear of losing you isn't security."},"relearn":"Threatening to leave or abandon a child controls through fear and chips away at the safety they need from you.","persona":"Suresh","source":"no abandonment threats"},
  {"id":"bc-996","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Comparing my child to others ('why can't you be like him?') pushes them to do better.\"","myth":{"un":"Comparing my child to others ('why can't you be like him?') pushes them to do better.","re":"Constant comparison teaches a child they're not enough; it breeds resentment and shame, not motivation.","why":"Comparison wounds self-worth."},"relearn":"Comparing your child to others doesn't motivate; it tells them they're not enough and feeds shame.","persona":"Suresh","source":"no comparing"},
  {"id":"bc-997","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Children only respect a strict parent; a soft one gets no respect.\"","myth":{"un":"Children only respect a strict parent; a soft one gets no respect.","re":"Children respect a parent who is fair, consistent and warm; harshness earns fear, which isn't respect.","why":"Respect grows from trust, not fear."},"relearn":"Real respect comes from fairness, consistency and warmth, not strictness; harshness only buys fear.","persona":"Suresh","source":"respect from fairness"},
  {"id":"bc-998","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Praising good behaviour spoils a child; only correcting the bad works.\"","myth":{"un":"Praising good behaviour spoils a child; only correcting the bad works.","re":"Noticing and naming good behaviour teaches more than punishment; children repeat what gets warm attention.","why":"What you notice, you grow."},"relearn":"Praise doesn't spoil; naming the good behaviour you want teaches a child more than only catching the bad.","persona":"Vikram","source":"catch the good"},
  {"id":"bc-999","cat":"discipline-differently","type":"strike-rewrite","hook":"\"A consequence has to hurt or it won't teach the lesson.\"","myth":{"un":"A consequence has to hurt or it won't teach the lesson.","re":"A consequence teaches when it's clear, related and explained — not when it hurts; pain teaches fear, not the lesson.","why":"Clarity teaches; pain only frightens."},"relearn":"A consequence works when it's clear, related and explained, not when it hurts; pain teaches fear, not the lesson.","persona":"any","source":"clear not painful"},
  {"id":"bc-1000","cat":"discipline-differently","type":"strike-rewrite","hook":"\"My child is being defiant on purpose just to provoke me.\"","myth":{"un":"My child is being defiant on purpose just to provoke me.","re":"Most 'defiance' is a child overwhelmed or testing limits, not plotting against you; reading it that way calms your response.","why":"Behaviour is communication, not attack."},"relearn":"A child's tough behaviour is usually overwhelm or limit-testing, not a plot against you; seeing that softens how you respond.","persona":"Suresh","source":"not out to get you"},
  {"id":"bc-1001","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Rules only work if I enforce them harshly and inconsistently scares them.\"","myth":{"un":"Rules only work if I enforce them harshly, and being unpredictable keeps them on their toes.","re":"Children follow rules best when limits are calm, clear and consistent; unpredictability breeds anxiety, not behaviour.","why":"Consistency teaches; unpredictability frightens."},"relearn":"Calm, clear, consistent limits work better than harsh, unpredictable ones, which just leave a child anxious.","persona":"any","source":"consistent not harsh"},
  {"id":"bc-1002","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Discipline is about punishing the wrong, full stop.\"","myth":{"un":"Discipline is about punishing the wrong, full stop.","re":"Discipline at its root means to teach; the aim is a child who understands and chooses better, not one who's been punished.","why":"To discipline is to teach, not to punish."},"relearn":"Discipline means to teach, not to punish; the goal is a child who learns the better choice, not one who fears.","persona":"any","source":"discipline is teaching"},
  {"id":"bc-1003","cat":"discipline-differently","type":"strike-rewrite","hook":"\"Letting a child feel a hard feeling without punishing is just being soft.\"","myth":{"un":"Letting a child feel a hard feeling without punishing is just being soft.","re":"You can hold the limit AND let the feeling be felt; naming the feeling while keeping the rule is firm and kind, not soft.","why":"You hold the line and the feeling both."},"relearn":"Allowing the feeling while holding the limit isn't soft; naming the feeling and keeping the rule is firm and kind.","persona":"Vikram","source":"feeling plus limit"},
  {"id":"bc-1004","cat":"discipline-differently","type":"strike-rewrite","hook":"\"If hitting is off the table, I'm left with no way to discipline at all.\"","myth":{"un":"If hitting is off the table, I'm left with no way to discipline at all.","re":"Without hitting you still have many tools: clear limits, related consequences, naming feelings, and warmth that works better.","why":"Non-violent discipline is full of tools."},"relearn":"Taking hitting off the table leaves you a full toolkit: clear limits, related consequences, and warmth that works.","persona":"Suresh","source":"a full toolkit"},
  {"id":"bc-1005","cat":"discipline-differently","type":"sort","hook":"Sort each line: firm-and-kind discipline, or fear-based control?","items":[{"id":"a","text":"\"You broke it, so let's clean it up together.\""},{"id":"b","text":"\"Hit you back so you know how it feels.\""},{"id":"c","text":"\"I won't let you hit; we'll find words instead.\""},{"id":"d","text":"\"Wait till your father gets home.\""},{"id":"e","text":"\"The rule stands, and I'm right here with you.\""},{"id":"f","text":"\"You're useless, why can't you behave?\""}],"bins":[{"id":"firm","label":"Firm & kind","valence":"pos"},{"id":"fear","label":"Fear-based","valence":"neg"}],"key":{"a":"firm","b":"fear","c":"firm","d":"fear","e":"firm","f":"fear"},"relearn":"Repairing together, blocking harm calmly and holding a limit warmly are firm-and-kind; hitting back, threats and insults are fear-based.","persona":"any","source":"firm vs fear lines"},
  {"id":"bc-1006","cat":"discipline-differently","type":"sort","hook":"Sort: an effective consequence, or just a punishment that doesn't teach?","items":[{"id":"a","text":"Spilt juice → help mop it up"},{"id":"b","text":"A whole week with no meals"},{"id":"c","text":"Skipped homework → no screen till it's done"},{"id":"d","text":"A hard slap for talking back"},{"id":"e","text":"Threw a toy in anger → toy rests for the day"},{"id":"f","text":"Locking the child outside alone"}],"bins":[{"id":"teaches","label":"Teaches the lesson","valence":"pos"},{"id":"harms","label":"Just punishes / harms","valence":"neg"}],"key":{"a":"teaches","b":"harms","c":"teaches","d":"harms","e":"teaches","f":"harms"},"relearn":"Clear, related consequences (clean the spill, finish homework, the toy rests) teach; starving, slapping or locking out only harm.","persona":"any","source":"consequence vs punishment"},
  {"id":"bc-1007","cat":"discipline-differently","type":"sort","hook":"Sort each phrase: builds your child up, or shames them down?","items":[{"id":"a","text":"\"That was unkind; let's make it right.\""},{"id":"b","text":"\"You're so stupid, you never learn.\""},{"id":"c","text":"\"You're better than that choice, try again.\""},{"id":"d","text":"\"Look how you've embarrassed me in front of everyone.\""},{"id":"e","text":"\"Mistakes happen; what can we do next time?\""},{"id":"f","text":"\"No wonder nobody likes you.\""}],"bins":[{"id":"builds","label":"Builds them up","valence":"pos"},{"id":"shames","label":"Shames them down","valence":"neg"}],"key":{"a":"builds","b":"shames","c":"builds","d":"shames","e":"builds","f":"shames"},"relearn":"Naming the act and offering a redo builds a child; calling them stupid, unloved or an embarrassment shames and discourages.","persona":"any","source":"build vs shame phrases"},
  {"id":"bc-1008","cat":"discipline-differently","type":"sort","hook":"Sort: a way to set a limit that teaches, or one that only frightens?","items":[{"id":"a","text":"Explaining the reason behind the rule"},{"id":"b","text":"Glaring and raising a hand to threaten"},{"id":"c","text":"Offering a small choice within the limit"},{"id":"d","text":"Mocking the child until they comply"},{"id":"e","text":"Staying calm and repeating it once"},{"id":"f","text":"Silent cold-shouldering for hours"}],"bins":[{"id":"teaches","label":"Teaches the limit","valence":"pos"},{"id":"frightens","label":"Only frightens","valence":"neg"}],"key":{"a":"teaches","b":"frightens","c":"teaches","d":"frightens","e":"teaches","f":"frightens"},"relearn":"Explaining the reason, offering a choice and calm repetition teach a limit; threatening, mocking and cold-shouldering only frighten.","persona":"any","source":"teach vs frighten limit"},
  {"id":"bc-1009","cat":"discipline-differently","type":"sort","hook":"Sort: discipline that respects the child, or that humiliates them?","items":[{"id":"a","text":"A quiet word aside, not in front of others"},{"id":"b","text":"Scolding them loudly in front of guests"},{"id":"c","text":"Letting them save face while holding the rule"},{"id":"d","text":"Telling relatives how badly they behaved"},{"id":"e","text":"Asking what happened before deciding"},{"id":"f","text":"Calling them a name in front of friends"}],"bins":[{"id":"respects","label":"Respects the child","valence":"pos"},{"id":"humiliates","label":"Humiliates","valence":"neg"}],"key":{"a":"respects","b":"humiliates","c":"respects","d":"humiliates","e":"respects","f":"humiliates"},"relearn":"A quiet word, saving face and hearing them out respect a child; public scolding and name-calling humiliate.","persona":"any","source":"respect vs humiliate"},
  {"id":"bc-1010","cat":"discipline-differently","type":"sort","hook":"Sort each belief: true about positive discipline, or a myth to leave behind?","items":[{"id":"a","text":"Firm-and-kind holds clear limits"},{"id":"b","text":"Being kind means no rules at all"},{"id":"c","text":"Children learn better without fear"},{"id":"d","text":"You must choose: strict or spoiled"},{"id":"e","text":"Warmth and boundaries go together"},{"id":"f","text":"Only pain makes a lesson stick"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth to leave","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Firm limits, learning without fear and warmth-with-boundaries are true; 'kind means no rules', 'strict or spoiled' and 'only pain teaches' are myths.","persona":"any","source":"true vs myth"},
  {"id":"bc-1011","cat":"discipline-differently","type":"sort","hook":"Sort each response to a meltdown: helps the child settle, or pours fuel on it?","items":[{"id":"a","text":"Lowering your voice, getting to their level"},{"id":"b","text":"Shouting louder than they are"},{"id":"c","text":"Naming the feeling: 'you're really angry'"},{"id":"d","text":"Threatening a beating if they don't stop"},{"id":"e","text":"Holding the limit calmly while they cry"},{"id":"f","text":"Mocking the crying to shame them quiet"}],"bins":[{"id":"settles","label":"Helps them settle","valence":"pos"},{"id":"fuels","label":"Pours fuel on it","valence":"neg"}],"key":{"a":"settles","b":"fuels","c":"settles","d":"fuels","e":"settles","f":"fuels"},"relearn":"A low voice, naming the feeling and a calm limit help a child settle; shouting, threats and mockery escalate it.","persona":"any","source":"settle vs fuel"},
  {"id":"bc-1012","cat":"discipline-differently","type":"branch","hook":"Your child lied about finishing homework. You want to discipline so they actually learn.","options":[{"text":"Calmly name it, set a fair consequence, ask why lying felt safer","consequence":"Honesty stays safe with you, and they face a fair result.","outcome":"teach","best":true},{"text":"Slap them and call them a liar","consequence":"Hitting and labelling teach better lying, not truth."}],"debrief":"Name the lie calmly, set a fair consequence, make truth safe; hitting just teaches hiding.","relearn":"Discipline a lie by naming it and making honesty safe; hitting only teaches better lying.","persona":"Suresh","source":"lie discipline"},
  {"id":"bc-1013","cat":"discipline-differently","type":"branch","hook":"Your child hit their younger sibling. The old reflex says hit back so they 'feel it'.","options":[{"text":"Stop it firmly, comfort the hurt one, teach 'we use words'","consequence":"They learn hitting is never the answer — even from you.","outcome":"teach","best":true},{"text":"Smack them to show how it feels","consequence":"It proves the bigger person hits the smaller."}],"debrief":"Block the hitting, tend the hurt child, teach words; hitting back just proves force wins.","relearn":"When your child hits, stop it, comfort the sibling, teach words; hitting back proves force wins.","persona":"Suresh","source":"sibling hitting"},
  {"id":"bc-1014","cat":"discipline-differently","type":"branch","hook":"At a family gathering, relatives push you to 'give him a good thrashing' for misbehaving.","options":[{"text":"Hold your line warmly; step aside to handle it your calm way","consequence":"You protect your child and keep your values.","outcome":"hold","best":true},{"text":"Hit him to satisfy the relatives","consequence":"You sacrifice your child to others' approval."}],"debrief":"Hold your non-violent line under pressure and handle it calmly; their approval isn't worth his safety.","relearn":"Pressed to 'thrash' your child, hold your line and stay calm; their approval isn't worth his safety.","persona":"Suresh","source":"relative pressure"},
  {"id":"bc-1015","cat":"discipline-differently","type":"branch","hook":"Your toddler keeps throwing food on the floor and grinning. Your patience is gone.","options":[{"text":"Say 'food stays on the plate' calmly and end the meal","consequence":"A clear, calm limit teaches without fear.","outcome":"limit","best":true},{"text":"Slap the little hand each time","consequence":"It frightens a toddler and teaches that hands hurt."}],"debrief":"Name the rule calmly and end the meal; a toddler learns the limit far better than from a slap.","relearn":"Meet thrown food with a calm limit and ending the meal; a slap only frightens a toddler.","persona":"any","source":"toddler limit"},
  {"id":"bc-1016","cat":"discipline-differently","type":"branch","hook":"Your child got a poor exam mark. You feel the inherited urge to punish hard.","options":[{"text":"Sit with them, ask what was tough, make a calm plan","consequence":"Setbacks meet support, and they try harder.","outcome":"support","best":true},{"text":"Beat them and ban all play","consequence":"It breeds fear of you and school, not learning."}],"debrief":"Meet a poor mark with curiosity and a plan, not a beating; support raises effort, fear raises hiding.","relearn":"Answer a poor mark with support and a plan, not a beating; fear makes a child hide, support helps them try.","persona":"Suresh","source":"exam marks"},
  {"id":"bc-1017","cat":"discipline-differently","type":"branch","hook":"Your child won't get off the phone despite three reminders. You're about to snatch and shout.","options":[{"text":"Give a calm final warning and consequence, then follow through","consequence":"Limits feel real and predictable, not scary.","outcome":"follow-through","best":true},{"text":"Snatch it and hurl abuse","consequence":"It starts a battle and models losing control."}],"debrief":"A calm final warning plus quiet follow-through holds the limit better than snatching or caving.","relearn":"Hold a screen limit with a calm warning and quiet follow-through, not snatching or caving in.","persona":"Vikram","source":"screen limit"},
  {"id":"bc-1018","cat":"discipline-differently","type":"branch","hook":"Your child broke a neighbour's window playing cricket and is terrified of you.","options":[{"text":"Stay calm; have them help apologise and make it right","consequence":"They learn accountability without fearing you.","outcome":"accountable","best":true},{"text":"Thrash them in front of the neighbour","consequence":"It teaches shame and fear, not repair."}],"debrief":"Have them own it and help make it right while you stay calm; accountability grows without fear.","relearn":"After a broken window, have your child help make it right calmly; it teaches accountability without fear.","persona":"Suresh","source":"broken window"},
  {"id":"bc-1019","cat":"discipline-differently","type":"branch","hook":"You're exhausted and your child keeps whining for sweets. The snap is rising.","options":[{"text":"Say 'no, and I know that's hard' once, then stop negotiating","consequence":"A kind, firm 'no' settles the whining sooner.","outcome":"firm-no","best":true},{"text":"Give in just for peace","consequence":"It teaches that whining overrides a 'no'."}],"debrief":"A warm, firm 'no' held once without re-arguing settles whining better than a slap or giving in.","relearn":"Hold a 'no' warmly and stop negotiating; a slap teaches hitting, caving teaches whining works.","persona":"any","source":"whining no"},
  {"id":"bc-1020","cat":"discipline-differently","type":"match","hook":"Match each misbehaviour to a firm-and-kind response that teaches.","pairs":[{"left":"Refusing to share a toy","right":"Set a turn-taking timer, stay close"},{"left":"Drawing on the wall","right":"Hand them a cloth to clean it together"},{"left":"Yelling 'I hate you'","right":"Name the anger, hold the limit anyway"},{"left":"Dawdling at bedtime","right":"A calm routine and one clear choice"},{"left":"Grabbing in a shop","right":"Quietly leave, try again another day"}],"relearn":"Each misbehaviour has a calm teaching response: a timer, a clean-up, naming the feeling, a routine, or a quiet exit.","persona":"Vikram","source":"misbehaviour to response"},
  {"id":"bc-1021","cat":"discipline-differently","type":"match","hook":"Match each fear-based old move to the firm-and-kind move that replaces it.","pairs":[{"left":"A slap to stop them","right":"A calm, clear limit"},{"left":"'Shut up or else'","right":"'I'm listening; the rule still stands'"},{"left":"Shaming in public","right":"A quiet word aside"},{"left":"'You're so bad'","right":"'That choice wasn't okay'"},{"left":"Threatening to abandon them","right":"'I'm staying right here with you'"}],"relearn":"Every fear-based reflex has a firm-and-kind swap: a calm limit, real listening, a private word, naming the act, and staying close.","persona":"any","source":"swap the reflex"},
  {"id":"bc-1022","cat":"discipline-differently","type":"match","hook":"Match each part of a calm consequence to why it works.","pairs":[{"left":"It's related to what happened","right":"The lesson makes sense to the child"},{"left":"It's explained, not just imposed","right":"They understand, not just obey"},{"left":"It's delivered calmly","right":"No fear clouds the learning"},{"left":"It ends and is forgiven","right":"They aren't shamed long-term"},{"left":"It's consistent next time","right":"They learn the limit is real"}],"relearn":"A consequence works when it's related, explained, calm, time-limited and consistent — that's what makes a child learn, not fear.","persona":"any","source":"why consequences work"},
  {"id":"bc-1023","cat":"discipline-differently","type":"match","hook":"Match each child's underlying need to the discipline that meets it.","pairs":[{"left":"Overtired and melting down","right":"Comfort first, rules after rest"},{"left":"Testing if the limit is real","right":"Hold it calmly and consistently"},{"left":"Big feeling with no words","right":"Name the feeling for them"},{"left":"Wants some control","right":"Offer a small choice within the limit"},{"left":"Feeling unseen","right":"Warm attention before correcting"}],"relearn":"Behind misbehaviour is a need — rest, a real limit, words for a feeling, some control, or attention — and meeting it teaches best.","persona":"any","source":"need to discipline"},
  {"id":"bc-1024","cat":"discipline-differently","type":"match","hook":"Match each common myth to the truth that replaces it.","pairs":[{"left":"'A slap never hurt anyone'","right":"Hitting harms and doesn't work"},{"left":"'Fear makes them respect you'","right":"Respect grows from trust"},{"left":"'Gentle means spoiled'","right":"Firm-and-kind holds the limit"},{"left":"'Shame makes them improve'","right":"Shame discourages and wounds"},{"left":"'Discipline means punishment'","right":"Discipline means to teach"}],"relearn":"Each discipline myth has a truth: hitting harms, respect is from trust, gentle still holds limits, shame wounds, discipline teaches.","persona":"any","source":"myth to truth"},
  {"id":"bc-1025","cat":"discipline-differently","type":"reflect","hook":"Lensy: the word 'discipline' shares a root with 'disciple' — a learner, not a target. Does that shift how it feels?","prompt":"What's your take?","options":["It shifts it","A learner, not a target","Teaching, not punishing"],"affirm":"Discipline and disciple share a root meaning 'to teach a learner'; the goal is a child who understands, not one who's been punished.","relearn":"Discipline means teaching a learner, not punishing a target; that root changes the whole aim.","persona":"any","source":"disciple root"},
  {"id":"bc-1026","cat":"discipline-differently","type":"reflect","hook":"Lensy: picture the parent your child would feel safest telling a mistake to. That parent is firm AND warm. Worth becoming?","prompt":"What do you think?","options":["Worth it","Safe to tell","Firm and warm"],"affirm":"Children confide in parents who are firm and warm, not frightening; being safe to tell the truth to is the aim.","relearn":"Aim to be the parent your child feels safest telling a mistake to — firm and warm, never frightening.","persona":"any","source":"safe to tell"},
  {"id":"bc-1027","cat":"discipline-differently","type":"reflect","hook":"Lensy: when you stayed calm and held a limit instead of snapping, what did you notice in your child afterward?","prompt":"What did you notice?","options":["They settled sooner","They came back closer","They listened more"],"affirm":"Holding a limit calmly usually settles a child sooner and keeps them close; firm-and-kind works, and you've likely felt it.","relearn":"You've probably noticed it: a calm, held limit settles a child sooner and keeps them close.","persona":"any","source":"noticing calm works"},
  {"id":"bc-1028","cat":"discipline-differently","type":"reflect","hook":"Lensy: every calm limit you hold today is a script your child may one day use with their own kids. Sit with that?","prompt":"What's your take?","options":["I'll sit with it","Passing the calm on","A better script"],"affirm":"The way you discipline becomes the inner voice your child carries; each calm limit writes a gentler script for the next generation.","relearn":"How you discipline becomes your child's future script; each calm limit hands the next generation a gentler one.","persona":"Suresh","source":"future script"},
  {"id":"bc-1029","cat":"discipline-differently","type":"reflect","hook":"Lensy: 'firm' and 'kind' aren't opposites you choose between — they're two hands holding the same limit. Feel that?","prompt":"What do you think?","options":["I feel it","Both hands","Not either/or"],"affirm":"Firm and kind work together, not against each other; you can hold a clear limit and stay warm in the very same breath.","relearn":"Firm and kind aren't a choice between; they're two hands on the same limit, held together.","persona":"any","source":"two hands"},
  {"id":"bc-1030","cat":"discipline-differently","type":"reflect","hook":"Lensy: a child who isn't afraid of you is freer to actually hear you. Does that change what you're aiming for?","prompt":"What's your take?","options":["It changes it","Heard, not feared","Less fear, more listening"],"affirm":"Fear makes a child defend and hide; safety lets them actually listen and learn — being heard beats being feared.","relearn":"A child who isn't afraid of you can actually hear you; aim to be listened to, not feared.","persona":"any","source":"heard not feared"},
  {"id":"bc-1031","cat":"discipline-differently","type":"reflect","hook":"Lensy: think of one limit you hold warmly already. You've proved you can do firm-and-kind. Build from there?","prompt":"What do you think?","options":["I'll build from there","I already do this","One at a time"],"affirm":"You already hold some limits warmly; that proof you can do firm-and-kind is the foundation to grow the rest from.","relearn":"You already do firm-and-kind somewhere; build the rest from the limits you already hold warmly.","persona":"Suresh","source":"build from proof"},
  {"id":"bc-1032","cat":"discipline-differently","type":"reflect","hook":"Lensy: choosing not to hit, on a hard day, when it's all you were shown, is real courage. Honour that in yourself?","prompt":"What's your take?","options":["I'll honour it","It's courage","Harder than it looks"],"affirm":"Choosing a calm limit over the hand you were raised with, on an exhausting day, is genuine courage worth honouring.","relearn":"Not hitting, on a hard day, when hitting is all you were shown, is real courage — honour it in yourself.","persona":"Suresh","source":"honour the courage"},
  {"id":"bc-1033","cat":"discipline-differently","type":"spot","hook":"Spot the two red-flag 'discipline' moves that frighten instead of teach.","scene":[{"id":"a","text":"Naming the rule and the reason calmly","trick":false},{"id":"b","text":"Raising a hand to threaten a hit","trick":true},{"id":"c","text":"Offering a small choice within the limit","trick":false},{"id":"d","text":"Calling the child stupid to shame them","trick":true},{"id":"e","text":"Staying warm while holding the limit","trick":false}],"why":"Threatening to hit and shaming with names frighten and wound; the others teach a child without fear.","relearn":"The red flags are threatening a hit and shaming with names; calm reasons, small choices and warmth teach instead.","persona":"any","source":"spot frightening moves"},
  {"id":"bc-1034","cat":"discipline-differently","type":"spot","hook":"Spot the two lines that are shame, not discipline.","scene":[{"id":"a","text":"\"That wasn't okay; let's fix it together.\"","trick":false},{"id":"b","text":"\"You're a disgrace to this family.\"","trick":true},{"id":"c","text":"\"I know you can make a better choice.\"","trick":false},{"id":"d","text":"\"No wonder no one wants to play with you.\"","trick":true},{"id":"e","text":"\"Mistakes happen; what's our plan?\"","trick":false}],"why":"Calling a child a disgrace or unwanted attacks their worth; the others correct the behaviour without shaming the child.","relearn":"Shame attacks the child ('a disgrace', 'no one wants you'); discipline names the act and offers a way forward.","persona":"any","source":"spot the shame"},
  {"id":"bc-1035","cat":"discipline-differently","type":"spot","hook":"Spot the two beliefs that keep the old harsh cycle running.","scene":[{"id":"a","text":"\"I can learn discipline that doesn't hurt.\"","trick":false},{"id":"b","text":"\"Kids only understand a beating.\"","trick":true},{"id":"c","text":"\"A calm limit can be firm too.\"","trick":false},{"id":"d","text":"\"Sparing the rod spoils the child.\"","trick":true},{"id":"e","text":"\"Warmth and rules go together.\"","trick":false}],"why":"'Only a beating works' and 'spare the rod, spoil the child' justify hitting; the others open the door to discipline without harm.","relearn":"The cycle-keeping beliefs are 'only a beating works' and 'spare the rod'; learning, calm limits and warmth break it.","persona":"Suresh","source":"spot cycle beliefs"},
  {"id":"bc-1036","cat":"discipline-differently","type":"spot","hook":"Spot the two responses to a tantrum that pour fuel on it.","scene":[{"id":"a","text":"Getting down to their level, lowering your voice","trick":false},{"id":"b","text":"Shouting louder than the child","trick":true},{"id":"c","text":"Naming the feeling: 'you're so angry'","trick":false},{"id":"d","text":"Threatening a thrashing if they don't stop","trick":true},{"id":"e","text":"Holding the limit calmly while they cry","trick":false}],"why":"Out-shouting a child and threatening a thrashing escalate fear; a low voice, naming the feeling and a calm limit settle it.","relearn":"Shouting louder and threatening a thrashing fuel a tantrum; a low voice, named feelings and a calm limit settle it.","persona":"any","source":"spot tantrum fuel"},
  {"id":"bc-1037","cat":"discipline-differently","type":"spot","hook":"Spot the two 'consequences' that punish without teaching anything.","scene":[{"id":"a","text":"Spilt it → help wipe it up","trick":false},{"id":"b","text":"A full day with no food","trick":true},{"id":"c","text":"Skipped homework → finish before play","trick":false},{"id":"d","text":"Locked alone in a dark room","trick":true},{"id":"e","text":"Threw the toy → toy rests for the day","trick":false}],"why":"Withholding food and locking a child in the dark frighten and harm; the others are related, fair consequences that teach.","relearn":"Starving or locking a child away harms, not teaches; a related, fair consequence is what actually teaches the lesson.","persona":"any","source":"spot harmful consequences"},
  {"id":"bc-1038","cat":"discipline-differently","type":"spot","hook":"Spot the two moves that humiliate a child in front of others.","scene":[{"id":"a","text":"A quiet word aside, away from the group","trick":false},{"id":"b","text":"Scolding them loudly in front of guests","trick":true},{"id":"c","text":"Letting them save face while holding the rule","trick":false},{"id":"d","text":"Mocking their crying for everyone to see","trick":true},{"id":"e","text":"Stepping out together to talk it through","trick":false}],"why":"Loud public scolding and mocking a child's tears humiliate; a quiet word, saving face and stepping out keep their dignity.","relearn":"Public scolding and mocking tears humiliate; correct a child privately so they keep their dignity.","persona":"Vikram","source":"spot humiliation"},
  {"id":"bc-1039","cat":"discipline-differently","type":"role-play","hook":"Your child threw their plate in anger. The old script wants to hit; you choose firm-and-kind.","setup":"Hold the limit warmly:","yourLine":[{"text":"\"I won't let you throw things. You're angry — that's okay — but the plate stays. Let's pick it up together.\"","best":true},{"text":"\"Throw one more thing and you'll really get it.\""}],"relearn":"Blocking the harm, allowing the feeling and holding the limit teaches self-control far better than a threat.","persona":"Suresh","source":"thrown plate"},
  {"id":"bc-1040","cat":"discipline-differently","type":"role-play","hook":"A relative scolds your child harshly and looks to you to pile on. You set a calm boundary.","setup":"Step in gently:","yourLine":[{"text":"\"I've got this one — we handle it calmly in our home. Come here, beta, let's talk.\"","best":true},{"text":"\"You heard them — now say sorry before I lose my temper too.\""}],"relearn":"Calmly taking over from a harsh relative protects the child and models the firm-and-kind way without a public clash.","persona":"Vikram","source":"relative scolds"},
  {"id":"bc-1041","cat":"discipline-differently","type":"role-play","hook":"Your child keeps interrupting and won't settle for dinner. You're tired but want to stay firm-and-kind.","setup":"Set the limit kindly:","yourLine":[{"text":"\"I can hear you have lots to say. First we sit and eat, then it's all yours — I promise to listen.\"","best":true},{"text":"\"Quiet! One more word and there's no dinner for you.\""}],"relearn":"Acknowledging the need and holding the limit, with a promise you keep, works better than a threat that punishes.","persona":"any","source":"interrupting dinner"},
  {"id":"bc-1042","cat":"discipline-differently","type":"role-play","hook":"Your child admits they cheated on a class test, scared of your reaction. You want honesty to feel safe.","setup":"Respond so truth stays safe:","yourLine":[{"text":"\"Thank you for telling me — that took courage. Let's talk about why, and how to make it right.\"","best":true},{"text":"\"You cheated? You've shamed us — wait till I deal with you.\""}],"relearn":"Welcoming the honest admission keeps a child telling you the truth; a furious reaction teaches them to hide it next time.","persona":"Suresh","source":"admitting cheating"},
  {"id":"bc-1043","cat":"discipline-differently","type":"role-play","hook":"Your child refuses to do homework and slams the book down. You feel the urge to grab their ear.","setup":"Offer a choice within the limit:","yourLine":[{"text":"\"Homework happens before play — that part's fixed. You choose: at the table now, or after a ten-minute break?\"","best":true},{"text":"\"Do it now or I'll give you something to cry about.\""}],"relearn":"A fixed limit plus a small real choice gives a child control without dropping the rule, and skips the power struggle.","persona":"any","source":"homework choice"},
  {"id":"bc-1044","cat":"discipline-differently","type":"role-play","hook":"Your child says 'I hate you!' after you held a limit. The old reflex is to crush that back.","setup":"Stay steady and warm:","yourLine":[{"text":"\"You're really angry with me right now, and that's allowed. I still love you, and the answer's still no.\"","best":true},{"text":"\"How dare you say that to me — apologise this instant!\""}],"relearn":"Letting a child's angry words be, while holding the limit and the love, teaches that big feelings don't break the bond.","persona":"any","source":"i hate you"},
  {"id":"bc-1045","cat":"discipline-differently","type":"role-play","hook":"In a crowded market your child grabs sweets and starts to wail for them. You feel watched and tense.","setup":"Hold firm without fear:","yourLine":[{"text":"\"Not today — I know that's disappointing. We'll put them back and find you a treat at home.\"","best":true},{"text":"\"Stop embarrassing me — do you want everyone to see you get a hiding?\""}],"relearn":"Naming the disappointment and holding the 'no' calmly settles a public scene better than threatening or shaming.","persona":"Vikram","source":"market sweets"},
  {"id":"bc-1046","cat":"discipline-differently","type":"role-play","hook":"Your child broke a rule you'd been clear about. You want a consequence that teaches, not wounds.","setup":"Deliver it calmly:","yourLine":[{"text":"\"We agreed no screens after bedtime, so the tablet stays with me tomorrow. We'll try again, together.\"","best":true},{"text":"\"That's it — no screens for a month, and don't test me again.\""}],"relearn":"A clear, related, time-limited consequence delivered calmly teaches the limit; a huge, angry ban only breeds resentment.","persona":"any","source":"clear consequence"},
  {"id":"bc-1047","cat":"discipline-differently","type":"sort","hook":"Sort: what firm-and-kind discipline grows in a child, or what fear-based discipline grows?","items":[{"id":"a","text":"Confidence to admit mistakes"},{"id":"b","text":"Learning to lie and hide"},{"id":"c","text":"Trust that you're on their side"},{"id":"d","text":"Flinching when you raise your voice"},{"id":"e","text":"Self-control they copy from you"},{"id":"f","text":"Belief that force solves problems"}],"bins":[{"id":"firm","label":"Firm-and-kind grows","valence":"pos"},{"id":"fear","label":"Fear grows","valence":"neg"}],"key":{"a":"firm","b":"fear","c":"firm","d":"fear","e":"firm","f":"fear"},"relearn":"Firm-and-kind grows confidence, trust and self-control; fear grows hiding, flinching and a belief that force wins.","persona":"any","source":"what it grows"},
  {"id":"bc-1048","cat":"discipline-differently","type":"match","hook":"Match each everyday slip-up to the calm, teaching response.","pairs":[{"left":"Spilled milk rushing about","right":"'Accidents happen — grab a cloth'"},{"left":"Forgot to pack their bag","right":"A reminder routine, not a rant"},{"left":"Loud during your phone call","right":"A quiet hand-signal you agreed on"},{"left":"Won't wear shoes to leave","right":"'Shoes on, or I carry you?' — a choice"},{"left":"Rough with the family pet","right":"Show gentle hands, stay close"}],"relearn":"Everyday slips meet calm teaching — a cloth, a routine, a signal, a choice, a gentle demo — not a rant or a smack.","persona":"any","source":"everyday slips"},
  {"id":"bc-1049","cat":"discipline-differently","type":"match","hook":"Match each thing you want your child to learn to the way they actually learn it.","pairs":[{"left":"How to handle anger","right":"Watching you stay calm"},{"left":"That mistakes are safe","right":"Your gentle response to theirs"},{"left":"To treat others kindly","right":"Being treated kindly themselves"},{"left":"To respect limits","right":"Limits held warmly and consistently"},{"left":"To say sorry","right":"Hearing you say it too"}],"relearn":"Children learn anger, safety, kindness, limits and apology mostly by watching how you do them — not from punishment.","persona":"any","source":"how kids learn"},
  {"id":"bc-1050","cat":"discipline-differently","type":"spot","hook":"Spot the two beliefs that secretly excuse hitting a child.","scene":[{"id":"a","text":"\"A clear limit can be held calmly.\"","trick":false},{"id":"b","text":"\"Some kids only learn through pain.\"","trick":true},{"id":"c","text":"\"My child can learn without fear.\"","trick":false},{"id":"d","text":"\"It's discipline, not violence, if I love them.\"","trick":true},{"id":"e","text":"\"Warmth and firmness work together.\"","trick":false}],"why":"'Only pain teaches' and 'love makes it not violence' both excuse hitting; the others hold discipline without harm.","relearn":"Two beliefs excuse hitting: 'only pain teaches' and 'love makes it not violence'; neither is true, and calm limits work.","persona":"Suresh","source":"spot the excuses"},
  {"id":"bc-1080","type":"strike-rewrite","persona":"Suresh","source":"buried not gone","hook":"\"What happened to me as a child is over and forgotten; it can't touch my kids.\"","myth":{"un":"What happened to me as a child is over and forgotten; it can't touch my kids.","re":"Pain you never tended doesn't vanish; it surfaces in your triggers and slips onto the people you love most.","why":"Buried isn't gone; untended wounds leak into the present."},"relearn":"Untended childhood pain doesn't disappear; it resurfaces in your triggers until you tend it.","cat":"heal-your-wounds"},
  {"id":"bc-1081","type":"strike-rewrite","persona":"any","source":"feeling it isn't weak","hook":"\"If I let myself feel the old hurt, I'll fall apart and won't cope.\"","myth":{"un":"If I let myself feel the old hurt, I'll fall apart and won't cope.","re":"Feeling it with support, a little at a time, is how it loses its grip; what you won't feel keeps running you.","why":"Felt and tended, pain softens; avoided, it stays in charge."},"relearn":"Gently feeling old hurt with support loosens its grip; avoiding it leaves it controlling your reactions.","cat":"heal-your-wounds"},
  {"id":"bc-1082","type":"strike-rewrite","persona":"Suresh","source":"forgiveness not required","hook":"\"To heal I must forgive my parents fully, or I'm a bad son.\"","myth":{"un":"To heal I must forgive my parents fully, or I'm a bad son.","re":"Healing is about tending your wound and your parenting now; forgiveness can come, or not, in its own time.","why":"You can stop the harm without forcing forgiveness."},"relearn":"Healing means tending your wound and your parenting; forgiving your parents isn't a precondition or a test.","cat":"heal-your-wounds"},
  {"id":"bc-1083","type":"strike-rewrite","persona":"any","source":"not too late","hook":"\"I'm a grown adult now; it's too late to do anything about my childhood.\"","myth":{"un":"I'm a grown adult now; it's too late to do anything about my childhood.","re":"It's never too late to tend an old wound; adults heal and change patterns at any age, and your child benefits now.","why":"Healing has no expiry; tending it still changes today."},"relearn":"It's never too late to tend a childhood wound; healing at any age changes how you parent today.","cat":"heal-your-wounds"},
  {"id":"bc-1084","type":"strike-rewrite","persona":"Suresh","source":"not your fault","hook":"\"I was raised with the belt and the silence, so deep down it must be what I deserved.\"","myth":{"un":"I was raised with the belt and the silence, so deep down it must be what I deserved.","re":"If you grew up with harsh discipline, it wasn't your fault and you didn't deserve it; you can choose differently now.","why":"A child is never to blame for how they were treated."},"relearn":"Growing up with harsh discipline was never your fault; you didn't deserve it, and you can choose differently now.","cat":"heal-your-wounds"},
  {"id":"bc-1085","type":"strike-rewrite","persona":"any","source":"healing helps kids","hook":"\"Working on my own past is selfish; my energy should all go to my kids.\"","myth":{"un":"Working on my own past is selfish; my energy should all go to my kids.","re":"Tending your wounds is for your kids: a calmer, less-triggered you is the surest gift you give them.","why":"You can't pour from a wound you keep open."},"relearn":"Tending your own wounds isn't selfish; a calmer, less-triggered parent is a direct gift to your child.","cat":"heal-your-wounds"},
  {"id":"bc-1086","type":"strike-rewrite","persona":"any","source":"triggers are signals","hook":"\"When my child's crying enrages me out of nowhere, that's just my bad temper.\"","myth":{"un":"When my child's crying enrages me out of nowhere, that's just my bad temper.","re":"A reaction far bigger than the moment is often an old wound speaking; naming it is the first step to easing it.","why":"Outsized reactions point to something older underneath."},"relearn":"A reaction far bigger than the moment often signals an old wound; naming it is the first step to easing it.","cat":"heal-your-wounds"},
  {"id":"bc-1087","type":"strike-rewrite","persona":"Suresh","source":"talking helps","hook":"\"Real men in my family don't talk about feelings; you just carry it and get on.\"","myth":{"un":"Real men in my family don't talk about feelings; you just carry it and get on.","re":"Carrying it silently is how the pain passed down to you; naming it to someone safe is what breaks that chain.","why":"Silence is how the wound was inherited; voicing it stops it."},"relearn":"Carrying pain in silence is how it gets passed down; voicing it to someone safe is what breaks the chain.","cat":"heal-your-wounds"},
  {"id":"bc-1088","type":"strike-rewrite","persona":"any","source":"slow not instant","hook":"\"If healing were real, I'd feel fixed by now; since I don't, it isn't working.\"","myth":{"un":"If healing were real, I'd feel fixed by now; since I don't, it isn't working.","re":"Healing isn't a switch; it's gradual, with hard days mixed in, and each step still means less leaks onto your child.","why":"Slow and uneven is what real healing looks like."},"relearn":"Healing is gradual, not a switch; hard days are normal, and each step still means less pain leaks onto your child.","cat":"heal-your-wounds"},
  {"id":"bc-1089","type":"strike-rewrite","persona":"any","source":"good memories too","hook":"\"There were good times too, so I've no right to call any of my childhood a wound.\"","myth":{"un":"There were good times too, so I've no right to call any of my childhood a wound.","re":"Good memories and real hurt can both be true; honouring the love doesn't mean denying what wounded you.","why":"Two things can be true; love doesn't erase the hurt."},"relearn":"Good memories and real hurt can both be true; honouring the love doesn't mean you must deny what wounded you.","cat":"heal-your-wounds"},
  {"id":"bc-1090","type":"strike-rewrite","persona":"any","source":"support is signposting","hook":"\"Reaching out to a helpline is only for people who are truly broken, not me.\"","myth":{"un":"Reaching out to a helpline is only for people who are truly broken, not me.","re":"Support like Tele-MANAS 14416 is for any parent tending a heavy load, not just a crisis; you don't have to wait to deserve it.","why":"Help is for tending wounds, not only emergencies."},"relearn":"A support line like Tele-MANAS 14416 is for any parent carrying a heavy load, not only those in crisis.","cat":"heal-your-wounds"},
  {"id":"bc-1091","type":"reflect","persona":"any","source":"the child you were","hook":"Lensy: the small child you once were deserved gentleness too, not just your own kids. Let that land?","prompt":"What's your take?","options":["Let it land","They did","I see them"],"affirm":"The child you once were deserved care and gentleness too; offering it to that child now is part of how you heal.","relearn":"The child you once were deserved gentleness too; offering it to that younger self is part of healing.","cat":"heal-your-wounds"},
  {"id":"bc-1092","type":"reflect","persona":"Suresh","source":"naming it aloud","hook":"Lensy: simply naming what happened to you, out loud or on paper, can loosen its hold. Worth a try?","prompt":"How does that sit?","options":["Worth a try","Naming it","I could"],"affirm":"Naming what happened to you is the first step of healing; it turns a vague ache into something you can begin to tend.","relearn":"Naming what happened to you is the first step of healing; it makes an old ache something you can tend.","cat":"heal-your-wounds"},
  {"id":"bc-1093","type":"reflect","persona":"any","source":"you broke pattern already","hook":"Lensy: the very fact you're here, looking at this, means you're already breaking the pattern. Feel that?","prompt":"What's your take?","options":["Feel it","Already started","That's me"],"affirm":"The fact that you're examining this at all means you've already begun breaking the pattern; that's not nothing, it's everything.","relearn":"Choosing to look at your own patterns at all means you've already begun to break them.","cat":"heal-your-wounds"},
  {"id":"bc-1094","type":"reflect","persona":"any","source":"grieve what you missed","hook":"Lensy: it's okay to feel sad for the care you didn't get as a child. Grief like that is allowed here.","prompt":"How does that sit?","options":["It's allowed","I feel it","Okay to grieve"],"affirm":"Allowing yourself to grieve the care you didn't receive isn't self-pity; it's part of processing it so less of it leaks forward.","relearn":"Grieving the care you didn't receive as a child is part of processing it, so less of it leaks onto your kids.","cat":"heal-your-wounds"},
  {"id":"bc-1095","type":"reflect","persona":"Suresh","source":"slow progress counts","hook":"Lensy: you don't have to heal it all at once; one honest look today is real progress. Sit right?","prompt":"What's your take?","options":["Sits right","One look","That counts"],"affirm":"You don't have to heal everything at once; each small, honest moment of tending an old wound is genuine progress.","relearn":"Healing happens in small steps; each honest moment of tending an old wound is real progress, not all-or-nothing.","cat":"heal-your-wounds"},
  {"id":"bc-1096","type":"reflect","persona":"any","source":"compassion for younger self","hook":"Lensy: if a small child told you what was done to you, you'd be gentle with them. Offer that to yourself?","prompt":"How does that sit?","options":["I'll try","Be gentle","To myself too"],"affirm":"The compassion you'd offer a hurt child is the same compassion your younger self has been waiting for from you.","relearn":"Offer your younger self the same compassion you'd give any hurt child; it's part of how the wound eases.","cat":"heal-your-wounds"},
  {"id":"bc-1097","type":"reflect","persona":"any","source":"not passing it down","hook":"Lensy: every bit of pain you tend in yourself is a bit your child and their child never inherit. Resonate?","prompt":"What's your take?","options":["Resonates","Stops here","For them all"],"affirm":"Tending your pain doesn't just spare your child; it can spare generations after, because the cycle stops here, with you.","relearn":"Tending your own pain can spare not just your child but generations after; the cycle can stop here, with you.","cat":"heal-your-wounds"},
  {"id":"bc-1098","type":"reflect","persona":"Divya","source":"rest is healing too","hook":"Lensy: rest, a kind word to yourself, a quiet breath; these are healing too, not luxuries. Feel that?","prompt":"How does that sit?","options":["Feel it","Not a luxury","I'll allow it"],"affirm":"Rest and self-kindness aren't indulgences you must earn; for a depleted parent, they're part of the healing itself.","relearn":"Rest and self-kindness aren't luxuries to earn; for a tired parent they're part of healing, not separate from it.","cat":"heal-your-wounds"},
  {"id":"bc-1099","type":"reflect","persona":"any","source":"you are not the wound","hook":"Lensy: what was done to you is something that happened; it isn't who you are. Let that breathe?","prompt":"What's your take?","options":["Let it breathe","Not who I am","It happened"],"affirm":"What happened to you is part of your story, not your identity; you are the one choosing, today, to tend it and change.","relearn":"What happened to you is part of your story, not who you are; you're the one choosing to tend it now.","cat":"heal-your-wounds"},
  {"id":"bc-1100","type":"reflect","persona":"Suresh","source":"asking is courage","hook":"Lensy: reaching for help with your own past takes real courage, the kind you're already showing. Sit right?","prompt":"How does that sit?","options":["Sits right","It's courage","I'm trying"],"affirm":"Reaching for support with your own past isn't a sign of weakness; it's one of the bravest, most loving things a parent does.","relearn":"Reaching for support with your own past is courage, not weakness; it's a loving act for you and your child.","cat":"heal-your-wounds"},
  {"id":"bc-1101","type":"reflect","persona":"any","source":"both parent and child","hook":"Lensy: you can be the parent your child needs and the hurt person who needs care, at once. Both are okay.","prompt":"What's your take?","options":["Both okay","I'm both","That's me"],"affirm":"You can hold both: a parent showing up for your child, and a person who still needs care for old wounds. Both are true and allowed.","relearn":"You can be both the parent showing up and the person who still needs care; holding both is part of healing.","cat":"heal-your-wounds"},
  {"id":"bc-1102","type":"sort","persona":"any","source":"heals vs reopens","hook":"Sort: does this help an old wound heal, or keep it raw?","items":[{"id":"a","text":"Naming what happened, kindly"},{"id":"b","text":"Telling yourself to just get over it"},{"id":"c","text":"Talking to someone safe about it"},{"id":"d","text":"Drinking to push the feeling down"},{"id":"e","text":"Letting yourself grieve it"},{"id":"f","text":"Pretending it never affected you"}],"bins":[{"id":"heals","label":"Helps it heal","valence":"pos"},{"id":"raw","label":"Keeps it raw","valence":"neg"}],"key":{"a":"heals","b":"raw","c":"heals","d":"raw","e":"heals","f":"raw"},"relearn":"Naming, talking and grieving help an old wound heal; dismissing, numbing and pretending keep it raw.","cat":"heal-your-wounds"},
  {"id":"bc-1103","type":"sort","persona":"any","source":"steps vs detours","hook":"Sort: a real step of healing, or a detour that stalls it?","items":[{"id":"a","text":"Understanding what triggers you"},{"id":"b","text":"Blaming yourself for being affected"},{"id":"c","text":"Reaching out for support"},{"id":"d","text":"Waiting until you feel 'ready enough'"},{"id":"e","text":"Processing the grief slowly"},{"id":"f","text":"Comparing your pain to others' and dismissing it"}],"bins":[{"id":"step","label":"A real step","valence":"pos"},{"id":"detour","label":"A stalling detour","valence":"uhoh"}],"key":{"a":"step","b":"detour","c":"step","d":"detour","e":"step","f":"detour"},"relearn":"Understanding triggers, reaching out and processing grief move healing forward; self-blame, waiting and dismissing stall it.","cat":"heal-your-wounds"},
  {"id":"bc-1104","type":"sort","persona":"Suresh","source":"keep vs set down","hook":"Sort: from your own upbringing, keep this, or gently set it down?","items":[{"id":"a","text":"The warmth at family meals"},{"id":"b","text":"Hitting when a child errs"},{"id":"c","text":"Showing up for relatives in need"},{"id":"d","text":"Silence instead of saying sorry"},{"id":"e","text":"Hard work and looking after your own"},{"id":"f","text":"Fear as the way to get respect"}],"bins":[{"id":"keep","label":"Keep the good","valence":"pos"},{"id":"setdown","label":"Set it down","valence":"neg"}],"key":{"a":"keep","b":"setdown","c":"keep","d":"setdown","e":"keep","f":"setdown"},"relearn":"You can keep the warmth, loyalty and care from your upbringing and set down the hitting, silence and fear.","cat":"heal-your-wounds"},
  {"id":"bc-1105","type":"sort","persona":"any","source":"self-talk heals or wounds","hook":"Sort: would you say this to a hurt friend, or only to yourself?","items":[{"id":"a","text":"\"That wasn't your fault.\""},{"id":"b","text":"\"You should be over this by now.\""},{"id":"c","text":"\"It makes sense that it still hurts.\""},{"id":"d","text":"\"You're weak for letting it get to you.\""},{"id":"e","text":"\"You deserved care back then.\""},{"id":"f","text":"\"Stop being so dramatic about it.\""}],"bins":[{"id":"kind","label":"Kind & healing","valence":"pos"},{"id":"harsh","label":"Harsh & wounding","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"The kindness you'd give a hurt friend, 'not your fault', 'it makes sense it hurts', is the self-talk that heals.","cat":"heal-your-wounds"},
  {"id":"bc-1106","type":"sort","persona":"any","source":"in scope vs route on","hook":"Sort: a wobble you can sit with, or a load to route to support?","items":[{"id":"a","text":"A wave of sadness while reflecting"},{"id":"b","text":"Flashbacks that flood you daily"},{"id":"c","text":"Feeling tender after an honest journal"},{"id":"d","text":"Thoughts of harming yourself"},{"id":"e","text":"Naming a trigger and breathing through it"},{"id":"f","text":"Pain so heavy you can't function"}],"bins":[{"id":"sit","label":"Can sit with it","valence":"pos"},{"id":"route","label":"Route to support","valence":"tell"}],"key":{"a":"sit","b":"route","c":"sit","d":"route","e":"sit","f":"route"},"relearn":"Tender feelings while reflecting you can sit with; daily flashbacks, self-harm thoughts or pain you can't carry route to Tele-MANAS 14416.","cat":"heal-your-wounds"},
  {"id":"bc-1107","type":"sort","persona":"any","source":"protects child vs passes pain","hook":"Sort: does this protect your child from your wound, or pass it to them?","items":[{"id":"a","text":"Pausing when an old trigger fires"},{"id":"b","text":"Snapping the moment you're reminded"},{"id":"c","text":"Repairing after you're triggered"},{"id":"d","text":"Expecting your child to soothe you"},{"id":"e","text":"Getting support for the underlying pain"},{"id":"f","text":"Calling them names you were called"}],"bins":[{"id":"protect","label":"Protects them","valence":"pos"},{"id":"pass","label":"Passes it on","valence":"neg"}],"key":{"a":"protect","b":"pass","c":"protect","d":"pass","e":"protect","f":"pass"},"relearn":"Pausing, repairing and getting support protect your child from your wound; snapping, leaning on them and old names pass it on.","cat":"heal-your-wounds"},
  {"id":"bc-1108","type":"sort","persona":"Suresh","source":"myth vs truth past","hook":"Sort: an old myth about your past, or the truer thing?","items":[{"id":"a","text":"\"It's too late to change anything.\""},{"id":"b","text":"\"I can choose differently now.\""},{"id":"c","text":"\"Talking about it makes me weak.\""},{"id":"d","text":"\"Naming it is the first step.\""},{"id":"e","text":"\"I must've deserved it.\""},{"id":"f","text":"\"A child is never to blame.\""}],"bins":[{"id":"myth","label":"Old myth","valence":"neg"},{"id":"truth","label":"The truer thing","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"'Too late', 'talking is weak', 'I deserved it' are old myths; 'I can choose now', 'naming is the first step', 'a child is never to blame' are true.","cat":"heal-your-wounds"},
  {"id":"bc-1109","type":"sort","persona":"any","source":"who can support","hook":"Sort: a steady place to take old pain, or one that can deepen it?","items":[{"id":"a","text":"Tele-MANAS 14416 counsellor"},{"id":"b","text":"The relative who minimised it then"},{"id":"c","text":"A trusted, kind friend"},{"id":"d","text":"Bottling it and saying nothing"},{"id":"e","text":"A support group of other parents"},{"id":"f","text":"Anyone who shames you for feeling it"}],"bins":[{"id":"steady","label":"A steady place","valence":"pos"},{"id":"deepens","label":"Can deepen it","valence":"uhoh"}],"key":{"a":"steady","b":"deepens","c":"steady","d":"deepens","e":"steady","f":"deepens"},"relearn":"A counsellor, a kind friend or a parents' group are steady places for old pain; minimisers, silence and shamers can deepen it.","cat":"heal-your-wounds"},
  {"id":"bc-1110","type":"branch","persona":"Suresh","source":"trigger at bedtime","hook":"Your child's bedtime whining sends a hot rush through you, far too big for the moment.","options":[{"text":"Notice it as an old wound, breathe, and tend it later, not now","consequence":"You catch the old reflex and keep the moment safe.","outcome":"caught","best":true},{"text":"Let it explode because 'that's just how I am'","consequence":"Acting on the old wound passes it to your child."}],"debrief":"A reaction far bigger than the moment is often an old wound; noticing it lets you tend it, not pass it on.","relearn":"When a reaction dwarfs the moment, treat it as an old wound to tend, not a fact about who you are.","cat":"heal-your-wounds"},
  {"id":"bc-1111","type":"branch","persona":"any","source":"old memory surfaces","hook":"A memory of how you were punished as a child surfaces while you're with your kids.","options":[{"text":"Note it kindly to sit with later, when you have space","consequence":"You honour it without it hijacking the moment.","outcome":"noted","best":true},{"text":"Shove it away and pretend it didn't come up","consequence":"Shoving it down keeps it surfacing at the worst times."}],"debrief":"You needn't process a surfacing memory on the spot; noting it to tend later keeps it from hijacking you.","relearn":"When an old memory surfaces, note it to tend later, don't shove it away; what's buried keeps resurfacing.","cat":"heal-your-wounds"},
  {"id":"bc-1112","type":"branch","persona":"any","source":"heavy after reflecting","hook":"After reflecting on your childhood, you feel heavier than expected for a few days.","options":[{"text":"Reach out to Tele-MANAS 14416 or a counsellor to process it","consequence":"You get a steady hand for a heavy load.","outcome":"supported","best":true},{"text":"Decide reflecting was a mistake and never look again","consequence":"Slamming the door leaves the wound untended and active."}],"debrief":"Feeling heavier after looking is normal; that's the moment to reach for support, not slam the door.","relearn":"If your past leaves you heavy, reach for support like Tele-MANAS 14416; don't slam the door on healing.","cat":"heal-your-wounds"},
  {"id":"bc-1113","type":"branch","persona":"Suresh","source":"father comment","hook":"At a gathering your father jokes that a few slaps 'made you who you are' and everyone laughs.","options":[{"text":"Quietly hold your own truth, no public fight","consequence":"You keep your boundary without inflaming the room.","outcome":"steady","best":true},{"text":"Decide he's right and your doubts are nonsense","consequence":"Swallowing it re-buries the wound you'd begun to tend."}],"debrief":"You can love your father and still privately hold that you're choosing differently; no need to win the room.","relearn":"You can hold your truth quietly, choosing differently, without a public fight or buying the old line.","cat":"heal-your-wounds"},
  {"id":"bc-1114","type":"branch","persona":"any","source":"partner dismisses","hook":"You open up to your partner about your past and they say, 'Why dig all that up now?'","options":[{"text":"Explain it's surfacing in your parenting; seek a counsellor if they can't hold it","consequence":"You keep tending the wound without their support.","outcome":"persist","best":true},{"text":"Agree it's pointless and bury it to keep the peace","consequence":"Burying it for peace leaves it leaking into how you parent."}],"debrief":"Not everyone can hold your healing; you can keep tending it with support.","relearn":"If those near you can't hold your healing, keep tending it with a counsellor or Tele-MANAS 14416.","cat":"heal-your-wounds"},
  {"id":"bc-1115","type":"branch","persona":"any","source":"naming the wound","hook":"You sense a specific old hurt is behind your sharpest reactions, but you've never named it.","options":[{"text":"Name it plainly on paper, kindly and without blame","consequence":"Naming it turns a vague ache into something you can tend.","outcome":"named","best":true},{"text":"Keep it vague so you never have to feel it","consequence":"Vague and unfelt, it keeps driving your reactions."}],"debrief":"Naming what happened, without self-blame, is the first step; a vague ache you won't face keeps steering you.","relearn":"Naming an old hurt plainly and kindly is healing's first step; vague and unfelt, it keeps driving you.","cat":"heal-your-wounds"},
  {"id":"bc-1116","type":"branch","persona":"any","source":"fear of harming child","hook":"Overwhelm from your past flares, and an urge to lash out at your child frightens you.","options":[{"text":"If safe, step away, then get help (Tele-MANAS 14416; danger: Childline 1098 or 112)","consequence":"You keep your child safe and get help.","outcome":"safe","best":true},{"text":"Push through alone and hope it passes","consequence":"White-knuckling a dangerous urge alone risks harm."}],"debrief":"A frightening urge means step away to keep your child safe; that fear shows you're trying.","relearn":"If you fear harming your child, step away if safe and get help, Tele-MANAS 14416; in danger Childline 1098 or 112.","cat":"heal-your-wounds"},
  {"id":"bc-1117","type":"branch","persona":"any","source":"healing not linear","hook":"You'd been calmer for weeks, then a bad week of old reactions makes you feel back to square one.","options":[{"text":"Treat the slip as part of a long road, not proof it's hopeless","consequence":"You stay on the path and the calmer weeks return.","outcome":"persist","best":true},{"text":"Conclude healing is fake and give up","consequence":"Quitting at the first hard week ends the progress you'd made."}],"debrief":"Healing isn't a straight line; a hard week after good ones is normal, not proof it's hopeless.","relearn":"Healing isn't linear; a hard week after calmer ones is part of the road, not failure. Keep going.","cat":"heal-your-wounds"},
  {"id":"bc-1118","type":"match","persona":"any","source":"trigger to root","hook":"Match each parenting trigger to the old wound it can point back to.","pairs":[{"left":"Rage at your child's tears","right":"Being told boys don't cry"},{"left":"Panic when they make a mess","right":"Punishment for any small slip"},{"left":"Going cold when they defy you","right":"Silence used against you as a child"},{"left":"Dread when they're disappointed in you","right":"A parent impossible to please"},{"left":"Flinching at raised voices","right":"A home that often shouted"}],"relearn":"Outsized parenting triggers often point back to specific old wounds; naming that link is where tending them begins.","cat":"heal-your-wounds"},
  {"id":"bc-1119","type":"match","persona":"any","source":"feeling to kind response","hook":"Match each hard feeling about your past to a kind way to meet it.","pairs":[{"left":"Grief for the care you missed","right":"Let yourself mourn it, with support"},{"left":"Shame that it still affects you","right":"Remind yourself it makes sense"},{"left":"Anger at how you were treated","right":"Allow it; it doesn't make you bad"},{"left":"Fear of becoming your parent","right":"Notice it as a sign you're changing"},{"left":"Numbness when you try to look","right":"Go slow; reach for a counsellor"}],"relearn":"Each hard feeling about your past has a kind response; meeting it gently, with support, is how it loosens its grip.","cat":"heal-your-wounds"},
  {"id":"bc-1120","type":"match","persona":"any","source":"myth to truth","hook":"Match each old myth about healing to the truth that replaces it.","pairs":[{"left":"\"It's too late for me\"","right":"Adults heal at any age"},{"left":"\"Asking for help is weak\"","right":"Reaching out is real courage"},{"left":"\"I must've deserved it\"","right":"A child is never to blame"},{"left":"\"I should be over it\"","right":"Healing is gradual, not a switch"},{"left":"\"My past doesn't touch them\"","right":"Untended, it leaks into parenting"}],"relearn":"Each old myth about healing has a truer replacement; learning the truer line is part of letting the wound heal.","cat":"heal-your-wounds"},
  {"id":"bc-1121","type":"match","persona":"any","source":"who helps with what","hook":"Match each support route to what it's there for.","pairs":[{"left":"Tele-MANAS 14416","right":"Your own heavy feelings & past"},{"left":"A trusted friend","right":"Being heard without judgement"},{"left":"A parents' support group","right":"Knowing you're not the only one"},{"left":"Childline 1098","right":"A child in real danger"},{"left":"Be the Safe Adult (g69)","right":"In-app child-safety routing"}],"relearn":"Different routes fit different needs: Tele-MANAS 14416 for your own load, Childline 1098 and g69 if a child is at risk.","cat":"heal-your-wounds"},
  {"id":"bc-1122","type":"match","persona":"Suresh","source":"keep good leave harm pairs","hook":"Match each part of your upbringing to keeping the good or leaving the harm.","pairs":[{"left":"Family loyalty and care","right":"Keep, and pass it on"},{"left":"Hitting to correct a child","right":"Leave; it harms, doesn't work"},{"left":"Hard work and providing","right":"Keep; it's a real strength"},{"left":"Silence instead of apology","right":"Leave; repair beats silence"},{"left":"Respect through fear","right":"Leave; respect grows from trust"}],"relearn":"You can keep loyalty, care and hard work from your upbringing and leave the hitting, silence and fear.","cat":"heal-your-wounds"},
  {"id":"bc-1123","type":"match","persona":"any","source":"action to gift to child","hook":"Match each healing action to the gift it quietly gives your child.","pairs":[{"left":"Tending your own triggers","right":"Fewer sharp reactions at them"},{"left":"Naming what happened to you","right":"A parent who models honesty"},{"left":"Getting support for old pain","right":"A calmer home to grow up in"},{"left":"Grieving what you missed","right":"Less of it leaking onto them"},{"left":"Choosing differently now","right":"A cycle that stops with you"}],"relearn":"Every step you take to heal is a quiet gift to your child: fewer sharp reactions, a calmer home, a cycle that stops with you.","cat":"heal-your-wounds"},
  {"id":"bc-1124","type":"match","persona":"any","source":"step to first move","hook":"Match each healing step to a small first move you can actually make this week.","pairs":[{"left":"Noticing your triggers","right":"Jot down what set you off"},{"left":"Naming the wound","right":"Write one honest sentence"},{"left":"Reaching for support","right":"Save the Tele-MANAS number"},{"left":"Being kinder to yourself","right":"Speak to yourself as a friend"},{"left":"Not carrying it alone","right":"Tell one safe person"}],"relearn":"Big healing breaks into small doable moves: jot a trigger, write one sentence, save a number, tell one safe person.","cat":"heal-your-wounds"},
  {"id":"bc-1125","type":"spot","persona":"any","source":"catch the denials","hook":"Spot the two lines that keep an old wound running.","scene":[{"id":"a","text":"\"I'll name what happened, kindly.\"","trick":false},{"id":"b","text":"\"It was nothing; I'm completely fine.\"","trick":true},{"id":"c","text":"\"I'll reach out for some support.\"","trick":false},{"id":"d","text":"\"Real men just bury it and move on.\"","trick":true},{"id":"e","text":"\"It's okay that it still hurts.\"","trick":false}],"why":"'I'm completely fine' and 'just bury it' are denial; insisting you're fine and numbing keep the wound running.","relearn":"Naming the hurt, seeking support and allowing the feeling heal; insisting you're fine and burying it keep it running.","cat":"heal-your-wounds"},
  {"id":"bc-1126","type":"spot","persona":"Suresh","source":"catch self-blame","hook":"Spot the two things you'd never say to a hurt child, so don't say them to yourself.","scene":[{"id":"a","text":"\"That wasn't your fault.\"","trick":false},{"id":"b","text":"\"You should be over this by now.\"","trick":true},{"id":"c","text":"\"You deserved care back then.\"","trick":false},{"id":"d","text":"\"You're weak for letting it hurt.\"","trick":true},{"id":"e","text":"\"It makes sense that it stings.\"","trick":false}],"why":"'Should be over it' and 'you're weak' are harsh self-blame; you'd never say them to a hurt child, so retire them for yourself.","relearn":"Speak to your wounded self as you would a hurt child: 'not your fault', 'you deserved care', not 'get over it' or 'you're weak'.","cat":"heal-your-wounds"},
  {"id":"bc-1127","type":"spot","persona":"any","source":"catch the stalls","hook":"Spot the two excuses that stall healing instead of moving it.","scene":[{"id":"a","text":"\"I'll start with one honest sentence.\"","trick":false},{"id":"b","text":"\"I'll deal with it when I'm fully ready.\"","trick":true},{"id":"c","text":"\"I'll tell one safe person.\"","trick":false},{"id":"d","text":"\"Others had it worse, so mine doesn't count.\"","trick":true},{"id":"e","text":"\"I'll save the Tele-MANAS number.\"","trick":false}],"why":"'When I'm fully ready' and 'others had it worse' are stalls; waiting for perfect readiness and dismissing your pain delay healing.","relearn":"Small steps now move healing; waiting to feel fully ready and dismissing your pain as not bad enough only stall it.","cat":"heal-your-wounds"},
  {"id":"bc-1128","type":"spot","persona":"any","source":"catch leaking onto child","hook":"Spot the two responses that pass your wound straight to your child.","scene":[{"id":"a","text":"Pausing when an old trigger fires","trick":false},{"id":"b","text":"Snapping the second you're reminded","trick":true},{"id":"c","text":"Repairing after you're triggered","trick":false},{"id":"d","text":"Calling them a name you were called","trick":true},{"id":"e","text":"Getting support for the root pain","trick":false}],"why":"Snapping on contact and using the old names pass the wound on; pausing, repairing and getting support protect your child.","relearn":"Pausing, repairing and getting support protect your child; snapping on contact and old names pass the wound straight on.","cat":"heal-your-wounds"},
  {"id":"bc-1129","type":"spot","persona":"any","source":"catch unsafe supports","hook":"Spot the two places that can deepen old pain rather than ease it.","scene":[{"id":"a","text":"A Tele-MANAS 14416 counsellor","trick":false},{"id":"b","text":"The relative who minimised it then","trick":true},{"id":"c","text":"A kind, trusted friend","trick":false},{"id":"d","text":"Anyone who shames you for feeling it","trick":true},{"id":"e","text":"A group of other parents healing too","trick":false}],"why":"A minimiser and a shamer can deepen the wound; take old pain to a counsellor, a kind friend or others healing too.","relearn":"Take old pain to safe places, a counsellor, a kind friend, a parents' group, not to those who minimise or shame you for it.","cat":"heal-your-wounds"},
  {"id":"bc-1130","type":"spot","persona":"Suresh","source":"catch fatalism","hook":"Spot the two fatalist lines that quietly keep the cycle going.","scene":[{"id":"a","text":"\"I can choose differently now.\"","trick":false},{"id":"b","text":"\"We all turn into our parents anyway.\"","trick":true},{"id":"c","text":"\"Naming it is the first step.\"","trick":false},{"id":"d","text":"\"It's too late to change at my age.\"","trick":true},{"id":"e","text":"\"Tending this protects my kids.\"","trick":false}],"why":"'We all turn into our parents' and 'too late to change' are fatalism; the inheritance isn't destiny and it's never too late.","relearn":"The inheritance isn't destiny and it's never too late; fatalist lines like 'too late' quietly keep the cycle going.","cat":"heal-your-wounds"},
  {"id":"bc-1131","type":"spot","persona":"any","source":"catch not-therapy overreach","hook":"Spot the two beliefs that expect this game to do what real care should.","scene":[{"id":"a","text":"\"This points me toward support.\"","trick":false},{"id":"b","text":"\"This alone will cure my trauma.\"","trick":true},{"id":"c","text":"\"Deeper wounds need a professional.\"","trick":false},{"id":"d","text":"\"So I never need to talk to anyone.\"","trick":true},{"id":"e","text":"\"Tele-MANAS 14416 is there for the heavy stuff.\"","trick":false}],"why":"Expecting the game alone to cure trauma, or to replace ever talking to anyone, overreaches; it signposts, care does the rest.","relearn":"This game offers compassion and signposting, not therapy; deeper wounds deserve real support like Tele-MANAS 14416.","cat":"heal-your-wounds"},
  {"id":"bc-1132","type":"role-play","persona":"Suresh","source":"self-compassion after slip","hook":"You snapped tonight in a way that echoed your own father, and now the old shame is loud.","setup":"Say it kindly to yourself:","yourLine":[{"text":"\"I slipped into an old script tonight; I'll repair with my child, and I'll tend the wound under it.\"","best":true},{"text":"\"See? I'm exactly the father I swore I'd never be. Hopeless.\""}],"relearn":"After an old-script slip, naming it and choosing to repair and tend the wound serves you far better than self-condemnation.","cat":"heal-your-wounds"},
  {"id":"bc-1133","type":"role-play","persona":"any","source":"ask for help","hook":"You've decided to reach out for support about your past, and a counsellor asks why you've come.","setup":"Say it honestly:","yourLine":[{"text":"\"Old pain from my childhood is surfacing in how I react to my kids, and I want to tend it.\"","best":true},{"text":"\"Honestly it's probably nothing, I shouldn't be wasting your time.\""}],"relearn":"Naming plainly why you've come, and that you deserve to be there, lets support actually help; minimising it shuts the door.","cat":"heal-your-wounds"},
  {"id":"bc-1134","type":"role-play","persona":"any","source":"set boundary with relative","hook":"A relative insists the harsh way you were raised was 'good for you' and you should do the same.","setup":"Hold your line, warmly:","yourLine":[{"text":"\"I love a lot about how I was raised, and I'm choosing to do some things differently with mine.\"","best":true},{"text":"\"You're right, I'm being soft; I'll go back to doing it your way.\""}],"relearn":"You can honour your upbringing and still hold the boundary that you'll parent differently, without caving to the old way.","cat":"heal-your-wounds"},
  {"id":"bc-1135","type":"role-play","persona":"any","source":"reassure inner child","hook":"An old memory leaves the child-you feeling, again, that the hurt back then was somehow deserved.","setup":"Speak to that younger self:","yourLine":[{"text":"\"You were a child; none of it was your fault, and you always deserved gentleness.\"","best":true},{"text":"\"You must have done something to bring it on yourself.\""}],"relearn":"Telling your younger self the truth, it wasn't your fault, you deserved gentleness, is how that old self-blame loosens.","cat":"heal-your-wounds"},
  {"id":"bc-1136","type":"role-play","persona":"Vikram","source":"invite partner to heal together","hook":"You and your partner were both raised with harshness; you want to face and change it together.","setup":"Invite them in:","yourLine":[{"text":"\"We were both raised with that. What if we tend our own stuff and choose differently for our kid, together?\"","best":true},{"text":"\"Your childhood was the messed-up one, not mine; this is your problem to fix.\""}],"relearn":"Inviting your partner to tend their wounds and choose differently together does more than blaming one of you for the past.","cat":"heal-your-wounds"},
  {"id":"bc-1137","type":"role-play","persona":"any","source":"answer the should-be-over-it voice","hook":"The voice in your head says you're too old and too grown to still be hurt by any of this.","setup":"Answer it kindly:","yourLine":[{"text":"\"Age doesn't seal a wound; tending it now is exactly how I stop passing it on.\"","best":true},{"text":"\"You're right, grow up; only weak people are still affected by their childhood.\""}],"relearn":"Answering the 'too old to still hurt' voice with truth, age doesn't seal a wound, keeps you tending it instead of burying it.","cat":"heal-your-wounds"},
  {"id":"bc-1138","type":"role-play","persona":"Priya","source":"encourage a scared parent","hook":"Another parent confides they're terrified their unhealed past will make them harm their child.","setup":"Steady and guide them:","yourLine":[{"text":"\"That fear means you're already breaking the pattern. If a moment ever feels unsafe, step away and get help, Tele-MANAS 14416.\"","best":true},{"text":"\"Then you probably will; once it's in you, there's no getting it out.\""}],"relearn":"Affirming that their fear itself shows change, plus pointing to step-away and support, helps a scared parent far more than dread.","cat":"heal-your-wounds"},
  {"id":"bc-1139","type":"role-play","persona":"any","source":"name it without blaming parents","hook":"You want to admit an old hurt to yourself without it becoming a verdict on your parents.","setup":"Say it with compassion:","yourLine":[{"text":"\"That part wounded me, and my parents were likely passing on their own pain; I can heal it without condemning them.\"","best":true},{"text":"\"My parents were monsters and ruined me; there's nothing good to keep.\""}],"relearn":"Naming a wound while holding compassion for parents who passed on their own pain heals more than condemning them wholesale.","cat":"heal-your-wounds"},
  {"id":"bc-1170","type":"strike-rewrite","hook":"\"My father raised me with a strict hand and I turned out fine, so it must be the right way.\"","myth":{"un":"A strict hand raised me and I turned out fine, so it's the right way.","re":"Surviving harsh discipline isn't proof it helped; many carry quiet costs from it and grew despite it, not because of it.","why":"\"I turned out fine\" overlooks the fear and distance it can leave behind."},"relearn":"Turning out okay despite harsh discipline isn't proof it worked; you can choose gentler and firmer ways.","persona":"Suresh","source":"turned out fine","cat":"how-you-were-raised"},
  {"id":"bc-1171","type":"strike-rewrite","hook":"\"My mother never said sorry to us, and that's how a parent keeps respect.\"","myth":{"un":"A parent who apologises to a child loses their respect.","re":"Owning a mistake to your child models respect and actually strengthens your bond and your authority.","why":"Children trust a parent who can say \"I was wrong\" more, not less."},"relearn":"Apologising to your child doesn't cost you authority; it builds trust and shows respect.","persona":"Suresh","source":"apology builds it","cat":"how-you-were-raised"},
  {"id":"bc-1172","type":"strike-rewrite","hook":"\"In our family, children were seen and not heard, and that kept the house calm.\"","myth":{"un":"Children should be seen and not heard.","re":"A child's voice and feelings matter; letting them be heard builds trust and doesn't cost you a calm home.","why":"Silence taught fear, not calm; being heard teaches a child they're safe with you."},"relearn":"\"Seen, not heard\" silences a child; their voice and feelings matter and can be heard with warmth.","persona":"any","source":"voice matters","cat":"how-you-were-raised"},
  {"id":"bc-1173","type":"strike-rewrite","hook":"\"What my parents did worked for generations, so questioning any of it is just modern nonsense.\"","myth":{"un":"It worked for generations, so questioning any of it is modern nonsense.","re":"You can honour your family and still leave the parts that cause harm; keeping the good isn't all-or-nothing.","why":"Long-standing doesn't mean harmless; you get to keep some and set some down."},"relearn":"You can keep the good your family passed on and gently leave the harmful parts; it's not all-or-nothing.","persona":"Suresh","source":"not all or nothing","cat":"how-you-were-raised"},
  {"id":"bc-1174","type":"strike-rewrite","hook":"\"My childhood is the past and has nothing to do with how I parent today.\"","myth":{"un":"My childhood is the past and has nothing to do with how I parent.","re":"Unhealed wounds resurface in your triggers and reactions; tending them helps the cycle stop with you.","why":"The past leaks into the present in heated moments until it's tended."},"relearn":"Your childhood shapes your reactions; tending old wounds helps the harmful cycle stop with you.","persona":"any","source":"heal so it stops","cat":"how-you-were-raised"},
  {"id":"bc-1175","type":"strike-rewrite","hook":"\"I swore I'd parent differently, but the old way always wins in the end, so why try.\"","myth":{"un":"The way I was raised always wins in the end, so why even try.","re":"The inheritance isn't destiny; new patterns are genuinely learnable, and each time you pause you weaken the old one.","why":"Choosing differently gets easier with practice; the reflex isn't fixed."},"relearn":"How you were raised isn't destiny; new patterns are learnable and grow stronger each time you choose them.","persona":"Suresh","source":"not destiny","cat":"how-you-were-raised"},
  {"id":"bc-1176","type":"strike-rewrite","hook":"\"My elders shamed us when we slipped, and that shame is what made us behave.\"","myth":{"un":"Shaming a child is what makes them behave.","re":"Shame damages a child's self-worth and your bond; it discourages them rather than teaching them.","why":"A child who feels small hides and resents, instead of learning."},"relearn":"Shaming doesn't teach good behaviour; it wounds self-worth and your bond. Guide without shame.","persona":"any","source":"shame wounds","cat":"how-you-were-raised"},
  {"id":"bc-1177","type":"strike-rewrite","hook":"\"My parents ruled by fear, and that fear is what they called respect.\"","myth":{"un":"Fear is the same as respect.","re":"Fear teaches a child to hide and resent; real respect grows from trust, not from being afraid of you.","why":"A child who fears you obeys when watched and learns to lie when not."},"relearn":"Fear isn't respect; it breeds hiding and resentment. Respect grows from trust you build over time.","persona":"Suresh","source":"fear isn't respect","cat":"how-you-were-raised"},
  {"id":"bc-1178","type":"reflect","hook":"Lensy: there may be one thing from your own childhood you'd never repeat, and one you'd happily pass on. Both can be true.","prompt":"Sit with that:","options":["Both are true","One to leave","One to keep"],"affirm":"Keeping the good and leaving the harm isn't all-or-nothing; you get to sort your inheritance with care.","relearn":"You can hold both: something from your childhood to pass on, and something to leave behind.","persona":"any","source":"keep one leave one","cat":"how-you-were-raised"},
  {"id":"bc-1179","type":"reflect","hook":"Lensy: the moment you notice \"I'm doing what was done to me,\" you've already stepped outside the pattern. Feel that?","prompt":"What's your take?","options":["I feel it","Noticing is the step","Outside the pattern"],"affirm":"Noticing the old reflex, without blaming yourself, is the exact moment you get to choose differently.","relearn":"Noticing the inherited reflex is itself the first step to choosing a different response.","persona":"Suresh","source":"noticing is the step","cat":"how-you-were-raised"},
  {"id":"bc-1180","type":"reflect","hook":"Lensy: choosing a gentler path than your parents did isn't a verdict on them. You can love them and still do it differently.","prompt":"Does that sit right?","options":["It sits right","Love and change","Not a verdict"],"affirm":"Doing some things differently honours what you learned the hard way; it isn't betrayal of your parents.","relearn":"You can love your parents and still parent differently; that's growth, not betrayal.","persona":"Suresh","source":"not a verdict","cat":"how-you-were-raised"},
  {"id":"bc-1181","type":"reflect","hook":"Lensy: imagine your child, grown, describing their childhood. What one word would you most want them to use?","prompt":"What word comes up?","options":["Safe","Loved","Heard"],"affirm":"Letting that word guide your choices today is how you decide, gently, what to keep and what to leave.","relearn":"Picturing the childhood you want your child to remember helps you choose your patterns on purpose.","persona":"any","source":"one word","cat":"how-you-were-raised"},
  {"id":"bc-1182","type":"reflect","hook":"Lensy: the patterns you choose on purpose can stop with you, so your child never has to unlearn them. That's the gift.","prompt":"How does that land?","options":["It lands","Stops with me","A gift forward"],"affirm":"Deciding what harm ends with you spares your child the work of undoing it later; it's a quiet, lasting gift.","relearn":"What you choose to stop with you, your child never has to unlearn; that decision is a gift forward.","persona":"any","source":"stops with me","cat":"how-you-were-raised"},
  {"id":"bc-1183","type":"reflect","hook":"Lensy: most parents who were raised harshly aren't cruel; they're carrying what they were handed, often unaware. Compassion fits here.","prompt":"What's your take?","options":["Compassion fits","They carried it too","Without excusing harm"],"affirm":"Holding compassion for those who raised you, without excusing the harm, frees you to choose your own way.","relearn":"Most who parented harshly were carrying what they were handed; compassion for that frees you to change.","persona":"Suresh","source":"compassion for them","cat":"how-you-were-raised"},
  {"id":"bc-1184","type":"reflect","hook":"Lensy: it's normal to feel grief realising some of what you needed as a child, you didn't get. That grief is allowed.","prompt":"Let it be here:","options":["It's allowed","I feel the grief","Naming it helps"],"affirm":"Letting the grief be felt, with compassion, turns it into fuel for change instead of something that leaks out.","relearn":"Grief over what you didn't get as a child is allowed; felt with care, it can fuel how you choose to parent.","persona":"Suresh","source":"grief allowed","cat":"how-you-were-raised"},
  {"id":"bc-1185","type":"reflect","hook":"Lensy: you don't have to throw out everything from your upbringing. Which warm thing, a food, a song, a ritual, do you keep?","prompt":"What comes to mind?","options":["A ritual","A song or food","Time together"],"affirm":"Keeping the warmth your family gave you is part of breaking the cycle; it's never all-or-nothing.","relearn":"Breaking the cycle means keeping the warmth too, the rituals and love worth passing on, not just leaving harm.","persona":"any","source":"keep the warmth","cat":"how-you-were-raised"},
  {"id":"bc-1186","type":"reflect","hook":"Lensy: when your child tests you at the end of a long day, you might hear an old voice rise in your mouth. You can pause it.","prompt":"How does that feel?","options":["Familiar","I can pause it","The voice isn't me"],"affirm":"Hearing the old voice rise doesn't mean you'll repeat it; the pause between feeling and acting is yours.","relearn":"When the inherited voice rises under stress, the pause before you act is yours; the old reflex isn't you.","persona":"Suresh","source":"old voice rises","cat":"how-you-were-raised"},
  {"id":"bc-1187","type":"reflect","hook":"Lensy: you may be the first in your line to even ask these questions. That alone is the cycle starting to bend.","prompt":"What do you notice?","options":["I'm the first","The cycle bends","Asking is a start"],"affirm":"Being the one who stops to question the inherited way is, by itself, the start of choosing a new pattern.","relearn":"Being the first in your family to question the old way is itself the cycle beginning to change.","persona":"any","source":"first to ask","cat":"how-you-were-raised"},
  {"id":"bc-1188","type":"reflect","hook":"Lensy: the goal isn't a perfect childhood for your kid, just one a little gentler than the one you were given. Small is enough.","prompt":"Does that ease it?","options":["It eases it","A little gentler","Small is enough"],"affirm":"Aiming for a bit gentler than you had, not perfect, is realistic and still breaks the cycle for your child.","relearn":"You don't need a perfect childhood for your child, just one a little gentler than yours; small shifts count.","persona":"any","source":"a little gentler","cat":"how-you-were-raised"},
  {"id":"bc-1189","type":"sort","hook":"Sort each thing you inherited: worth keeping, or worth gently leaving behind?","items":[{"id":"a","text":"Bedtime stories every night"},{"id":"b","text":"A slap when you talked back"},{"id":"c","text":"Eating together as a family"},{"id":"d","text":"Silence instead of \"I love you\""},{"id":"e","text":"Respecting hard work"},{"id":"f","text":"Comparing you to other kids"}],"bins":[{"id":"keep","label":"Worth keeping","valence":"pos"},{"id":"leave","label":"Worth leaving","valence":"neg"}],"key":{"a":"keep","b":"leave","c":"keep","d":"leave","e":"keep","f":"leave"},"relearn":"Keep the stories, shared meals and good values; leave the slaps, the silence and the comparing.","persona":"any","source":"keep vs leave","cat":"how-you-were-raised"},
  {"id":"bc-1190","type":"sort","hook":"Sort each belief about how you were raised: a compassionate truth, or a shaming myth?","items":[{"id":"a","text":"\"Most harsh parents were raised that way\""},{"id":"b","text":"\"If I slip once, I've ruined my child\""},{"id":"c","text":"\"I can choose differently from here\""},{"id":"d","text":"\"I'm doomed to repeat my parents\""},{"id":"e","text":"\"Noticing the pattern is real progress\""},{"id":"f","text":"\"A trying parent who errs is a monster\""}],"bins":[{"id":"truth","label":"Compassionate truth","valence":"pos"},{"id":"myth","label":"Shaming myth","valence":"neg"}],"key":{"a":"truth","b":"myth","c":"truth","d":"myth","e":"truth","f":"myth"},"relearn":"Compassion is true: harsh parents were raised that way, you can choose now. Doom and monster talk is shaming.","persona":"any","source":"compassion vs shame","cat":"how-you-were-raised"},
  {"id":"bc-1191","type":"sort","hook":"Sort each inherited message: pass it on to your child, or rewrite it?","items":[{"id":"a","text":"\"Your feelings matter to me\""},{"id":"b","text":"\"Big boys don't cry\""},{"id":"c","text":"\"Mistakes are how you learn\""},{"id":"d","text":"\"You'll only learn through fear\""},{"id":"e","text":"\"You can tell me anything\""},{"id":"f","text":"\"Children should be seen, not heard\""}],"bins":[{"id":"pass","label":"Pass it on","valence":"pos"},{"id":"rewrite","label":"Rewrite it","valence":"neg"}],"key":{"a":"pass","b":"rewrite","c":"pass","d":"rewrite","e":"pass","f":"rewrite"},"relearn":"Pass on \"your feelings matter\" and \"you can tell me anything\"; rewrite \"don't cry,\" fear and \"seen, not heard.\"","persona":"any","source":"pass or rewrite","cat":"how-you-were-raised"},
  {"id":"bc-1192","type":"sort","hook":"Suresh notices old reflexes at day's end. Sort each one: catch it, or it's safe to keep?","items":[{"id":"a","text":"Reaching to hit when angry"},{"id":"b","text":"Hugging him goodnight"},{"id":"c","text":"Mocking him when he cries"},{"id":"d","text":"Asking how his day went"},{"id":"e","text":"Threatening to scare him quiet"},{"id":"f","text":"Praising effort, not just marks"}],"bins":[{"id":"catch","label":"Catch this reflex","valence":"uhoh"},{"id":"safe","label":"Safe to keep","valence":"pos"}],"key":{"a":"catch","b":"safe","c":"catch","d":"safe","e":"catch","f":"safe"},"relearn":"Catch the hitting, mocking and threats as they rise; the hugs, the asking and praising effort are safe to keep.","persona":"Suresh","source":"catch the reflex","cat":"how-you-were-raised"},
  {"id":"bc-1193","type":"sort","hook":"Sort each move a parent makes with their own past: tends the wound, or buries it?","items":[{"id":"a","text":"Naming what hurt you as a child"},{"id":"b","text":"\"I never think about my childhood\""},{"id":"c","text":"Talking to a counsellor about it"},{"id":"d","text":"Snapping, then blaming the kids"},{"id":"e","text":"Noticing what triggers the old anger"},{"id":"f","text":"Pushing the old pain down, again"}],"bins":[{"id":"tend","label":"Tends the wound","valence":"pos"},{"id":"bury","label":"Buries it","valence":"neg"}],"key":{"a":"tend","b":"bury","c":"tend","d":"bury","e":"tend","f":"bury"},"relearn":"Naming the hurt, getting support and knowing your triggers tends the wound; ignoring and pushing it down buries it.","persona":"any","source":"tend or bury","cat":"how-you-were-raised"},
  {"id":"bc-1194","type":"sort","hook":"A relative pushes back on your gentler ways. Sort each reply: holds your path, or caves to the old way?","items":[{"id":"a","text":"\"I'm choosing some things differently\""},{"id":"b","text":"\"You're right, I'll be harder\""},{"id":"c","text":"\"I love what you gave me, and I'll add to it\""},{"id":"d","text":"\"Maybe fear did keep me in line\""},{"id":"e","text":"\"My child can be heard and still respectful\""},{"id":"f","text":"\"I suppose a slap never hurt anyone\""}],"bins":[{"id":"holds","label":"Holds your path","valence":"pos"},{"id":"caves","label":"Caves to old way","valence":"neg"}],"key":{"a":"holds","b":"caves","c":"holds","d":"caves","e":"holds","f":"caves"},"relearn":"Holding your path means \"I'm choosing differently\" and \"heard and respectful\"; caving repeats fear and slaps.","persona":"Suresh","source":"hold or cave","cat":"how-you-were-raised"},
  {"id":"bc-1195","type":"sort","hook":"Sort each childhood memory: a warm gift to pass on, or a hurt to leave behind?","items":[{"id":"a","text":"Grandmother's lullabies"},{"id":"b","text":"Being beaten for poor marks"},{"id":"c","text":"Festival mornings together"},{"id":"d","text":"Being called \"useless\" when upset"},{"id":"e","text":"A parent who showed up for you"},{"id":"f","text":"Never being allowed to say no"}],"bins":[{"id":"gift","label":"Warm gift to pass on","valence":"pos"},{"id":"hurt","label":"Hurt to leave","valence":"neg"}],"key":{"a":"gift","b":"hurt","c":"gift","d":"hurt","e":"gift","f":"hurt"},"relearn":"Pass on the lullabies, festivals and showing up; leave the beatings, the name-calling and never allowing a no.","persona":"any","source":"gift vs hurt","cat":"how-you-were-raised"},
  {"id":"bc-1196","type":"sort","hook":"Sort each thought about questioning your upbringing: frees you to choose, or keeps you stuck?","items":[{"id":"a","text":"\"I can keep the good and leave the rest\""},{"id":"b","text":"\"Questioning it betrays my parents\""},{"id":"c","text":"\"Loving them and changing both fit\""},{"id":"d","text":"\"This is just who I am\""},{"id":"e","text":"\"New ways are learnable\""},{"id":"f","text":"\"It worked for them, can't touch it\""}],"bins":[{"id":"frees","label":"Frees you","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"frees","b":"stuck","c":"frees","d":"stuck","e":"frees","f":"stuck"},"relearn":"Keeping the good, loving and changing, and learnable new ways free you; betrayal-guilt and \"can't touch it\" keep you stuck.","persona":"any","source":"free or stuck","cat":"how-you-were-raised"},
  {"id":"bc-1197","type":"branch","hook":"Your son ignores you a third time, and your hand rises the way your father's did.","options":[{"text":"Lower your hand, step back, and breathe first","consequence":"You break the old reflex and stay the parent you want to be.","outcome":"break","best":true},{"text":"Let the hand fall, as you were taught","consequence":"The inherited pattern passes straight to your son."}],"debrief":"When the reflex rises, lowering your hand and breathing first interrupts the inheritance.","relearn":"When your hand rises like your parent's did, lower it and breathe; that pause stops the pattern.","persona":"Suresh","source":"hand rises","cat":"how-you-were-raised"},
  {"id":"bc-1198","type":"branch","hook":"Your mother says you're spoiling your daughter by letting her cry on your shoulder, not \"toughening up.\"","options":[{"text":"Thank her, but keep choosing comfort","consequence":"You hold your gentler path warmly, without a fight.","outcome":"hold","best":true},{"text":"Push the child away to win approval","consequence":"You repeat the old coldness, and your child learns to hide tears."}],"debrief":"You can stay warm with your elder and keep comforting your child; her trust beats their approval.","relearn":"When an elder calls comfort \"spoiling,\" honour them but keep comforting your child; their trust matters most.","persona":"any","source":"spoiling","cat":"how-you-were-raised"},
  {"id":"bc-1199","type":"branch","hook":"You realise you rule your home by fear, as you were ruled; the kids go quiet when you enter.","options":[{"text":"Notice it without self-attack, and build trust instead","consequence":"Awareness turns into a slow, real change toward trust.","outcome":"change","best":true},{"text":"Decide you're a lost cause and give up","consequence":"Giving up locks the fear pattern in for another generation."}],"debrief":"Noticing the fear pattern, without beating yourself up, is where change begins, not ends.","relearn":"Noticing you rule by fear isn't failure; it's the start of building respect through trust instead.","persona":"Suresh","source":"rule by fear","cat":"how-you-were-raised"},
  {"id":"bc-1200","type":"branch","hook":"At a festival, relatives laugh that you ask your son's opinion; children shouldn't have a say.","options":[{"text":"Smile and keep asking him; his voice matters","consequence":"Your son learns his voice is safe with you, whoever's watching.","outcome":"voice","best":true},{"text":"Hush him to fit in with the relatives","consequence":"He learns his voice only matters until others are around."}],"debrief":"Letting your child be heard even when relatives mock it teaches him his feelings matter everywhere.","relearn":"Keep letting your child have a say even when relatives mock it; \"seen, not heard\" is the pattern to leave.","persona":"any","source":"children should have a say","cat":"how-you-were-raised"},
  {"id":"bc-1201","type":"branch","hook":"You catch yourself comparing your daughter to her cousin, as you were compared, and her face falls.","options":[{"text":"Stop, and tell her you love who she is","consequence":"You cut off the comparing before it lands, and she feels seen.","outcome":"seen","best":true},{"text":"Finish the comparison to \"motivate\" her","consequence":"It wounds her worth, the way it once wounded yours."}],"debrief":"Comparing to motivate is an inherited reflex that wounds; stopping and naming your love repairs it.","relearn":"When you compare your child as you were compared, stop and affirm who they are; comparison wounds worth.","persona":"any","source":"comparing","cat":"how-you-were-raised"},
  {"id":"bc-1202","type":"branch","hook":"Your old anger surges and you hear your father's harsh words forming in your mouth at your child.","options":[{"text":"If it's safe, step into another room first","consequence":"You break the surge safely and keep the harsh words unsaid.","outcome":"step away","best":true},{"text":"Let the words out, they're already there","consequence":"The harsh words land on your child, as they once did on you."}],"debrief":"When old words form under anger, stepping away if safe keeps the surge from harming your child.","relearn":"When your parent's harsh words rise in your mouth, step away if safe; the gap before you act is yours.","persona":"Suresh","source":"harsh words form","cat":"how-you-were-raised"},
  {"id":"bc-1203","type":"branch","hook":"Your partner says \"we were both raised with the belt, and look at us.\" Your child is next door.","options":[{"text":"\"We were, and let's choose differently for our kid\"","consequence":"You two become a team choosing a new pattern together.","outcome":"team","best":true},{"text":"Agree, and bring back the belt","consequence":"You both pass the harm forward instead of stopping it."}],"debrief":"Naming the shared inheritance, then choosing differently together, lets co-parents break the cycle as a team.","relearn":"When a co-parent defends the old harsh way, invite them to choose differently with you, for your child.","persona":"any","source":"both raised with the belt","cat":"how-you-were-raised"},
  {"id":"bc-1204","type":"branch","hook":"A wave of guilt hits as you realise how much of your harsh upbringing you've been repeating.","options":[{"text":"Let the guilt move you to act on one small thing","consequence":"Guilt becomes motion, and one pattern starts to shift today.","outcome":"act","best":true},{"text":"Drown in guilt and decide you've failed","consequence":"Spiralling in guilt freezes you, and nothing changes."}],"debrief":"Guilt that turns into one small change helps; guilt that spirals into \"I've failed\" freezes you.","relearn":"Let guilt about repeating the old way move you to one small change, not a spiral into \"I've failed.\"","persona":"Suresh","source":"guilt to action","cat":"how-you-were-raised"},
  {"id":"bc-1205","type":"match","hook":"Match each harsh inherited message to the truer one to raise your child on.","pairs":[{"left":"\"Children should be seen, not heard\"","right":"Your voice and feelings matter to me"},{"left":"\"Fear keeps kids in line\"","right":"Respect grows from trust, not fear"},{"left":"\"Big boys don't cry\"","right":"All your feelings are welcome here"},{"left":"\"A slap teaches them\"","right":"Calm limits teach far better than pain"},{"left":"\"Affection spoils a child\"","right":"Warmth makes a child stronger, not weaker"}],"relearn":"Each harsh message has a truer one: voice matters, respect from trust, feelings welcome, warmth strengthens.","persona":"any","source":"truer messages","cat":"how-you-were-raised"},
  {"id":"bc-1206","type":"match","hook":"Match each part of your inheritance to whether you'd keep it or leave it, and why.","pairs":[{"left":"Family closeness","right":"Keep: it nourished you"},{"left":"Hitting when angry","right":"Leave: it harms and doesn't work"},{"left":"Bedtime stories","right":"Keep: warmth your child deserves too"},{"left":"Shaming when you erred","right":"Leave: it wounds self-worth"},{"left":"Valuing honesty","right":"Keep: a value worth passing on"}],"relearn":"Keep the closeness, stories and honesty that nourished you; leave the hitting and shaming that harm.","persona":"any","source":"keep-leave reasons","cat":"how-you-were-raised"},
  {"id":"bc-1207","type":"match","hook":"Match each old reflex Suresh notices to the gentler response he's learning instead.","pairs":[{"left":"Raising a hand when angry","right":"Step back and breathe first"},{"left":"Ruling by fear","right":"Build trust over time"},{"left":"Going silent and cold","right":"Say the warm words out loud"},{"left":"Mocking tears","right":"Name the feeling with him"},{"left":"Comparing to cousins","right":"Praise his own effort"}],"relearn":"Each old reflex has a gentler swap: breathe instead of hit, trust over fear, warmth over silence, naming over mocking.","persona":"Suresh","source":"reflex to response","cat":"how-you-were-raised"},
  {"id":"bc-1208","type":"match","hook":"Match each step of stopping the cycle to what it does.","pairs":[{"left":"Noticing the old pattern","right":"Gives you the power to choose"},{"left":"Holding compassion for your parents","right":"Frees you from blame to act"},{"left":"Keeping the good, leaving the harm","right":"Sorts your inheritance with care"},{"left":"Tending your own old wounds","right":"Stops them leaking onto your child"},{"left":"Choosing one new pattern today","right":"Bends the cycle for the next generation"}],"relearn":"Noticing, compassion, sorting keep-from-leave, tending wounds and one new choice are the steps that bend the cycle.","persona":"any","source":"steps that stop it","cat":"how-you-were-raised"},
  {"id":"bc-1209","type":"match","hook":"Match each belief about questioning your upbringing to whether it's a freeing truth or a stuck myth.","pairs":[{"left":"\"I can love them and still change\"","right":"Freeing truth"},{"left":"\"Questioning betrays my parents\"","right":"Stuck myth"},{"left":"\"New ways are learnable\"","right":"A freeing truth, slowly"},{"left":"\"This is just who I am\"","right":"Stuck myth, and untrue"},{"left":"\"I keep the good and leave the harm\"","right":"Both at once, freely"}],"relearn":"Loving and changing, and learnable new ways, are freeing truths; betrayal-guilt and \"just who I am\" keep you stuck.","persona":"any","source":"free truth or stuck myth","cat":"how-you-were-raised"},
  {"id":"bc-1210","type":"match","hook":"Match each warm thing from a childhood to the harsh thing it can replace.","pairs":[{"left":"A goodnight hug","right":"Replaces cold, silent nights"},{"left":"Asking about their day","right":"Replaces being ignored"},{"left":"Praising effort","right":"Replaces constant comparing"},{"left":"Letting them say no","right":"Replaces forced obedience"},{"left":"Owning your mistakes","right":"Replaces never apologising"}],"relearn":"Hugs replace cold nights, asking replaces ignoring, praise replaces comparing, an allowed-no replaces force, apology replaces silence.","persona":"any","source":"warm replaces harsh","cat":"how-you-were-raised"},
  {"id":"bc-1211","type":"match","hook":"Match each thing a parent might say to whether it shames the parent or holds compassion.","pairs":[{"left":"\"You're a bad parent for slipping\"","right":"Shames the parent"},{"left":"\"You were raised that way; you can change\"","right":"Holds compassion"},{"left":"\"You've already ruined your child\"","right":"Shames, and isn't true"},{"left":"\"Your worry means you're trying\"","right":"Holds compassion, warmly"},{"left":"\"One hard day doesn't define you\"","right":"Holds compassion, gently"}],"relearn":"\"Bad parent\" and \"ruined\" shame; \"you can change,\" \"you're trying\" and \"one hard day\" hold compassion.","persona":"Priya","source":"shame or compassion","cat":"how-you-were-raised"},
  {"id":"bc-1212","type":"match","hook":"Match each inherited fear-script to the trust-script that replaces it.","pairs":[{"left":"\"Wait till your father gets home\"","right":"\"Let's sort this out together now\""},{"left":"\"Because I said so\"","right":"\"Here's why this matters\""},{"left":"\"Stop crying or I'll give you a reason\"","right":"\"It's okay to cry; I'm here\""},{"left":"\"You'll shame this whole family\"","right":"\"You can always come to me\""},{"left":"\"Children don't argue with elders\"","right":"\"You can disagree respectfully\""}],"relearn":"Fear-scripts like \"wait till your father\" and \"because I said so\" have trust-scripts that keep the child close.","persona":"any","source":"fear to trust scripts","cat":"how-you-were-raised"},
  {"id":"bc-1213","type":"spot","hook":"Spot the two lines that just repeat the harsh inheritance unquestioned.","scene":[{"id":"a","text":"\"I'll keep the warmth and leave the hitting\"","trick":false},{"id":"b","text":"\"A slap never hurt me, so it's fine for him\"","trick":true},{"id":"c","text":"\"I can choose my own patterns now\"","trick":false},{"id":"d","text":"\"This is just how we've always done it\"","trick":true},{"id":"e","text":"\"I love my childhood; I'll do some things differently\"","trick":false}],"why":"\"A slap never hurt me\" and \"how we've always done it\" repeat the harm; the rest sort it with care.","relearn":"Repeating the old way unquestioned passes on harm; keep the good and choose your own patterns instead.","persona":"Suresh","source":"repeat unquestioned","cat":"how-you-were-raised"},
  {"id":"bc-1214","type":"spot","hook":"Spot the two beliefs that keep a parent stuck in the old pattern.","scene":[{"id":"a","text":"\"New ways are learnable, slowly\"","trick":false},{"id":"b","text":"\"I'm doomed to repeat my parents\"","trick":true},{"id":"c","text":"\"Noticing the pattern is the first step\"","trick":false},{"id":"d","text":"\"This is just who I am, I can't change\"","trick":true},{"id":"e","text":"\"I choose what stops with me\"","trick":false}],"why":"\"I'm doomed\" and \"I can't change\" keep the pattern running; the inheritance isn't destiny and new ways are learnable.","relearn":"\"Doomed\" and \"can't change\" keep you stuck; noticing the pattern and choosing new ways frees you.","persona":"any","source":"stuck beliefs","cat":"how-you-were-raised"},
  {"id":"bc-1215","type":"spot","hook":"Spot the two replies that cave to the old harsh way under family pressure.","scene":[{"id":"a","text":"\"I'm choosing some things differently, kindly\"","trick":false},{"id":"b","text":"\"You're right, maybe I should be harder on him\"","trick":true},{"id":"c","text":"\"My child can be heard and still respectful\"","trick":false},{"id":"d","text":"\"I suppose a little fear did keep me in line\"","trick":true},{"id":"e","text":"\"I'll keep what I loved and leave the rest\"","trick":false}],"why":"\"I should be harder\" and \"fear kept me in line\" cave to the old way; the rest hold the gentler path.","relearn":"Under pressure, caving repeats fear and harshness; you can honour elders and hold your gentler path.","persona":"Suresh","source":"caving replies","cat":"how-you-were-raised"},
  {"id":"bc-1216","type":"spot","hook":"Spot the two messages that pass shame, not love, to a child.","scene":[{"id":"a","text":"\"Your feelings matter to me\"","trick":false},{"id":"b","text":"\"You're the shame of this family\"","trick":true},{"id":"c","text":"\"You can always come to me\"","trick":false},{"id":"d","text":"\"Why can't you be like your cousin?\"","trick":true},{"id":"e","text":"\"Mistakes are how you learn\"","trick":false}],"why":"\"Shame of this family\" and \"be like your cousin\" pass shame and comparison; the others build a child's worth and trust.","relearn":"Shaming and comparing wound a child's worth; messages of worth and welcome are what's worth passing on.","persona":"any","source":"shame messages","cat":"how-you-were-raised"},
  {"id":"bc-1217","type":"spot","hook":"Spot the two things a parent does that bury their own old wounds instead of tending them.","scene":[{"id":"a","text":"Naming what hurt them as a child","trick":false},{"id":"b","text":"\"I never think about my childhood\"","trick":true},{"id":"c","text":"Noticing what triggers the old anger","trick":false},{"id":"d","text":"Snapping, then blaming the kids for it","trick":true},{"id":"e","text":"Reaching out to a counsellor for support","trick":false}],"why":"\"I never think about it\" and blaming the kids bury the wound; naming, noticing triggers and getting support tend it.","relearn":"Burying old pain leaks it onto your child; naming it, knowing your triggers and seeking support tends it.","persona":"any","source":"bury the wound","cat":"how-you-were-raised"},
  {"id":"bc-1218","type":"spot","hook":"Spot the two reactions that let the old anger run straight onto the child.","scene":[{"id":"a","text":"Stepping into another room to cool down","trick":false},{"id":"b","text":"Letting the harsh words out because they're there","trick":true},{"id":"c","text":"Taking a few slow breaths first","trick":false},{"id":"d","text":"Hitting now and feeling sorry later","trick":true},{"id":"e","text":"Naming the anger out loud, then pausing","trick":false}],"why":"Letting the words out and hitting land the surge on the child; stepping away, breathing and naming keep it safe.","relearn":"When old anger surges, the gap between feeling and acting is yours; step away, breathe, name it before you act.","persona":"Suresh","source":"anger runs onto child","cat":"how-you-were-raised"},
  {"id":"bc-1219","type":"spot","hook":"Spot the two thoughts that treat questioning your upbringing as betrayal.","scene":[{"id":"a","text":"\"I can love them and still change\"","trick":false},{"id":"b","text":"\"Doing it differently insults my parents\"","trick":true},{"id":"c","text":"\"Keeping the good isn't all-or-nothing\"","trick":false},{"id":"d","text":"\"Changing means they did everything wrong\"","trick":true},{"id":"e","text":"\"Growth honours what I learned the hard way\"","trick":false}],"why":"\"It insults them\" and \"they did everything wrong\" frame change as betrayal; choosing differently is growth.","relearn":"Questioning a pattern isn't betrayal; you can love your parents, keep the good and still choose differently.","persona":"Suresh","source":"betrayal thoughts","cat":"how-you-were-raised"},
  {"id":"bc-1220","type":"spot","hook":"Spot the two myths hiding among truths about how you were raised.","scene":[{"id":"a","text":"Awareness is the first step to change","trick":false},{"id":"b","text":"Hitting is just normal, harmless discipline","trick":true},{"id":"c","text":"You can keep the good and leave the harm","trick":false},{"id":"d","text":"Fear from a parent is the same as respect","trick":true},{"id":"e","text":"Most harsh parents were raised that way","trick":false}],"why":"\"Hitting is harmless\" and \"fear is respect\" are the myths; awareness, keep-and-leave and compassion are the truths.","relearn":"Hitting harms and fear isn't respect; awareness, sorting your inheritance and compassion are the real truths.","persona":"any","source":"myths among truths","cat":"how-you-were-raised"},
  {"id":"bc-1221","type":"role-play","hook":"Your father, watching you parent, says \"you're too soft; I raised you with a firm hand and you turned out fine.\" You answer warmly.","setup":"Answer your father warmly:","yourLine":[{"text":"\"You did your best with what you knew, Baba. I'm choosing some things differently for him, with love.\"","best":true},{"text":"\"You're right, I'll be firmer with him from now on.\""}],"relearn":"Honouring your parent while owning your own gentler choice holds your path without attacking how they raised you.","persona":"Suresh","source":"too soft","cat":"how-you-were-raised"},
  {"id":"bc-1222","type":"role-play","hook":"Your child asks, \"Why don't you hit me when I'm bad, like Dadi says her papa did?\" You answer simply and honestly.","setup":"Answer your child:","yourLine":[{"text":"\"Because hurting you isn't how I want to teach you. I'd rather help you understand.\"","best":true},{"text":"\"Maybe I should, like they did to me.\""}],"relearn":"Telling your child plainly that you choose teaching over hurting models the new pattern out loud.","persona":"any","source":"why don't you hit me","cat":"how-you-were-raised"},
  {"id":"bc-1223","type":"role-play","hook":"A relative scolds you for letting your son cry openly: \"that's how you make him weak.\" You hold your ground kindly.","setup":"Hold your ground kindly:","yourLine":[{"text":"\"Letting him feel things will make him stronger, not weaker. I'm okay with his tears.\"","best":true},{"text":"\"You're right, I'll tell him to stop crying.\""}],"relearn":"Welcoming a child's tears, even when relatives call it weakness, leaves behind the \"don't cry\" script.","persona":"any","source":"make him weak","cat":"how-you-were-raised"},
  {"id":"bc-1224","type":"role-play","hook":"Your partner says \"we were both raised with the belt and we're fine, why change?\" You invite them to choose differently together.","setup":"Invite your partner in:","yourLine":[{"text":"\"We were, and I'm grateful we made it. Let's choose a gentler way for our child, together.\"","best":true},{"text":"\"You're right, let's just raise her the way we were raised.\""}],"relearn":"Naming the shared inheritance, then inviting a gentler choice together, lets co-parents break the cycle as a team.","persona":"any","source":"both raised with the belt","cat":"how-you-were-raised"},
  {"id":"bc-1225","type":"role-play","hook":"You just heard your father's harsh words come out of your mouth at your daughter, and her face fell. You repair, owning it.","setup":"Repair with your daughter:","yourLine":[{"text":"\"I'm sorry I spoke to you like that. It wasn't okay, and it wasn't your fault.\"","best":true},{"text":"\"I only said it because you made me angry.\""}],"relearn":"A clean repair owns what you said and tells your child it wasn't their fault, breaking the no-apology pattern.","persona":"Suresh","source":"harsh words slipped","cat":"how-you-were-raised"},
  {"id":"bc-1226","type":"role-play","hook":"Another struggling parent confides, \"I'm terrified I'll raise my kid the harsh way I was raised.\" You reassure them.","setup":"Reassure them warmly:","yourLine":[{"text":"\"The fact that you're worried means you're already breaking the pattern. You can do it differently.\"","best":true},{"text":"\"You probably will; it's in the blood, nothing to be done.\""}],"relearn":"Reminding a frightened parent that their worry itself is the cycle bending offers compassion, not condemnation.","persona":"Priya","source":"terrified I'll repeat it","cat":"how-you-were-raised"},
  {"id":"bc-1227","type":"role-play","hook":"At a family lunch, an uncle laughs that you ask your son's opinion: \"children don't get a say in our house.\" You answer evenly.","setup":"Answer your uncle evenly:","yourLine":[{"text":"\"In ours, his voice matters. He can be heard and still respect his elders.\"","best":true},{"text":"\"You're right, he should just stay quiet around adults.\""}],"relearn":"Standing by your child's voice, calmly, even when elders mock it leaves \"seen, not heard\" behind for good.","persona":"any","source":"children don't get a say","cat":"how-you-were-raised"},
  {"id":"bc-1260","cat":"the-repair","type":"strike-rewrite","persona":"Divya","source":"buying gift not repair","relearn":"A toy or treat can't replace the words; a real repair owns what happened and reconnects.","hook":"\"I'll just buy him a treat and we'll be fine; I don't need to say anything.\"","myth":{"un":"I'll just buy him a treat and we'll be fine; I don't need to say anything.","re":"A gift can soften the day, but it isn't a repair; the child needs you to name it and reconnect, not to be bought off.","why":"Repair is words and warmth, not a bribe."}},
  {"id":"bc-1261","cat":"the-repair","type":"strike-rewrite","persona":"Suresh","source":"silent treatment not repair","relearn":"Going quiet for days isn't keeping the peace; it leaves the rupture open. Reconnecting once calm is the repair.","hook":"\"If I just go quiet for a few days, it'll blow over on its own.\"","myth":{"un":"If I just go quiet for a few days, it'll blow over on its own.","re":"Silence doesn't heal a rupture; it leaves the child anxious and guessing. Going back and reconnecting once you're calm is what repairs it.","why":"Withdrawal leaves the hurt open."}},
  {"id":"bc-1262","cat":"the-repair","type":"strike-rewrite","persona":"any","source":"repair shows weakness myth","relearn":"Owning a slip in front of your child is strength, not weakness; it teaches them that mistakes can be put right.","hook":"\"Admitting I was wrong in front of my child makes me look weak.\"","myth":{"un":"Admitting I was wrong in front of my child makes me look weak.","re":"Owning a mistake to your child is a sign of strength; it shows them how to be accountable and that being wrong can be put right.","why":"Accountability models strength, not weakness."}},
  {"id":"bc-1263","cat":"the-repair","type":"strike-rewrite","persona":"Divya","source":"baby too young for repair","relearn":"Even a baby reads your tone and touch; a soft voice and a cuddle after a hard moment are a real repair.","hook":"\"My baby is too small to understand, so there's no point repairing after I snap.\"","myth":{"un":"My baby is too small to understand, so there's no point repairing after I snap.","re":"A baby can't follow words, but they feel your tone and touch; a calm voice and a gentle cuddle after a hard moment soothe and reconnect them.","why":"Tone and touch repair before words can."}},
  {"id":"bc-1264","cat":"the-repair","type":"strike-rewrite","persona":"any","source":"sorry but undoes it","relearn":"A 'sorry, but...' that tacks on blame undoes the apology; a clean sorry owns your part and stops there.","hook":"\"As long as I say sorry, adding 'but you provoked me' is fine.\"","myth":{"un":"As long as I say sorry, adding 'but you provoked me' is fine.","re":"A 'sorry, but you provoked me' cancels the apology and hands the child the blame; a clean sorry owns your reaction and stops there.","why":"'Sorry, but' transfers the fault back."}},
  {"id":"bc-1265","cat":"the-repair","type":"strike-rewrite","persona":"Suresh","source":"father never apologised","relearn":"Your parents may never have apologised to you; choosing to repair with your own child is how the cycle changes.","hook":"\"My father never once said sorry to me, and I turned out fine; why should I?\"","myth":{"un":"My father never once said sorry to me, and I turned out fine; why should I?","re":"That your father never repaired is part of the inheritance you can set down; choosing to own a slip with your own child is exactly how the pattern changes.","why":"Repairing is how you break the cycle."}},
  {"id":"bc-1266","cat":"the-repair","type":"strike-rewrite","persona":"Vikram","source":"explaining is not repairing","relearn":"Explaining why you lost your temper isn't the same as repairing; the child needs ownership, not your reasons.","hook":"\"If I explain that I was stressed about work, that counts as repairing.\"","myth":{"un":"If I explain that I was stressed about work, that counts as repairing.","re":"Naming you were stressed can help, but an explanation isn't a repair until you also own the snap and tell the child it wasn't their fault.","why":"Reasons aren't ownership."}},
  {"id":"bc-1267","cat":"the-repair","type":"strike-rewrite","persona":"Divya","source":"guilt is the repair myth","relearn":"Drowning in guilt doesn't help your child; turning that feeling into a calm, simple repair does.","hook":"\"Feeling terribly guilty for hours afterward shows I'm making up for it.\"","myth":{"un":"Feeling terribly guilty for hours afterward shows I'm making up for it.","re":"Guilt that spirals helps no one and can pull you further from your child; what makes up for a slip is a calm, simple repair, then letting it go.","why":"Repair, not endless guilt, mends it."}},
  {"id":"bc-1268","cat":"the-repair","type":"branch","persona":"Suresh","source":"repair in front of relatives","relearn":"You can repair quietly even with relatives nearby; don't let pride cancel it.","hook":"You snapped at your son at a family gathering and relatives are watching.","options":[{"text":"Quietly kneel, own it softly, and reconnect","consequence":"He feels seen; the rupture mends without a scene.","outcome":"repair","best":true},{"text":"Skip it, deciding it would look weak","consequence":"Pride cancels the repair; he carries it alone."}],"debrief":"A repair can be quiet and private even in a full room; your child needs the ownership, not an audience."},
  {"id":"bc-1269","cat":"the-repair","type":"branch","persona":"Divya","source":"repair timing mid-meltdown","relearn":"Repair lands once you're both calm; wait for the lull, then reconnect.","hook":"You've just snapped and your toddler is mid-meltdown, screaming.","options":[{"text":"Stay near, keep calm, repair once the storm passes","consequence":"As she settles, your warmth reaches her.","outcome":"repair","best":true},{"text":"Demand she calm down now so you can apologise","consequence":"An apology mid-meltdown adds pressure, rarely lands."}],"debrief":"Repair needs a calm moment to land; stay present, let the meltdown pass, then go back and reconnect."},
  {"id":"bc-1270","cat":"the-repair","type":"branch","persona":"any","source":"child made to comfort parent","relearn":"Repair shouldn't make your child comfort you; carry your own guilt, and let the apology be theirs.","hook":"After you snap, you start crying and your child rushes to console you.","options":[{"text":"Steady yourself, thank them, turn the warmth back to them","consequence":"They stay the child and still get the repair.","outcome":"repair","best":true},{"text":"Let them comfort you and call the apology done","consequence":"Leaning on the child flips the roles, skips theirs."}],"debrief":"A child shouldn't manage your feelings; steady yourself, then make the repair about reconnecting with them."},
  {"id":"bc-1271","cat":"the-repair","type":"branch","persona":"Suresh","source":"broke a promise repair","relearn":"When you break a promise, name it, apologise, and set a real new plan; pretending erodes trust.","hook":"You promised to take your daughter to the park, then cancelled in a bad mood.","options":[{"text":"Name the broken promise, apologise, set a real new time","consequence":"She learns promises matter and you make it right.","outcome":"repair","best":true},{"text":"Act like you never promised, hope she forgets","consequence":"Denying it teaches her not to trust your word."}],"debrief":"A broken promise is a rupture too; owning it and setting a realistic new plan repairs the trust."},
  {"id":"bc-1272","cat":"the-repair","type":"branch","persona":"Divya","source":"slip after a sleepless night","relearn":"Exhaustion explains a snap but doesn't cancel the repair; rest if you can, then reconnect.","hook":"Running on no sleep, you snapped at your baby and now feel like a failure.","options":[{"text":"Forgive the tiredness, rest if you can, repair gently","consequence":"You meet your limit with kindness and still reconnect.","outcome":"repair","best":true},{"text":"Spiral that exhaustion proves you're a bad mother","consequence":"Self-blame drains the energy repair needs."}],"debrief":"Exhaustion is a reason, not a verdict; be gentle with yourself, then reconnect when you can."},
  {"id":"bc-1273","cat":"the-repair","type":"branch","persona":"Vikram","source":"co-parent undermining repair","relearn":"Back up your partner's repair instead of undercutting it; a child needs both parents, not a split.","hook":"Your partner just apologised to your child; you think apologising is soft.","options":[{"text":"Back her up and let the repair stand","consequence":"The child sees both parents value owning a slip.","outcome":"repair","best":true},{"text":"Tell the child she didn't need to apologise","consequence":"Undermining her repair splits the parenting front."}],"debrief":"When one parent repairs, the other backs it up; a united front teaches your child that owning a slip is normal and strong."},
  {"id":"bc-1274","cat":"the-repair","type":"branch","persona":"any","source":"repair after harsh words on marks","relearn":"After harsh words about marks, take the word back and separate marks from worth; then talk study calmly.","hook":"You called your child 'useless' over a poor test result and saw their face fall.","options":[{"text":"Take the word back; separate their marks from their worth","consequence":"They learn one bad test doesn't make them worthless.","outcome":"repair","best":true},{"text":"Stand by it, hoping harsh words scare them to study","consequence":"Shaming over marks wounds self-worth, rarely helps."}],"debrief":"A child is never their marks; take back the harsh word, repair the bond, then talk study calmly."},
  {"id":"bc-1275","cat":"the-repair","type":"branch","persona":"Suresh","source":"raised hand then stopped","relearn":"Catching yourself before hitting is real progress; reassure the child and own it. If the urge feels close, get help — Tele-MANAS 14416.","hook":"You raised your hand to hit, caught yourself, and your child looks frightened.","options":[{"text":"Lower your hand, breathe, reassure them, own it","consequence":"They feel safe; you honour the pause that saved it.","outcome":"repair","best":true},{"text":"Say they're lucky you stopped, so behave","consequence":"Turning the pause into a threat teaches fear."}],"debrief":"Catching yourself before hitting is hard-won; reassure the child, own it, and protect that growing gap."},
  {"id":"bc-1276","cat":"the-repair","type":"branch","persona":"Divya","source":"over-apologising grovelling","relearn":"One clear, calm sorry repairs; grovelling on burdens the child. Own it simply, then return to warmth.","hook":"You feel so guilty you keep apologising over and over, and your child looks overwhelmed.","options":[{"text":"Give one clear, calm apology, then return to warmth","consequence":"They get the repair without carrying your guilt.","outcome":"repair","best":true},{"text":"Keep apologising all day to feel better yourself","consequence":"Endless apologies make the child manage your guilt."}],"debrief":"Repair is one honest sorry and a return to warmth, not a guilt performance; say it once and let it land."},
  {"id":"bc-1277","cat":"the-repair","type":"branch","persona":"any","source":"repair days later still counts","relearn":"Even days later a repair matters; name the old moment, own it, and reconnect.","hook":"It's been three days since you snapped and you never circled back.","options":[{"text":"Bring it up gently now, own it, reconnect","consequence":"They learn it's never too late to make it right.","outcome":"repair","best":true},{"text":"Decide too much time has passed to matter now","consequence":"'Too late' leaves a rupture the child still carries."}],"debrief":"A delayed repair still heals; gently name the moment, own your part, and reconnect, even days on."},
  {"id":"bc-1278","cat":"the-repair","type":"branch","persona":"Vikram","source":"model repair when child snaps","relearn":"When your child repairs on their own, notice it warmly; praising it grows the habit you've modelled.","hook":"Your child shouted at their sibling, then came back and said sorry on their own.","options":[{"text":"Warmly notice they came back and made it right","consequence":"They learn repairing is valued, worth doing again.","outcome":"repair","best":true},{"text":"Ignore the sorry, keep scolding the original shout","consequence":"Overlooking their repair teaches it earns nothing."}],"debrief":"Children learn repair by being noticed for it; when your child owns a slip, let them know it counts."},
  {"id":"bc-1279","cat":"the-repair","type":"role-play","persona":"Divya","source":"name the feeling repair","relearn":"Naming your feeling while owning the snap helps a child make sense of it without taking the blame.","hook":"You want to repair by naming what you felt, without making it your child's job to fix.","setup":"Name it and own it:","yourLine":[{"text":"\"I felt overwhelmed and I shouted, and that wasn't your fault; I'm sorry, my love.\"","best":true},{"text":"\"You see how upset you make me when you don't listen?\""}]},
  {"id":"bc-1280","cat":"the-repair","type":"role-play","persona":"Suresh","source":"repair the silence","relearn":"Breaking your own silence with warmth repairs the withdrawal; one quiet, kind opener tells the child the cold spell is over.","hook":"You've been cold and silent with your son since yesterday; you want to break it gently.","setup":"Reopen the warmth:","yourLine":[{"text":"\"I've been quiet and that wasn't fair to you; come here, I've missed you, let's start fresh.\"","best":true},{"text":"\"Have you learned your lesson yet? Then we can talk.\""}]},
  {"id":"bc-1281","cat":"the-repair","type":"role-play","persona":"any","source":"repair without grovelling","relearn":"A simple, steady apology that holds the limit repairs without grovelling or undoing the boundary you set.","hook":"You snapped while enforcing a fair rule; you want to repair the tone but keep the limit.","setup":"Repair the tone, keep the limit:","yourLine":[{"text":"\"I'm sorry I shouted; that was too harsh. The rule still stands, but I love you and we're okay.\"","best":true},{"text":"\"Fine, forget the rule, just stop crying, I can't take it.\""}]},
  {"id":"bc-1282","cat":"the-repair","type":"role-play","persona":"Vikram","source":"repair a broken promise words","relearn":"Owning a broken promise plainly and offering a real new plan repairs the trust better than excuses.","hook":"You bailed on a promised outing; you want to make it right honestly.","setup":"Own the broken promise:","yourLine":[{"text":"\"I promised and I let you down; that's on me, not you. Saturday morning, just us two, I mean it.\"","best":true},{"text":"\"Something came up, these things happen, don't make a big deal of it.\""}]},
  {"id":"bc-1283","cat":"the-repair","type":"role-play","persona":"Divya","source":"repair after harsh marks words","relearn":"Taking back a harsh word about marks and reaffirming the child's worth separates a result from who they are.","hook":"You called your daughter 'hopeless' over her marks; you want to take it back.","setup":"Take back the harsh word:","yourLine":[{"text":"\"I called you hopeless and that was wrong; you're not your marks, and I'm proud of who you are.\"","best":true},{"text":"\"Well, prove me wrong next time and I won't have to say it.\""}]},
  {"id":"bc-1284","cat":"the-repair","type":"role-play","persona":"Suresh","source":"repair to a teenager","relearn":"With a teen, a respectful, blame-free apology that doesn't demand instant forgiveness keeps the door open.","hook":"You embarrassed your teenager by yelling in front of their friend; you want to repair.","setup":"Repair, respecting their space:","yourLine":[{"text":"\"I shouldn't have yelled at you in front of your friend; I'm sorry. Take your time, I'm here when you're ready.\"","best":true},{"text":"\"You should be used to it by now; anyway, forget it.\""}]},
  {"id":"bc-1285","cat":"the-repair","type":"role-play","persona":"any","source":"repair invites child voice","relearn":"A repair that invites the child to say how it felt, and listens, deepens the reconnection.","hook":"After owning your snap, you want to make space for how your child felt.","setup":"Invite their side:","yourLine":[{"text":"\"I'm sorry, and I want to hear how that felt for you; I'll just listen.\"","best":true},{"text":"\"I said sorry, so there's nothing more to talk about.\""}]},
  {"id":"bc-1286","cat":"the-repair","type":"role-play","persona":"Divya","source":"repair with a non-verbal baby","relearn":"With a baby, a soft voice, gentle holding and calm presence are the repair; they read your tone long before words.","hook":"You raised your voice near your six-month-old, who startled and cried.","setup":"Soothe and reconnect:","yourLine":[{"text":"\"Shh, I'm here, that was too loud, wasn't it? I've got you, you're safe now.\"","best":true},{"text":"\"Stop crying, it wasn't even that loud.\""}]},
  {"id":"bc-1287","cat":"the-repair","type":"match","persona":"any","source":"repair phrase to what it does","relearn":"Each piece of a repair does a job: owning the act, lifting the blame, restoring safety, holding the limit, reconnecting.","hook":"Match each repair line to what it does for the child.","pairs":[{"left":"\"I shouldn't have shouted\"","right":"Owns the behaviour"},{"left":"\"It wasn't your fault\"","right":"Lifts the blame off them"},{"left":"\"You're safe with me\"","right":"Restores their security"},{"left":"\"The rule still stands\"","right":"Keeps the limit firm"},{"left":"\"Come here for a cuddle\"","right":"Reconnects the bond"}]},
  {"id":"bc-1288","cat":"the-repair","type":"match","persona":"any","source":"rupture to its repair","relearn":"Different ruptures need fitting repairs: a shout, a broken promise, a harsh label, withdrawal, and an unfair blame.","hook":"Match each rupture to the repair it needs.","pairs":[{"left":"You shouted in anger","right":"Own the shout and reassure them"},{"left":"You broke a promise","right":"Apologise and set a real new plan"},{"left":"You called them a harsh name","right":"Take the word back and affirm their worth"},{"left":"You went cold and silent","right":"Reopen with warmth and start fresh"},{"left":"You blamed them for your reaction","right":"Say clearly the reaction was yours"}]},
  {"id":"bc-1289","cat":"the-repair","type":"match","persona":"any","source":"clean vs blaming apology","relearn":"A clean apology owns your part; a blaming one shifts fault to the child. The wording is what makes the difference.","hook":"Match each opener to whether it owns or shifts the fault.","pairs":[{"left":"\"I was wrong to shout\"","right":"Owns your part"},{"left":"\"Sorry, but you pushed me to it\"","right":"Shifts fault to the child"},{"left":"\"That wasn't okay of me\"","right":"Takes responsibility"},{"left":"\"I only reacted because of you\"","right":"Blames the child"},{"left":"\"It wasn't your fault\"","right":"Frees them of blame"}]},
  {"id":"bc-1290","cat":"the-repair","type":"match","persona":"Suresh","source":"timing of repair","relearn":"Repair has a rhythm: pause when hot, reconnect when calm, keep it simple, and let it go once it's done.","hook":"Match each moment to the right repair move.","pairs":[{"left":"You're still furious","right":"Wait, don't repair yet"},{"left":"You've both calmed down","right":"Go back and reconnect"},{"left":"You've said a clear sorry","right":"Let it rest, don't over-repeat"},{"left":"Days have passed, still unsaid","right":"Bring it up gently now"},{"left":"Mid-meltdown screaming","right":"Stay near, wait for the lull"}]},
  {"id":"bc-1291","cat":"the-repair","type":"match","persona":"Divya","source":"guilt reframed to action","relearn":"Guilt can be turned into a useful step: noticing, owning, reconnecting, and self-forgiving so you can keep going.","hook":"Match each guilty thought to the kinder action underneath it.","pairs":[{"left":"\"I've ruined everything\"","right":"Repair what just happened"},{"left":"\"I'm a terrible mother\"","right":"Be as kind to yourself as to her"},{"left":"\"It's too late now\"","right":"Reconnect, it rarely is"},{"left":"\"I must punish myself\"","right":"Forgive yourself and continue"},{"left":"\"I can never slip again\"","right":"Expect slips, plan to repair"}]},
  {"id":"bc-1292","cat":"the-repair","type":"match","persona":"any","source":"what child learns from repair","relearn":"Watching a parent repair teaches a child lasting lessons: accountability, that love survives conflict, and how to apologise.","hook":"Match each repair you model to what your child takes from it.","pairs":[{"left":"You own your mistake aloud","right":"Mistakes can be admitted"},{"left":"You reconnect after a fight","right":"Love survives conflict"},{"left":"You apologise sincerely","right":"How to say a real sorry"},{"left":"You forgive yourself","right":"Self-kindness after slipping"},{"left":"You keep the limit kindly","right":"Boundaries and warmth coexist"}]},
  {"id":"bc-1293","cat":"the-repair","type":"match","persona":"Vikram","source":"fake vs real repair gestures","relearn":"Some gestures look like repair but dodge it; a real repair uses words and reconnection, not bribes or pressure.","hook":"Match each move to what it really is.","pairs":[{"left":"Buying a toy, saying nothing","right":"Looks like repair, dodges it"},{"left":"\"Say you forgive me, now\"","right":"Pressures, doesn't heal"},{"left":"Owning it and reconnecting","right":"A true repair"},{"left":"\"Let's just forget it happened\"","right":"Avoids the repair"},{"left":"A calm sorry and a hug","right":"Also a true repair"}]},
  {"id":"bc-1294","cat":"the-repair","type":"reflect","persona":"any","source":"repair you never got","relearn":"Maybe no one ever circled back to repair with you; choosing to repair with your child gives them what you missed.","hook":"Lensy: maybe no one ever came back to make it right with you as a child. Offering that to your own child now?","prompt":"What stirs in you?","options":["I want to give that","It matters","Something I missed"],"affirm":"Choosing to repair with your child offers them the very thing you may never have received, and that is how a cycle ends."},
  {"id":"bc-1295","cat":"the-repair","type":"reflect","persona":"Divya","source":"self-forgiveness in repair","relearn":"You can hold yourself with the same gentleness you'd want your child to feel; forgiving yourself is part of the repair.","hook":"Lensy: the kindness you offer your child after a slip, you're allowed to offer yourself too. Can you?","prompt":"How does that sit?","options":["I can try","I'm too hard on myself","Worth practising"],"affirm":"Forgiving yourself after a slip isn't letting yourself off; it frees the energy you need to go back and reconnect."},
  {"id":"bc-1296","cat":"the-repair","type":"reflect","persona":"any","source":"repair is courage","relearn":"Going back to own a slip takes courage, especially if you were never shown how; that courage is worth honouring.","hook":"Lensy: going back to say 'I was wrong' takes real courage, more if no one modelled it for you. Feel that?","prompt":"What's your take?","options":["It does take courage","Honour that","Hard but worth it"],"affirm":"Choosing to repair when you were never shown how is quiet courage, and every time you do it, the next time gets easier."},
  {"id":"bc-1297","cat":"the-repair","type":"reflect","persona":"Suresh","source":"repair over being right","relearn":"You can value the connection over winning the moment; choosing repair over being right keeps the bond whole.","hook":"Lensy: sometimes the bond matters more than proving you were right. Can you let connection win?","prompt":"Where do you land?","options":["Connection wins","Still learning","Worth choosing"],"affirm":"Choosing to repair instead of insisting you were right tells your child the relationship matters more than winning, and that lasts."},
  {"id":"bc-1298","cat":"the-repair","type":"reflect","persona":"any","source":"small repairs add up","relearn":"You don't need one grand repair; small, consistent reconnections after ordinary slips are what build security.","hook":"Lensy: it's the small, everyday 'I'm sorry, let's start over' moments that build a secure child, not grand gestures. True for you?","prompt":"What do you feel?","options":["The small ones count","Reassuring","I can do small"],"affirm":"Security is built from many small repairs, not one perfect one; each ordinary 'let's start over' quietly adds up."},
  {"id":"bc-1299","cat":"the-repair","type":"reflect","persona":"Divya","source":"repair frees you from spiral","relearn":"A repair can be the off-ramp from a guilt spiral; doing the small kind thing breaks the loop better than ruminating.","hook":"Lensy: when guilt loops, a small repair can be the way out of the spiral, not deeper into it. Does that help?","prompt":"How does that land?","options":["That helps","A way out","I'll reach for it"],"affirm":"When guilt starts to spiral, reaching for a small repair gives the feeling somewhere to go, and quietly ends the loop."},
  {"id":"bc-1300","cat":"the-repair","type":"reflect","persona":"any","source":"repair you can start now","relearn":"There's likely a small rupture you could repair today; it's almost never too late to gently reconnect.","hook":"Lensy: is there a small moment from this week you could still circle back and repair? It's rarely too late.","prompt":"What comes to mind?","options":["There is one","I'll go back","Good to remember"],"affirm":"If a small rupture comes to mind, it's rarely too late to gently circle back; reconnection restores trust whenever it's offered."},
  {"id":"bc-1301","cat":"the-repair","type":"reflect","persona":"Suresh","source":"repair the silence pattern","relearn":"If silence was your family's way, breaking it with a few warm words is a real repair, even if it feels unfamiliar.","hook":"Lensy: if your home went silent after conflict, choosing a few warm words instead is its own kind of repair. Can you try it?","prompt":"What stirs?","options":["I can try","Unfamiliar but right","Worth breaking"],"affirm":"Breaking an inherited silence with a little warmth is a genuine repair; unfamiliar at first, it teaches your child that conflict can end in reconnection."},
  {"id":"bc-1302","cat":"the-repair","type":"spot","persona":"any","source":"spot fake repairs","relearn":"A real repair owns the slip and reconnects; blaming the child or buying them off only looks like repair.","hook":"Spot the two lines that look like a repair but actually dodge it.","scene":[{"id":"a","text":"\"I'm sorry I shouted, that wasn't okay\"","trick":false},{"id":"b","text":"\"Sorry, but you made me lose it\"","trick":true},{"id":"c","text":"\"It wasn't your fault, come here\"","trick":false},{"id":"d","text":"\"Here's a chocolate, now we're fine\"","trick":true},{"id":"e","text":"\"You're safe with me, let's start over\"","trick":false}],"why":"'Sorry, but you made me' shifts the blame, and buying them off skips the words; neither owns the slip or truly reconnects."},
  {"id":"bc-1303","cat":"the-repair","type":"spot","persona":"Suresh","source":"spot blame-shifting repair","relearn":"A repair that owns your reaction heals; one that hands the child the fault for it does not.","hook":"Spot the two apologies that secretly blame the child.","scene":[{"id":"a","text":"\"I was wrong to snap at you\"","trick":false},{"id":"b","text":"\"I only shouted because you provoked me\"","trick":true},{"id":"c","text":"\"That was on me, not on you\"","trick":false},{"id":"d","text":"\"If you'd behaved, I'd never have lost it\"","trick":true},{"id":"e","text":"\"I'm sorry, you didn't deserve that tone\"","trick":false}],"why":"'You provoked me' and 'if you'd behaved' both hand the child the blame for your reaction, which is not repair."},
  {"id":"bc-1304","cat":"the-repair","type":"spot","persona":"Divya","source":"spot guilt-driven over-repair","relearn":"A clean, simple repair heals; guilt-driven grovelling or making the child reassure you burdens them instead.","hook":"Spot the two moves where your guilt becomes the child's burden.","scene":[{"id":"a","text":"One calm, clear 'I'm sorry'","trick":false},{"id":"b","text":"Apologising over and over for hours","trick":true},{"id":"c","text":"A warm cuddle and starting fresh","trick":false},{"id":"d","text":"\"Tell me you forgive me, please, again\"","trick":true},{"id":"e","text":"Letting the moment rest once it's said","trick":false}],"why":"Apologising for hours and pressing the child to keep forgiving you turn your guilt into something they must carry."},
  {"id":"bc-1305","cat":"the-repair","type":"spot","persona":"any","source":"spot repair that keeps limit","relearn":"A good repair mends the tone without dropping the limit; caving on the rule to stop the tears isn't repair.","hook":"Spot the two moves that drop the limit instead of repairing the tone.","scene":[{"id":"a","text":"\"Sorry I was harsh; the rule still stands\"","trick":false},{"id":"b","text":"\"Fine, forget the rule, just stop crying\"","trick":true},{"id":"c","text":"\"I love you, and bedtime is still bedtime\"","trick":false},{"id":"d","text":"\"Have the sweets, I can't bear you upset\"","trick":true},{"id":"e","text":"\"That tone was too sharp, I'm sorry\"","trick":false}],"why":"Dropping the rule or handing over sweets to end the tears caves the limit; repair mends the tone and holds it."},
  {"id":"bc-1306","cat":"the-repair","type":"spot","persona":"any","source":"spot avoidance disguised as repair","relearn":"Avoiding the rupture isn't the same as repairing it; pretending, rushing past, or silencing the child all dodge the repair.","hook":"Spot the two lines that avoid the repair rather than make it.","scene":[{"id":"a","text":"\"Let's talk about what happened earlier\"","trick":false},{"id":"b","text":"\"Nothing happened, stop bringing it up\"","trick":true},{"id":"c","text":"\"I want to make this right with you\"","trick":false},{"id":"d","text":"\"Enough now, we're not discussing it\"","trick":true},{"id":"e","text":"\"How did that feel for you? I'll listen\"","trick":false}],"why":"Denying it happened and shutting down the talk both avoid the rupture; repair means opening it, not closing it off."},
  {"id":"bc-1307","cat":"the-repair","type":"spot","persona":"Vikram","source":"spot undermining co-parent repair","relearn":"Backing your partner's repair strengthens it; undercutting or mocking it splits the front and teaches the child apologies are weak.","hook":"Spot the two reactions that undermine your partner's repair.","scene":[{"id":"a","text":"\"Mum's right to say sorry, that was fair\"","trick":false},{"id":"b","text":"\"You didn't need to apologise to him\"","trick":true},{"id":"c","text":"Standing quietly beside her repair","trick":false},{"id":"d","text":"Rolling your eyes at her apology","trick":true},{"id":"e","text":"\"We both got it wrong; we're sorry\"","trick":false}],"why":"Telling her she didn't need to apologise and mocking her apology both undermine the repair and split the parenting front."},
  {"id":"bc-1308","cat":"the-repair","type":"spot","persona":"Suresh","source":"spot repair after near-hit","relearn":"After a near-hit, calm reassurance repairs; threats or denying the child's fear don't. If the urge feels close, get help — Tele-MANAS 14416.","hook":"You stopped your hand in time; spot the two reactions that fail the child.","scene":[{"id":"a","text":"\"I nearly lost it; I'm sorry I scared you\"","trick":false},{"id":"b","text":"\"You're lucky I stopped, so behave\"","trick":true},{"id":"c","text":"Kneeling and reassuring them calmly","trick":false},{"id":"d","text":"\"Don't look at me like that, nothing happened\"","trick":true},{"id":"e","text":"\"You're safe; I'm working on this\"","trick":false}],"why":"A threat after the pause and denying their fear both fail the child; reassurance repairs."},
  {"id":"bc-1309","cat":"the-repair","type":"sort","persona":"any","source":"true repair vs doesnt heal","relearn":"A true repair owns it, lifts the blame and reconnects; blaming, bribing, denying or pressuring only looks like repair.","hook":"Sort each into a true repair or one that doesn't heal.","items":[{"id":"a","text":"\"I'm sorry I shouted, that wasn't okay\""},{"id":"b","text":"\"Sorry, but you made me do it\""},{"id":"c","text":"A warm cuddle and 'let's start over'"},{"id":"d","text":"Buying a toy and saying nothing"},{"id":"e","text":"\"It wasn't your fault, I love you\""},{"id":"f","text":"\"Forget it happened, stop sulking\""}],"bins":[{"id":"true","label":"True repair","valence":"pos"},{"id":"false","label":"Doesn't heal","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"}},
  {"id":"bc-1310","cat":"the-repair","type":"sort","persona":"Suresh","source":"repair timing right vs wrong","relearn":"Repair lands when you're both calm and stays simple; trying mid-rage, demanding instant calm, or grovelling on misfires.","hook":"Sort each into good repair timing or poor timing.","items":[{"id":"a","text":"Wait until you've both cooled down"},{"id":"b","text":"Apologise mid-rage, still shouting"},{"id":"c","text":"Reconnect gently once it's calm"},{"id":"d","text":"Demand the child calm down this instant"},{"id":"e","text":"Say one clear sorry, then let it rest"},{"id":"f","text":"Keep apologising on and on for hours"}],"bins":[{"id":"good","label":"Good timing","valence":"pos"},{"id":"poor","label":"Poor timing","valence":"neg"}],"key":{"a":"good","b":"poor","c":"good","d":"poor","e":"good","f":"poor"}},
  {"id":"bc-1311","cat":"the-repair","type":"sort","persona":"Divya","source":"guilt spiral vs repair action","relearn":"A guilt spiral keeps you stuck; turning the feeling into a small repair and self-forgiveness moves you forward.","hook":"Sort each into a guilt spiral or a forward repair step.","items":[{"id":"a","text":"\"I've ruined everything forever\""},{"id":"b","text":"Go back and reconnect gently"},{"id":"c","text":"\"I'm a terrible, hopeless mother\""},{"id":"d","text":"Forgive yourself and keep going"},{"id":"e","text":"Replay the moment all night"},{"id":"f","text":"Say one calm sorry, then let it rest"}],"bins":[{"id":"spiral","label":"Guilt spiral","valence":"neg"},{"id":"forward","label":"Forward repair","valence":"pos"}],"key":{"a":"spiral","b":"forward","c":"spiral","d":"forward","e":"spiral","f":"forward"}},
  {"id":"bc-1312","cat":"the-repair","type":"sort","persona":"any","source":"owns vs shifts blame","relearn":"A clean repair owns your reaction; a 'sorry but' or 'you made me' shifts the fault onto the child and doesn't heal.","hook":"Sort each apology by whether it owns your part or shifts the blame.","items":[{"id":"a","text":"\"I was wrong to snap\""},{"id":"b","text":"\"I only yelled because of you\""},{"id":"c","text":"\"That tone was on me, not you\""},{"id":"d","text":"\"You provoked me, so I reacted\""},{"id":"e","text":"\"It wasn't your fault at all\""},{"id":"f","text":"\"If you'd listened, I'd not have shouted\""}],"bins":[{"id":"owns","label":"Owns your part","valence":"pos"},{"id":"shifts","label":"Shifts the blame","valence":"neg"}],"key":{"a":"owns","b":"shifts","c":"owns","d":"shifts","e":"owns","f":"shifts"}},
  {"id":"bc-1313","cat":"the-repair","type":"sort","persona":"any","source":"helps child feel safe vs on edge","relearn":"Warmth, ownership and reassurance help a child feel safe after a rupture; denial, blame and the cold shoulder keep them on edge.","hook":"Sort each into helping the child feel safe again or keeping them on edge.","items":[{"id":"a","text":"A sincere apology and a cuddle"},{"id":"b","text":"Acting like nothing happened"},{"id":"c","text":"\"You're safe, I'm working on my temper\""},{"id":"d","text":"Making them apologise for your outburst"},{"id":"e","text":"Extra warmth and reassurance"},{"id":"f","text":"Days of cold silence afterward"}],"bins":[{"id":"safe","label":"Feels safe again","valence":"pos"},{"id":"edge","label":"Kept on edge","valence":"neg"}],"key":{"a":"safe","b":"edge","c":"safe","d":"edge","e":"safe","f":"edge"}},
  {"id":"bc-1314","cat":"the-repair","type":"sort","persona":"Vikram","source":"real repair vs avoidance","relearn":"Real repair opens the rupture and reconnects; avoidance denies it, rushes past it, or buys the child off without words.","hook":"Sort each into a real repair or avoiding the repair.","items":[{"id":"a","text":"\"Let's talk about earlier, I was wrong\""},{"id":"b","text":"\"Nothing happened, drop it\""},{"id":"c","text":"\"I want to make this right with you\""},{"id":"d","text":"Handing over a gift instead of words"},{"id":"e","text":"\"How did that feel? I'll just listen\""},{"id":"f","text":"Changing the subject to skip it"}],"bins":[{"id":"real","label":"Real repair","valence":"pos"},{"id":"avoid","label":"Avoiding it","valence":"neg"}],"key":{"a":"real","b":"avoid","c":"real","d":"avoid","e":"real","f":"avoid"}},
  {"id":"bc-1315","cat":"the-repair","type":"match","persona":"Divya","source":"repair tone signals","relearn":"After a hard moment, your softened voice, gentle eyes, open arms and slowed pace each signal safety to a child before words do.","hook":"Match each gentle cue after a snap to what it signals the child.","pairs":[{"left":"A softened, lower voice","right":"The danger has passed"},{"left":"Kneeling to their eye level","right":"You're meeting them, not looming"},{"left":"Open arms held out","right":"You're welcome back close"},{"left":"A slow, deep breath first","right":"You've steadied yourself"},{"left":"A warm, unhurried pace","right":"There's no rush, you're here"}]},
  {"id":"bc-1316","cat":"the-repair","type":"sort","persona":"any","source":"whose job in repair","relearn":"In a repair, owning the snap and reconnecting are the parent's job; a child should never have to apologise for your reaction or soothe your guilt.","hook":"Sort each into the parent's job in a repair or not the child's burden.","items":[{"id":"a","text":"Owning the snap that was yours"},{"id":"b","text":"The child apologising for your outburst"},{"id":"c","text":"Reaching out to reconnect first"},{"id":"d","text":"The child soothing your guilt"},{"id":"e","text":"Saying clearly it wasn't their fault"},{"id":"f","text":"The child having to forgive on demand"}],"bins":[{"id":"parent","label":"Parent's job","valence":"pos"},{"id":"notchild","label":"Not the child's burden","valence":"neg"}],"key":{"a":"parent","b":"notchild","c":"parent","d":"notchild","e":"parent","f":"notchild"}},
  {"id":"bc-1317","cat":"the-repair","type":"sort","persona":"Suresh","source":"repair vs makes it worse","relearn":"A calm sorry, reconnection and naming the feeling repair a rupture; revenge silence, threats and 'see what you made me do' make it worse.","hook":"Sort each into repairs the rupture or makes it worse.","items":[{"id":"a","text":"A calm, simple sorry"},{"id":"b","text":"Days of punishing silence"},{"id":"c","text":"Reconnecting with warmth"},{"id":"d","text":"\"See what you made me do\""},{"id":"e","text":"Naming the feeling, no blame"},{"id":"f","text":"\"Behave or there's more next time\""}],"bins":[{"id":"repairs","label":"Repairs the rupture","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"repairs","b":"worse","c":"repairs","d":"worse","e":"repairs","f":"worse"}},
  {"id":"bc-1350","cat":"tools-and-help","type":"branch","hook":"Anger is climbing and your toddler won't stop screaming. What's your move?","options":[{"text":"Say \"I need a minute\", put her somewhere safe, step out and breathe","consequence":"You break the surge before it acts; you both stay safe.","outcome":"step-away","best":true},{"text":"Stay in the room and try to win the shouting match","consequence":"Standing in the surge makes a slip likelier; stepping out first keeps everyone safe."}],"debrief":"When anger climbs, put your child somewhere safe, step away and breathe before you respond.","relearn":"Stepping away to calm down, child kept safe, is the caring move, not a failure.","persona":"Suresh","source":"step away safely"},
  {"id":"bc-1351","cat":"tools-and-help","type":"branch","hook":"Your own childhood keeps surfacing as rage you can't place. You want somewhere to take it.","options":[{"text":"Reach out to Tele-MANAS 14416 to talk through your own past","consequence":"You tend the old wound so less of it leaks onto your child.","outcome":"support","best":true},{"text":"Push it down and hope it stays buried","consequence":"Buried pain keeps leaking into your reactions; tending it stops the cycle."}],"debrief":"Old pain that drives your reactions can route to support, Tele-MANAS 14416.","relearn":"Heavy feelings from your past route to Tele-MANAS 14416; this is support, not therapy.","persona":"any","source":"route your past"},
  {"id":"bc-1352","cat":"tools-and-help","type":"branch","hook":"You're scared your anger could seriously hurt your child one of these days.","options":[{"text":"Get help now to keep them safe, see Be the Safe Adult","consequence":"You protect your child and find support before harm happens.","outcome":"safe-now","best":true},{"text":"Tell yourself it's not that bad and carry it alone","consequence":"Minimising a real risk leaves your child exposed; reaching for help is the caring act."}],"debrief":"If you fear real harm, reach for help now: Be the Safe Adult (g69), Childline 1098.","relearn":"When anger risks real harm, get help now; carrying it alone keeps the risk in place.","persona":"Suresh","source":"real-harm route"},
  {"id":"bc-1353","cat":"tools-and-help","type":"branch","hook":"You slipped and shouted at bedtime. The house is calm now. What do you do with it?","options":[{"text":"Go back, own it cleanly: \"I'm sorry I shouted, that wasn't your fault\"","consequence":"The repair reconnects you; that's what your child remembers.","outcome":"repair","best":true},{"text":"Say nothing and hope morning erases it","consequence":"Pretending it didn't happen leaves the rupture open; the repair is what heals it."}],"debrief":"Once you're both calm, go back and repair the slip; repair beats perfection.","relearn":"After a slip, the repair, owning it without blaming the child, counts most.","persona":"Divya","source":"repair tool"},
  {"id":"bc-1354","cat":"tools-and-help","type":"branch","hook":"You want one ready plan for heated moments instead of relying on willpower. What goes in it?","options":[{"text":"Pause, breathe, step away if needed, repair after, decided in advance","consequence":"You have a path ready before the storm hits.","outcome":"plan","best":true},{"text":"Just try harder to stay calm in the moment","consequence":"Willpower alone tends to fail mid-surge; a simple ready plan gives you a path."}],"debrief":"Decide your pause-breathe-step-away-repair plan in advance so it's ready in the heat.","relearn":"A simple plan readied in advance beats willpower alone, which often fails mid-surge.","persona":"any","source":"ready a plan"},
  {"id":"bc-1355","cat":"tools-and-help","type":"branch","hook":"It's been a hard week and you snapped twice. You're ready to call yourself a failure.","options":[{"text":"Name two calmer moments too, repair the slips, keep going","consequence":"You see real progress and stay in the change.","outcome":"keep-going","best":true},{"text":"Decide you'll never change and give up trying","consequence":"Quitting at a relapse ends the progress; slips are part of change, not proof it's impossible."}],"debrief":"Slips are part of changing; count the calmer moments, repair, and keep going.","relearn":"Each pause, each repair, each calmer day is real progress; a slip isn't proof you can't change.","persona":"Suresh","source":"progress not perfection"},
  {"id":"bc-1356","cat":"tools-and-help","type":"branch","hook":"A friend confides he hits his kids and feels trapped in it. How do you respond?","options":[{"text":"\"You were raised with that too; let's find you real support, no judgment\"","consequence":"He feels safe enough to reach for help.","outcome":"warm-route","best":true},{"text":"\"You're an abuser, what's wrong with you?\"","consequence":"Judgment makes him hide it; warmth plus a route opens the door to change."}],"debrief":"Meet a struggling parent with compassion plus a real route, Tele-MANAS 14416.","relearn":"Compassion, not condemnation, helps a trapped parent reach for help and change.","persona":"Priya","source":"help a parent"},
  {"id":"bc-1357","cat":"tools-and-help","type":"branch","hook":"Anger surges as you're driving the kids home. You can't step into another room.","options":[{"text":"Lower your voice, slow your breathing, deal with it once parked","consequence":"You keep everyone safe and handle it calmly after.","outcome":"adapt","best":true},{"text":"Let the anger out at full volume right there","consequence":"Venting full anger mid-drive isn't safe; slow your breath and address it once parked."}],"debrief":"When you can't step away, slow your breath and lower your voice; address it once it's safe.","relearn":"Calming tools adapt; when you can't leave the room, slow the breath first.","persona":"Vikram","source":"adapt the tool"},
  {"id":"bc-1358","cat":"tools-and-help","type":"match","hook":"Match each need to the route that fits it.","pairs":[{"left":"Your own past trauma resurfacing","right":"Tele-MANAS 14416"},{"left":"A child in immediate danger","right":"Childline 1098"},{"left":"A life-threatening emergency","right":"Emergency 112"},{"left":"Help owning full parenting","right":"Positive-parenting support"},{"left":"Routing a child to safety in-app","right":"Be the Safe Adult (g69)"}],"relearn":"Each need has a clear route: Tele-MANAS for your past, Childline for danger, 112 for emergencies.","persona":"any","source":"need to route"},
  {"id":"bc-1359","cat":"tools-and-help","type":"match","hook":"Match each hard moment to the tool that meets it.","pairs":[{"left":"The first rush of anger","right":"A few slow breaths"},{"left":"Close to losing it","right":"Step into another room"},{"left":"Just after you snapped","right":"A clean repair"},{"left":"A wound from your own past","right":"Reach for support"},{"left":"A heated day ahead","right":"A ready pause-plan"}],"relearn":"Slow breaths, stepping away, repair, support and a ready plan each fit a different hard moment.","persona":"Suresh","source":"moment to tool"},
  {"id":"bc-1360","cat":"tools-and-help","type":"match","hook":"Match each tool to what it actually does.","pairs":[{"left":"The pause-before-you-react step","right":"Stops a harmful reaction"},{"left":"The repair routine","right":"Heals a rupture afterward"},{"left":"Knowing your triggers","right":"Catches the old reflex early"},{"left":"Tending your own wounds","right":"Stops the cycle with you"},{"left":"Self-compassion on a slip","right":"Keeps you in the change"}],"relearn":"Each tool has a job: pause stops the reaction, repair heals, triggers warn, healing ends the cycle.","persona":"any","source":"tool to job"},
  {"id":"bc-1361","cat":"tools-and-help","type":"match","hook":"Match each calm-down step to when you'd use it.","pairs":[{"left":"Count five slow breaths","right":"The anger is just rising"},{"left":"Hand over to your partner","right":"You're close to your limit"},{"left":"Splash cold water","right":"You need to reset your body"},{"left":"Step onto the balcony","right":"You must leave the room safely"},{"left":"Name the feeling aloud","right":"You want to slow the surge"}],"relearn":"Breaths, a hand-over, cold water, stepping out and naming the feeling each suit a different stage.","persona":"Vikram","source":"step to moment"},
  {"id":"bc-1362","cat":"tools-and-help","type":"match","hook":"Match each part of a clean repair to its words.","pairs":[{"left":"Own what you did","right":"\"I shouted and that wasn't okay\""},{"left":"Clear the child of blame","right":"\"It wasn't your fault\""},{"left":"Reconnect","right":"\"I love you and I'm here\""},{"left":"Name what you'll try","right":"\"I'll take a breath next time\""},{"left":"Invite them back","right":"\"Shall we start the evening again?\""}],"relearn":"A clean repair owns it, clears the child of blame, reconnects, and names what you'll try next.","persona":"Divya","source":"repair in words"},
  {"id":"bc-1363","cat":"tools-and-help","type":"match","hook":"Match each co-parenting move to what it builds.","pairs":[{"left":"\"Let's choose differently together\"","right":"A shared plan"},{"left":"Backing each other in the moment","right":"A united front"},{"left":"A calm hand-over when you're spent","right":"A safety net"},{"left":"Agreeing no one hits, ever","right":"A clear family rule"},{"left":"Steadying a guilt-spiralling partner","right":"Room to repair"}],"relearn":"Choosing together, backing each other, calm hand-overs and a no-hitting rule build a steady home.","persona":"Vikram","source":"co-parent builds"},
  {"id":"bc-1364","cat":"tools-and-help","type":"match","hook":"Match each sign to the tool it calls for.","pairs":[{"left":"Jaw clenching, voice rising","right":"Pause and breathe now"},{"left":"You just slipped","right":"Plan your repair"},{"left":"The same trigger keeps firing","right":"Tend its root in support"},{"left":"You fear real harm","right":"Reach for help today"},{"left":"You managed a calm response","right":"Notice the progress"}],"relearn":"Read the sign and reach for its tool: pause, repair, support, urgent help, or noticing progress.","persona":"Suresh","source":"sign to tool"},
  {"id":"bc-1365","cat":"tools-and-help","type":"match","hook":"Match each worry a parent has to the reassurance that fits.","pairs":[{"left":"\"Needing help means I've failed\"","right":"It's the most caring thing you can do"},{"left":"\"One bad evening ruined it\"","right":"The repair is what they'll remember"},{"left":"\"My past has nothing to do with it\"","right":"Tending it protects your child"},{"left":"\"I'll never change\"","right":"Change is gradual; slips are part of it"},{"left":"\"Asking is shameful\"","right":"Reaching out is courageous, not shameful"}],"relearn":"Needing help isn't failure, repair beats one bad night, healing protects your child, change is gradual.","persona":"Priya","source":"worry to reassurance"},
  {"id":"bc-1366","cat":"tools-and-help","type":"match","hook":"Match each routine to the moment it belongs in.","pairs":[{"left":"The morning check-in","right":"Spot a heavy day early"},{"left":"The bedtime repair","right":"Close any rupture before sleep"},{"left":"The weekly reflect","right":"Count the calmer wins"},{"left":"The trigger note","right":"Learn what sets you off"},{"left":"The support call","right":"Tend what's too heavy alone"}],"relearn":"Small routines, a check-in, a repair, a reflect, a trigger note, a support call, keep the change alive.","persona":"any","source":"routine to moment"},
  {"id":"bc-1367","cat":"tools-and-help","type":"match","hook":"Match each escalation to the safe alternative.","pairs":[{"left":"Raising a hand","right":"Lower it and step back"},{"left":"Shouting to control","right":"Drop your volume, hold the limit"},{"left":"Shaming to motivate","right":"Name the behaviour, not the child"},{"left":"Cornering them in anger","right":"Give space, return when calm"},{"left":"Threatening to scare","right":"State a clear, kind consequence"}],"relearn":"Each harsh reflex has a firm-and-kind alternative that holds the limit without fear or harm.","persona":"Suresh","source":"reflex to alternative"},
  {"id":"bc-1368","cat":"tools-and-help","type":"match","hook":"Match each tool to the cycle it helps break.","pairs":[{"left":"The pause step","right":"The hitting reflex"},{"left":"Speaking up warmly","right":"The silent-treatment habit"},{"left":"A clean apology","right":"The never-admit-fault rule"},{"left":"Tending your wounds","right":"Old pain leaking onto your child"},{"left":"Asking for support","right":"Carrying it all alone"}],"relearn":"Each tool targets an inherited cycle: the pause, speaking up, apology, healing and asking for help.","persona":"Suresh","source":"tool to cycle"},
  {"id":"bc-1369","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Asking for help to parent more gently means I'm a weak or bad parent.\"","myth":{"un":"Asking for help to parent more gently means I'm a weak or bad parent.","re":"Reaching for help to parent more gently is one of the most caring, courageous things you can do.","why":"It puts your child first, never shameful."},"relearn":"Needing help to parent gently isn't weakness; it's a caring, courageous act for your child.","persona":"any","source":"help isn't weakness"},
  {"id":"bc-1370","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If I can't fix this on my own, there's no point reaching out.\"","myth":{"un":"If I can't fix this on my own, there's no point reaching out.","re":"Heavy feelings from your past can route to support like Tele-MANAS 14416; you don't have to carry it alone.","why":"Tended pain leaks less onto your child."},"relearn":"You don't have to fix it alone; support like Tele-MANAS 14416 helps you tend what's heavy.","persona":"Suresh","source":"not alone"},
  {"id":"bc-1371","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Stepping away when I'm furious means I'm abandoning my child.\"","myth":{"un":"Stepping away when I'm furious means I'm abandoning my child.","re":"Stepping away briefly, with your child kept safe, to calm down is a protective, caring move, not abandonment.","why":"It keeps the heated moment safe."},"relearn":"Stepping away to calm down, child kept safe, protects them; it isn't abandonment.","persona":"any","source":"stepping away protects"},
  {"id":"bc-1372","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's no tool for the heat of the moment; you just react.\"","myth":{"un":"There's no tool for the heat of the moment; you just react.","re":"A simple plan readied in advance, pause, breathe, step away if needed, repair after, gives you a path in the heat.","why":"A ready path beats raw willpower."},"relearn":"A pause-breathe-step-away-repair plan readied ahead gives you a path when anger surges.","persona":"any","source":"there is a tool"},
  {"id":"bc-1373","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Reaching out for my child's safety will only get my family in trouble.\"","myth":{"un":"Reaching out for my child's safety will only get my family in trouble.","re":"When you fear real harm, reaching out, Be the Safe Adult, Childline 1098, protects your child and gets you support.","why":"Safety and support come first."},"relearn":"If you fear real harm, reaching for help protects your child; it's support, not punishment.","persona":"Suresh","source":"safety not trouble"},
  {"id":"bc-1374","cat":"tools-and-help","type":"strike-rewrite","hook":"\"I've slipped again, so all my effort to change was pointless.\"","myth":{"un":"I've slipped again, so all my effort to change was pointless.","re":"Change is gradual and slips are part of it; each pause, each repair, each calmer day is real progress.","why":"Progress isn't all-or-nothing."},"relearn":"A slip doesn't erase your progress; each pause and repair is a real step in gradual change.","persona":"Suresh","source":"effort not pointless"},
  {"id":"bc-1375","cat":"tools-and-help","type":"strike-rewrite","hook":"\"My partner and I were both raised with hitting, so we're stuck with it.\"","myth":{"un":"My partner and I were both raised with hitting, so we're stuck with it.","re":"Co-parents can choose differently together and back each other up; the inheritance you share isn't a sentence.","why":"You can choose new patterns together."},"relearn":"Two parents raised with harsh discipline can still choose differently together and back each other up.","persona":"Vikram","source":"choose together"},
  {"id":"bc-1376","cat":"tools-and-help","type":"sort","hook":"Sort each move: a tool that helps break the cycle, or an old reflex to rethink?","items":[{"id":"a","text":"Pausing before you react"},{"id":"b","text":"Hitting when overwhelmed"},{"id":"c","text":"Repairing after a slip"},{"id":"d","text":"Shaming to control"},{"id":"e","text":"Reaching for support"},{"id":"f","text":"Carrying it alone in shame"}],"bins":[{"id":"tool","label":"Helpful tool","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"tool","b":"rethink","c":"tool","d":"rethink","e":"tool","f":"rethink"},"relearn":"Pausing, repairing and reaching for support help; hitting, shaming and isolating shame need a rethink.","persona":"any","source":"tool or rethink"},
  {"id":"bc-1377","cat":"tools-and-help","type":"sort","hook":"Sort each one: a realistic way to change, or a setup to fail?","items":[{"id":"a","text":"One small change at a time"},{"id":"b","text":"Becoming perfect overnight"},{"id":"c","text":"Self-compassion when you slip"},{"id":"d","text":"Quitting at the first relapse"},{"id":"e","text":"Counting your calmer days"},{"id":"f","text":"Shaming yourself harder"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"fail","label":"Setup to fail","valence":"neg"}],"key":{"a":"real","b":"fail","c":"real","d":"fail","e":"real","f":"fail"},"relearn":"Small changes, self-compassion and counting wins are realistic; perfectionism and self-shaming set you up to fail.","persona":"any","source":"realistic or fail"},
  {"id":"bc-1378","cat":"tools-and-help","type":"sort","hook":"Sort each situation: tend it yourself, or route it to outside help?","items":[{"id":"a","text":"A bedtime slip you can repair"},{"id":"b","text":"Your past trauma resurfacing hard"},{"id":"c","text":"A rising temper you can pause"},{"id":"d","text":"Fear you might really harm your child"},{"id":"e","text":"A trigger you can name and breathe through"},{"id":"f","text":"Pain too heavy to carry alone"}],"bins":[{"id":"self","label":"Tend yourself","valence":"pos"},{"id":"route","label":"Route to help","valence":"tell"}],"key":{"a":"self","b":"route","c":"self","d":"route","e":"self","f":"route"},"relearn":"You can repair slips and pause tempers yourself; deep trauma and real-harm fears route to help.","persona":"Suresh","source":"tend or route"},
  {"id":"bc-1379","cat":"tools-and-help","type":"sort","hook":"Sort each line said to a struggling parent: supportive, or shaming?","items":[{"id":"a","text":"\"You're already breaking the pattern by worrying\""},{"id":"b","text":"\"What kind of parent does that?\""},{"id":"c","text":"\"Let's find you real support\""},{"id":"d","text":"\"You've scarred them for life\""},{"id":"e","text":"\"You were raised with it; you can still choose new\""},{"id":"f","text":"\"You're an abuser\""}],"bins":[{"id":"support","label":"Supportive","valence":"pos"},{"id":"shame","label":"Shaming","valence":"neg"}],"key":{"a":"support","b":"shame","c":"support","d":"shame","e":"support","f":"shame"},"relearn":"Compassion and a real route help a struggling parent; verdicts and labels make them hide it.","persona":"Priya","source":"support or shame"},
  {"id":"bc-1380","cat":"tools-and-help","type":"sort","hook":"Sort each helpline use: the right route, or the wrong fit?","items":[{"id":"a","text":"Tele-MANAS 14416 for your own heavy past"},{"id":"b","text":"Childline 1098 for a child in danger"},{"id":"c","text":"Emergency 112 for a life-threatening crisis"},{"id":"d","text":"Tele-MANAS for a child being harmed right now"},{"id":"e","text":"Be the Safe Adult to route a child to safety"},{"id":"f","text":"112 just to vent your frustration"}],"bins":[{"id":"right","label":"Right route","valence":"pos"},{"id":"wrong","label":"Wrong fit","valence":"neg"}],"key":{"a":"right","b":"right","c":"right","d":"wrong","e":"right","f":"wrong"},"relearn":"Match the route: Tele-MANAS for your wellbeing, Childline 1098 and 112 for a child in danger.","persona":"any","source":"right route"},
  {"id":"bc-1381","cat":"tools-and-help","type":"sort","hook":"Sort each calm-down idea: it keeps the moment safe, or it makes it riskier?","items":[{"id":"a","text":"Stepping into another room to breathe"},{"id":"b","text":"Bottling it until you explode later"},{"id":"c","text":"Slowing your breath before you speak"},{"id":"d","text":"Drinking to numb the anger"},{"id":"e","text":"Handing over to your partner"},{"id":"f","text":"Driving fast to blow off steam"}],"bins":[{"id":"safe","label":"Keeps it safe","valence":"pos"},{"id":"risky","label":"Makes it riskier","valence":"uhoh"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Stepping away, slow breathing and handing over keep a heated moment safe; bottling, numbing and reckless venting don't.","persona":"Vikram","source":"safe or risky"},
  {"id":"bc-1382","cat":"tools-and-help","type":"sort","hook":"Sort each thing: it counts as real progress, or it's a myth about change?","items":[{"id":"a","text":"A calmer response you managed today"},{"id":"b","text":"\"If I slip once, I've failed\""},{"id":"c","text":"A slip you went back and repaired"},{"id":"d","text":"\"Real change happens overnight\""},{"id":"e","text":"Catching a trigger before it acted"},{"id":"f","text":"\"Wanting to change but slipping means it's hopeless\""}],"bins":[{"id":"progress","label":"Real progress","valence":"pos"},{"id":"myth","label":"A change-myth","valence":"neg"}],"key":{"a":"progress","b":"myth","c":"progress","d":"myth","e":"progress","f":"myth"},"relearn":"Calmer responses, repaired slips and caught triggers are real progress; all-or-nothing thinking is a myth.","persona":"any","source":"progress or myth"},
  {"id":"bc-1383","cat":"tools-and-help","type":"sort","hook":"Sort each co-parenting move: it builds a steady home, or it undermines one?","items":[{"id":"a","text":"\"Let's choose differently for our kid\""},{"id":"b","text":"\"You're just like your father\""},{"id":"c","text":"Backing each other up in the moment"},{"id":"d","text":"Undercutting your partner in front of the kids"},{"id":"e","text":"A calm hand-over when one of you is spent"},{"id":"f","text":"Keeping score of each other's slips"}],"bins":[{"id":"build","label":"Builds it","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"build","b":"undermine","c":"build","d":"undermine","e":"build","f":"undermine"},"relearn":"Choosing together, backing each other and calm hand-overs build a steady home; blame and scorekeeping erode it.","persona":"Vikram","source":"build or undermine"},
  {"id":"bc-1384","cat":"tools-and-help","type":"reflect","hook":"Lensy: reaching for help to parent more gently is brave, not shameful. Where do you feel that?","prompt":"What's alive for you?","options":["It's brave","Hard to ask","I want to try"],"affirm":"However it lands, reaching for help to parent more gently is a caring, courageous act, never shameful.","relearn":"Asking for help to parent gently is brave and caring; there's no shame in it.","persona":"any","source":"brave to ask"},
  {"id":"bc-1385","cat":"tools-and-help","type":"reflect","hook":"Lensy: think of one calm-down tool you could ready before the next hard evening. Picture it.","prompt":"Which feels yours?","options":["Slow breaths","Step away","Hand over"],"affirm":"Any of these is a real tool; readying one before the heat gives you a path when anger climbs.","relearn":"Choosing a calm-down tool in advance gives you a ready path for the next hard moment.","persona":"Suresh","source":"ready your tool"},
  {"id":"bc-1386","cat":"tools-and-help","type":"reflect","hook":"Lensy: change here is gradual, and slips are part of it. Sit with that for a moment.","prompt":"How does it land?","options":["A relief","Still hard","I can keep going"],"affirm":"Whatever you feel, each pause, each repair, each calmer day is real progress; you don't have to be perfect.","relearn":"Change is gradual and slips are part of it; progress, not perfection, is the goal.","persona":"any","source":"gradual change"},
  {"id":"bc-1387","cat":"tools-and-help","type":"reflect","hook":"Lensy: needing support for your own old pain isn't a flaw. Notice what comes up.","prompt":"What surfaces?","options":["Some resistance","Quiet relief","I'm curious"],"affirm":"Whatever surfaces is welcome; tending your own wounds, with support like Tele-MANAS 14416, is a gift to your child.","relearn":"Tending your own old pain, with support, is caring for your child, not a personal flaw.","persona":"any","source":"support not flaw"},
  {"id":"bc-1388","cat":"tools-and-help","type":"reflect","hook":"Lensy: you noticed the pattern, and noticing is where the power to choose begins. Feel that?","prompt":"What's your take?","options":["I feel it","Still early","I'm choosing"],"affirm":"However ready you feel, noticing the pattern is exactly where you regain the power to choose differently.","relearn":"Noticing the inherited pattern is the first step that gives you the power to choose differently.","persona":"any","source":"noticing is power"},
  {"id":"bc-1389","cat":"tools-and-help","type":"reflect","hook":"Lensy: the repair after a slip is what your child remembers most. Let that settle.","prompt":"What do you notice?","options":["That eases me","I want to repair","Good to know"],"affirm":"Wherever you are, going back to repair, owning it without blame, is what your child carries, not the slip.","relearn":"The repair after a slip, not the slip itself, is what your child remembers and learns from.","persona":"Divya","source":"repair remembered"},
  {"id":"bc-1390","cat":"tools-and-help","type":"reflect","hook":"Lensy: the cycle can end with you, one calmer choice at a time. How does that sit?","prompt":"What's stirring?","options":["It ends with me","One choice","Let's go"],"affirm":"However it stirs, noticing, repairing, healing and reaching for help are how the harmful cycle ends with you.","relearn":"Noticing, repairing, healing and asking for help are how the cycle ends with you, one choice at a time.","persona":"any","source":"ends with me"},
  {"id":"bc-1391","cat":"tools-and-help","type":"reflect","hook":"Lensy: you and your co-parent can choose new patterns together and back each other up. Picture it.","prompt":"What feels possible?","options":["We can try","One step","I'll start"],"affirm":"Whatever feels possible, choosing differently together and backing each other up makes the change far more likely to hold.","relearn":"Co-parents choosing new patterns together and backing each other up help the change hold.","persona":"Vikram","source":"together it holds"},
  {"id":"bc-1392","cat":"tools-and-help","type":"spot","hook":"In this calm-down plan, spot the two steps that would make a heated moment riskier.","scene":[{"id":"a","text":"Pause and take a few slow breaths","trick":false},{"id":"b","text":"Bottle it up until you explode later","trick":true},{"id":"c","text":"Step into another room if you can","trick":false},{"id":"d","text":"Numb the anger with a drink","trick":true},{"id":"e","text":"Repair with your child once you're calm","trick":false}],"why":"Bottling it up and numbing with a drink don't calm anger, they make a slip more likely; the other three keep the moment safe.","relearn":"Pausing, stepping away and repairing keep a moment safe; bottling and numbing make it riskier.","persona":"any","source":"spot risky steps"},
  {"id":"bc-1393","cat":"tools-and-help","type":"spot","hook":"A friend gives advice to a struggling parent. Spot the two lines that shame instead of help.","scene":[{"id":"a","text":"\"You're already breaking the pattern by worrying\"","trick":false},{"id":"b","text":"\"What's wrong with you as a parent?\"","trick":true},{"id":"c","text":"\"Let's find you real support, no judgment\"","trick":false},{"id":"d","text":"\"You've scarred them for life\"","trick":true},{"id":"e","text":"\"You were raised with it; you can still choose new\"","trick":false}],"why":"\"What's wrong with you\" and \"scarred for life\" shame the parent into hiding it; the other three offer compassion and a route.","relearn":"Compassion and a real route help a struggling parent; verdicts shame them.","persona":"Priya","source":"spot the shaming lines"},
  {"id":"bc-1394","cat":"tools-and-help","type":"spot","hook":"Here's how a parent talks about help. Spot the two beliefs that keep them stuck.","scene":[{"id":"a","text":"\"Reaching out is caring, not shameful\"","trick":false},{"id":"b","text":"\"If I can't fix it alone, there's no point\"","trick":true},{"id":"c","text":"\"Tele-MANAS 14416 can help with my past\"","trick":false},{"id":"d","text":"\"Asking for help means I'm a bad parent\"","trick":true},{"id":"e","text":"\"Slips are part of change, not the end\"","trick":false}],"why":"\"No point unless I fix it alone\" and \"asking means I'm bad\" keep a parent stuck; the other three open the door to support.","relearn":"Reaching for help is caring; the beliefs that asking is shameful or pointless keep a parent stuck.","persona":"Suresh","source":"spot stuck beliefs"},
  {"id":"bc-1395","cat":"tools-and-help","type":"spot","hook":"A parent is about to react in anger. Spot the two responses that aren't safe or kind.","scene":[{"id":"a","text":"Lower your voice and slow your breathing","trick":false},{"id":"b","text":"Raise a hand to make them listen","trick":true},{"id":"c","text":"Name the feeling and hold the limit","trick":false},{"id":"d","text":"Corner and shame them to scare them","trick":true},{"id":"e","text":"Step away to calm, child kept safe","trick":false}],"why":"Raising a hand and shaming to scare are harmful reflexes; lowering your voice, naming the feeling and stepping away are firm-and-kind.","relearn":"Firm-and-kind responses hold the limit safely; raising a hand or shaming to scare are reflexes to drop.","persona":"Suresh","source":"spot unsafe responses"},
  {"id":"bc-1396","cat":"tools-and-help","type":"spot","hook":"Spot the two routing choices that send a child-safety worry to the wrong place.","scene":[{"id":"a","text":"Child in danger → Childline 1098","trick":false},{"id":"b","text":"Child being harmed now → Tele-MANAS 14416","trick":true},{"id":"c","text":"Life-threatening crisis → emergency 112","trick":false},{"id":"d","text":"Route a child to safety → Be the Safe Adult","trick":false},{"id":"e","text":"A child in danger → just wait and see","trick":true}],"why":"Tele-MANAS is for your wellbeing, not a child being harmed, and \"wait and see\" leaves a child in danger; a child at risk goes to Childline 1098 or 112.","relearn":"A child in danger routes to Childline 1098 or 112, never Tele-MANAS.","persona":"any","source":"spot wrong routing"},
  {"id":"bc-1397","cat":"tools-and-help","type":"spot","hook":"A parent sums up their progress. Spot the two all-or-nothing thoughts dragging them down.","scene":[{"id":"a","text":"\"I managed two calmer evenings this week\"","trick":false},{"id":"b","text":"\"One slip means I've ruined everything\"","trick":true},{"id":"c","text":"\"I repaired the time I snapped\"","trick":false},{"id":"d","text":"\"If I'm not perfect, why bother\"","trick":true},{"id":"e","text":"\"I caught a trigger before it acted\"","trick":false}],"why":"\"One slip ruins everything\" and \"why bother if I'm not perfect\" are all-or-nothing traps; the other three are real progress.","relearn":"Calmer days, repairs and caught triggers are real progress; all-or-nothing thinking drags you down.","persona":"any","source":"spot all-or-nothing"},
  {"id":"bc-1398","cat":"tools-and-help","type":"spot","hook":"Two co-parents talk. Spot the two lines that undermine choosing differently together.","scene":[{"id":"a","text":"\"Let's back each other up on no hitting\"","trick":false},{"id":"b","text":"\"You're useless, just like your father\"","trick":true},{"id":"c","text":"\"Tap me in when you're at your limit\"","trick":false},{"id":"d","text":"\"I'll undercut you in front of the kids\"","trick":true},{"id":"e","text":"\"We were both raised with it; let's choose new\"","trick":false}],"why":"The insult and undercutting in front of the kids break the united front; the other three build it.","relearn":"Backing each other and choosing new patterns build a united front; insults break it.","persona":"Vikram","source":"spot undermining lines"},
  {"id":"bc-1399","cat":"tools-and-help","type":"role-play","hook":"Anger is surging and you need to step out for a minute. You tell your child what's happening.","setup":"Name it and step away:","yourLine":[{"text":"\"I'm getting too angry, so I'm taking a minute to breathe, then I'll be back.\"","best":true},{"text":"\"Get out of my sight before I lose it.\""}],"relearn":"Naming your anger and stepping away to breathe models self-control, far better than threatening your child.","persona":"Suresh","source":"name and step away"},
  {"id":"bc-1400","cat":"tools-and-help","type":"role-play","hook":"A close friend admits he hits his kids and feels ashamed. You want him to feel safe enough to get help.","setup":"Open the door, gently:","yourLine":[{"text":"\"You were raised with that too; you're not a monster. Let's find you some real support.\"","best":true},{"text":"\"I can't believe you'd do that. What's wrong with you?\""}],"relearn":"Meeting a struggling parent with compassion and a route to help opens the door that judgment slams shut.","persona":"Priya","source":"open the door"},
  {"id":"bc-1401","cat":"tools-and-help","type":"role-play","hook":"You're spent and your patience is gone. You ask your co-parent to take over before you snap.","setup":"Tap them in:","yourLine":[{"text":"\"I'm at my limit, can you take over for ten minutes? I need to reset.\"","best":true},{"text":"\"I'll just push through it.\""}],"relearn":"Asking your co-parent to tap in before you snap is a tool, not a failure; pushing through risks a slip.","persona":"Vikram","source":"tap in"},
  {"id":"bc-1402","cat":"tools-and-help","type":"role-play","hook":"You snapped and your child looks crushed. The room is calm now and you go to repair it.","setup":"Make the repair:","yourLine":[{"text":"\"I'm sorry I shouted. That wasn't okay and it wasn't your fault. I love you.\"","best":true},{"text":"\"I only shouted because you wouldn't listen.\""}],"relearn":"A clean repair owns your reaction without blaming the child; blaming them transfers your fault to them.","persona":"Divya","source":"clean repair"},
  {"id":"bc-1403","cat":"tools-and-help","type":"role-play","hook":"Your partner slipped and is spiralling in guilt. You want to steady them toward repair, not blame.","setup":"Steady them:","yourLine":[{"text":"\"You slipped, it happens to all of us. Go repair it with them, that's what matters now.\"","best":true},{"text":"\"Great, now you've gone and damaged them.\""}],"relearn":"Steadying a guilt-spiralling co-parent toward repair helps the child far more than piling on blame.","persona":"Vikram","source":"steady toward repair"},
  {"id":"bc-1404","cat":"tools-and-help","type":"role-play","hook":"Your teen asks why you grounded them for shouting when you yell too. You owe an honest answer.","setup":"Answer honestly:","yourLine":[{"text":"\"You're right that my yelling isn't fair either. I'm working on it, and I'll own it when I slip.\"","best":true},{"text":"\"Do as I say, not as I do.\""}],"relearn":"Admitting your own slips, instead of demanding obedience you don't model, earns the credibility kids actually follow.","persona":"Suresh","source":"own your slip"},
  {"id":"bc-1405","cat":"tools-and-help","type":"role-play","hook":"A relative tells you a slap will sort your son out. You want to hold your line, warmly.","setup":"Hold your line:","yourLine":[{"text":"\"I know that's how we grew up, but we're choosing a different way that works for us.\"","best":true},{"text":"\"Maybe you're right, I'll just hit him then.\""}],"relearn":"Holding your non-violent line with warmth, while honouring how you grew up, keeps you choosing differently.","persona":"Suresh","source":"hold your line"},
  {"id":"bc-1406","cat":"tools-and-help","type":"role-play","hook":"You're truly scared you might harm your child. You phone someone you trust to ask for help.","setup":"Ask for help:","yourLine":[{"text":"\"I'm scared of how angry I get with him. I need help to keep him safe. Can we talk?\"","best":true},{"text":"\"Everything's fine, forget I said anything.\""}],"relearn":"Asking for help when you fear harming your child is the bravest, most protective thing you can do.","persona":"Suresh","source":"ask before harm"},
  {"id":"bc-1407","cat":"tools-and-help","type":"role-play","hook":"You've been hard on yourself after a rough week. You try speaking to yourself the way you'd speak to a friend.","setup":"Be kind to yourself:","yourLine":[{"text":"\"I slipped, but I'm trying and repairing. That's real progress, and I can keep going.\"","best":true},{"text":"\"I'm a terrible parent and I'll never change.\""}],"relearn":"Self-compassion after a slip keeps you in the change; harsh self-talk only repeats the cycle inward.","persona":"any","source":"kind to yourself"},
  {"id":"bc-1408","cat":"tools-and-help","type":"role-play","hook":"Your co-parent snapped and smacked your son, then froze, ashamed. You want a calm next move, not blame.","setup":"Steady the moment:","yourLine":[{"text":"\"That scared us both. Let's step out, breathe, and go back and repair with him together.\"","best":true},{"text":"\"You're just like your father, you'll never change.\""}],"relearn":"Meeting a co-parent's lapse with a shared repair plan, not a verdict, turns one bad moment into a teachable recovery.","persona":"Vikram","source":"steady the moment"},
  {"id":"bc-1409","cat":"tools-and-help","type":"role-play","hook":"Your teenager calls out that you snapped unfairly. You choose to own it instead of defending.","setup":"Own it:","yourLine":[{"text":"\"You're right, I snapped and that wasn't fair to you. I'm sorry, let's start over.\"","best":true},{"text":"\"Don't you dare talk back to me.\""}],"relearn":"Owning a slip when your child names it models respect and strengthens your bond, never weakens your authority.","persona":"any","source":"own it with a teen"},
];

